const sleep = ms => new Promise(r => setTimeout(r, ms));
function cellAt(x,y){ if(x<0||x>=GRID_SIZE||y<0||y>=GRID_SIZE) return null; return Game.grid[y*GRID_SIZE+x]; }
function showScreen(name){ document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active')); const el=document.getElementById(name); if(el) el.classList.add('active'); Game.screen=name; }
function toast(msg){ const el=document.getElementById('toast'); if(!el) return; el.textContent=msg; el.classList.add('show'); clearTimeout(el._t); el._t=setTimeout(()=>el.classList.remove('show'),2400); }

