// ================= CHARACTER CREATION =================
let ccState = { className:'Hacker', background:'street' };

function renderCharCreate(){
  const classGrid = document.getElementById('cc-classes');
  classGrid.innerHTML = '';
  Object.keys(CLASS_DEFS).forEach(cn => {
    const def = CLASS_DEFS[cn];
    const el = document.createElement('div');
    el.className = 'cc-choice' + (ccState.className === cn ? ' selected' : '');
    el.innerHTML = `
      <div class="cc-port">${window.CRAssets?.classPortrait?.(cn,cn)||SPRITES[cn]}</div>
      <div class="cc-name" style="color:${def.color};">${cn}</div>
      <div class="cc-desc">${def.blurb}</div>
      <div class="cc-stats">HP ${def.hp} · DMG ${def.dmg} · ARM ${def.armor}</div>`;
    el.addEventListener('click', () => { ccState.className = cn; renderCharCreate(); });
    classGrid.appendChild(el);
  });

  const bgGrid = document.getElementById('cc-backgrounds');
  bgGrid.innerHTML = '';
  Object.keys(BACKGROUNDS).forEach(bn => {
    const b = BACKGROUNDS[bn];
    const el = document.createElement('div');
    el.className = 'cc-choice' + (ccState.background === bn ? ' selected' : '');
    el.innerHTML = `
      <div class="cc-name">${b.name}</div>
      <div class="cc-desc">${b.desc}</div>`;
    el.addEventListener('click', () => { ccState.background = bn; renderCharCreate(); });
    bgGrid.appendChild(el);
  });
}

document.getElementById('cc-go').addEventListener('click', () => {
  const name = (document.getElementById('cc-name').value || 'Vex').trim().slice(0,16);
  startNewGame(name, ccState.className, ccState.background);
});

// ================= NEW GAME =================
function startNewGame(name, className, background){
  Game.playerName = name;
  Game.playerClass = className;
  Game.background = background;
  Game.credits = 1500;
  Game.day = 1; Game.hour = 8;
  Game.rep = { meridian:0, wraiths:0, iron:0, chrome:0, spine:0 };
  Game.missionHistory = [];
  Game.journal = [];
  Game.storyFlags = {};
  Game.loadedFromSave = false;

  // Apply background rep
  const bg = BACKGROUNDS[background];
  if (bg.rep) Object.entries(bg.rep).forEach(([k,v]) => Game.rep[k] = v);

  // Create player
  const player = makeUnit(name, className, 1);
  applyBackground(player, bg);
  Game.roster = [player];

  // Hire starting companions
  Game.roster.push(makeUnit('Rook', 'Gunslinger', 1));
  Game.roster.push(makeUnit('Kage', 'Cyber Sword', 1));

  // World setup
  setupWorld();
  addJournal('story', 'The Beginning', 'You arrived in the city with nothing but a name and a debt. Time to make something of it.');
  saveGame(0); // autosave to slot 0

  // Play prologue story
  playStory('prologue');
}

function makeUnit(name, className, level){
  const def = CLASS_DEFS[className];
  const u = {
    name, className, level,
    maxHp: def.hp, hp: def.hp,
    maxAp: def.ap, ap: def.ap,
    move: def.move, range: def.range,
    damage: def.dmg, armor: def.armor,
    critChance: 5,
    weapon: def.w, armor_item: def.a,
    cyber: [],
    inventory: { medkit:2, stim:1, emp:1 },
    skills: [...def.abilities],
    skillPoints: 1,
    xp: 0, xpNext: 100
  };
  return u;
}

function applyBackground(u, bg){
  if (bg.stat.hp) u.maxHp += bg.stat.hp, u.hp += bg.stat.hp;
  if (bg.stat.armor) u.armor += bg.stat.armor;
  if (bg.stat.move) u.move += bg.stat.move;
  if (bg.stat.crit) u.critChance += bg.stat.crit;
  if (bg.stat.dmg) u.damage += bg.stat.dmg;
}

