// ================= MISSION GEN =================
function generateMissions(){
  const missionTemplates = [
    { type:'eliminate', name:'Eliminate Hostiles', desc:'Neutralize all hostiles.', enemies:['Guard','Guard','Heavy'], base:500 },
    { type:'extract',   name:'Extract Data',       desc:'Secure the node and clear the area.', enemies:['Guard','Drone','Drone','Enforcer'], base:600 },
    { type:'sabotage',  name:'Sabotage Node',      desc:'Destroy infrastructure.', enemies:['Enforcer','Guard','Heavy','Drone'], base:750 },
    { type:'bounty',    name:'Bounty Contract',    desc:'Hunt a high-value target.', enemies:['Enforcer','Enforcer','Heavy'], base:900 }
  ];

  const enemyFactionPool = {
    meridian: ['Guard','Enforcer','Drone'],
    wraiths:  ['Drone','Enforcer','Guard'],
    iron:     ['Guard','Heavy','Brute'],
    chrome:   ['Enforcer','Brute','Heavy'],
    spine:    ['Guard','Drone','Enforcer']
  };

  Game.contacts.forEach(c => {
    c.missions = [];
    const count = 2 + Math.floor(Math.random()*2);
    for (let i=0;i<count;i++){
      const t = missionTemplates[Math.floor(Math.random()*missionTemplates.length)];
      const diff = 1 + Math.floor(Math.random()*3);
      const targetFac = Object.keys(FACTIONS)[Math.floor(Math.random()*5)];
      c.missions.push({
        id:'m_'+c.id+'_'+i+'_'+Math.random().toString(36).slice(2,6),
        contact:c.id, type:t.type, name:t.name, desc:t.desc,
        enemies:[...t.enemies], diff,
        reward: t.base + diff*150 + Math.floor(Math.random()*200),
        xp: 60 + diff*30,
        targetFaction: targetFac,
        factionRepGain: 5 + diff*2,
        factionRepLoss: { [targetFac]: -(5 + diff*2) }
      });
    }
  });
}

