function triggerTravelEvent(){
  const ev = TRAVEL_EVENTS[Math.floor(Math.random()*TRAVEL_EVENTS.length)];
  const panel = document.getElementById('travel-event');
  document.getElementById('te-title').textContent = ev.title;
  document.getElementById('te-text').textContent = ev.text;
  const choicesEl = document.getElementById('te-choices');
  choicesEl.innerHTML = '';
  ev.choices.forEach(ch => {
    const btn = document.createElement('button');
    btn.className = 'btn';
    btn.textContent = ch.text;
    btn.addEventListener('click', () => {
      ch.effect();
      panel.classList.remove('open');
      updateOverworldHUD();
    });
    choicesEl.appendChild(btn);
  });
  panel.classList.add('open');
}

// ================= CONTACT PANEL =================
function openContactPanel(contact){
  document.getElementById('contact-name').textContent = contact.name;
  document.getElementById('contact-role').textContent = contact.role;
  const list = document.getElementById('contact-missions');
  list.innerHTML = '';
  if (contact.missions.length === 0){
    const div = document.createElement('div');
    div.style.cssText = 'color:#6fa8b8;font-size:11px;padding:6px;';
    div.textContent = 'No contracts available right now. Come back later.';
    list.appendChild(div);
  }
  contact.missions.forEach(m => {
    const el = document.createElement('div');
    el.className = 'mission';
    el.innerHTML = `
      <div class="m-title">${m.name}</div>
      <div class="m-meta">
        <span class="reward">¢ ${m.reward}</span>
        <span class="diff">DIFF ${'▮'.repeat(m.diff)}${'▯'.repeat(3-m.diff)}</span>
        <span>XP ${m.xp}</span>
        <span class="fac">vs ${FACTIONS[m.targetFaction].short}</span>
      </div>
      <div class="m-desc">${m.desc}</div>`;
    el.addEventListener('click', () => startMission(m));
    list.appendChild(el);
  });
  document.getElementById('contact-panel').classList.add('open');
}
document.getElementById('contact-close').addEventListener('click', () => document.getElementById('contact-panel').classList.remove('open'));

// ================= VENDOR =================
function openVendor(vendor){
  Game.vendorCurrent = vendor;
  document.getElementById('vendor-title').textContent = vendor.name;
  document.getElementById('vendor-cr').innerHTML = `¢ <b style="color:#ffaa00">${Game.credits.toLocaleString()}</b>`;
  const grid = document.getElementById('vendor-grid');
  grid.innerHTML = '';
  // Discount based on reputation with faction
  const fac = (vendor.type === 'weapon' && vendor.id === 'v_gun') ? 'iron' :
              (vendor.type === 'armor') ? 'meridian' :
              (vendor.type === 'cyber') ? 'chrome' : 'spine';
  const rep = Game.rep[fac] || 0;
  const discount = rep > 50 ? 0.8 : rep > 20 ? 0.9 : rep < -20 ? 1.2 : 1;

  vendor.stock.forEach(itemKey => {
    const item = ITEMS[itemKey];
    let price = 0;
    if (item.type === 'weapon') price = WEAPON_PRICES[itemKey] || 300;
    else if (item.type === 'armor') price = ARMOR_PRICES[itemKey] || 400;
    else if (item.type === 'cyber') price = CYBER_PRICES[itemKey] || 1000;
    else price = item.price || 100;
    price = Math.round(price * discount * (1 - Math.min(0.20, Math.max(0, ((Game.safehouse?.workshop||1)-1)*0.05))));

    const el = document.createElement('div');
    el.className = 'vendor-item';
    el.innerHTML = `
      ${ICONS[item.icon]||''}
      <div class="vi-info">
        <div class="vi-name">${item.name}</div>
        <div class="vi-desc">${item.desc}</div>
        <div class="vi-price">¢ ${price}${discount !== 1 ? ` <span style="color:#8fa8b8;font-size:9px;">(${discount<1?'-':'+'}${Math.abs(Math.round((1-discount)*100))}%)</span>` : ''}</div>
      </div>`;
    el.addEventListener('click', () => purchaseItem(vendor, itemKey, price, item));
    grid.appendChild(el);
  });

  showScreen('vendor');
}

function purchaseItem(vendor, itemKey, price, item){
  if (Game.credits < price){ toast('Not enough credits.'); return; }
  Game.credits -= price;
  const target = Game.roster[Game.selectedCrewIndex] || Game.roster[0];
  if (item.type === 'consumable'){
    target.inventory[itemKey] = (target.inventory[itemKey]||0) + 1;
    toast(`Purchased ${item.name}.`);
  } else if (item.type === 'cyber'){
    if (target.cyber.includes(itemKey)){ toast('Already installed.'); Game.credits += price; return; }
    if (target.cyber.length >= 2){ toast('Max 2 cyberware.'); Game.credits += price; return; }
    target.cyber.push(itemKey);
    applySkillsToUnit(target);
    toast(`Installed ${item.name} on ${target.name}.`);
  } else {
    // weapon/armor - add to shared stash (equip on selected)
    if (item.type === 'weapon') target.weapon = itemKey;
    else target.armor_item = itemKey;
    applySkillsToUnit(target);
    toast(`${target.name} equips ${item.name}.`);
  }
  updateOverworldHUD();
  document.getElementById('vendor-cr').innerHTML = `¢ <b style="color:#ffaa00">${Game.credits.toLocaleString()}</b>`;
  saveGame(0);
}

document.getElementById('vendor-back-btn').addEventListener('click', () => { showScreen('overworld-screen'); });

// ================= FACTION SCREEN =================
document.getElementById('ov-fac-btn').addEventListener('click', () => { showScreen('faction-screen'); renderFactions(); });
document.getElementById('fac-back-btn').addEventListener('click', () => showScreen('overworld-screen'));

function renderFactions(){
  const body = document.getElementById('faction-body');
  body.innerHTML = '';
  Object.keys(FACTIONS).forEach(key => {
    const f = FACTIONS[key];
    const rep = Game.rep[key] || 0;
    const tier = rep >= 70 ? 'ALLY' : rep >= 30 ? 'FRIENDLY' : rep >= -10 ? 'NEUTRAL' : rep >= -50 ? 'HOSTILE' : 'KILL ON SIGHT';
    const tierColor = rep >= 70 ? '#00ff88' : rep >= 30 ? '#00f0ff' : rep >= -10 ? '#8fa8b8' : rep >= -50 ? '#ffaa00' : '#ff2244';
    const pct = Math.min(100, Math.abs(rep));
    const card = document.createElement('div');
    card.className = 'faction-card';
    card.style.borderLeftColor = f.color;
    card.innerHTML = `
      <div class="f-header">
        <div class="f-name" style="color:${f.color};text-shadow:0 0 6px ${f.color};">${f.name}</div>
        <div class="f-rep" style="color:${tierColor};">${rep > 0 ? '+' : ''}${rep}</div>
      </div>
      <div class="f-desc">${f.desc}</div>
      <div class="faction-bar">
        <i style="width:${rep>=0?50+pct/2:50-pct/2}%;background:${tierColor};box-shadow:0 0 8px ${tierColor};"></i>
        <div class="center"></div>
      </div>
      <div class="faction-tier">STATUS: <span style="color:${tierColor};">${tier}</span></div>`;
    body.appendChild(card);
  });
}

