function renderJournal(){
  const body = document.getElementById('journal-body');
  body.innerHTML = '';
  if (Game.journal.length === 0){
    body.innerHTML = '<div style="color:#6fa8b8;font-size:11px;padding:20px;text-align:center;">No journal entries yet.</div>';
    return;
  }
  Game.journal.forEach(j => {
    const el = document.createElement('div');
    el.className = 'journal-entry ' + (j.type === 'story' ? 'story' : j.type === 'main' ? 'main' : '');
    el.innerHTML = `
      <div class="je-title">${j.title}</div>
      <div class="je-desc">${j.desc.replace(/\n/g,'<br>')}</div>
      <div class="je-status">Day ${j.day}</div>`;
    body.appendChild(el);
  });
}

