document.getElementById('crew-back-btn').addEventListener('click', () => showScreen('overworld-screen'));
document.querySelectorAll('.tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));
    tab.classList.add('active');
    Game.crewTab = tab.dataset.tab;
    renderCrewScreen();
  });
});

function renderCrewScreen(){
  const body = document.getElementById('crew-body');
  if (Game.crewTab === 'roster') renderRoster(body);
  else if (Game.crewTab === 'skills') renderSkills(body);
  else if (Game.crewTab === 'inventory') renderInventory(body);
}

function renderRoster(body){
  body.innerHTML = '';
  Game.roster.forEach((u, i) => {
    const el = document.createElement('div');
    el.className = 'crew-card' + (i === Game.selectedCrewIndex ? ' active' : '');
    el.innerHTML = `
      <div class="crew-portrait">${window.CRAssets?.classPortrait?.(u.className,u.name)||SPRITES[u.className]}</div>
      <div class="crew-info">
        <div class="crew-name">${u.name}</div>
        <div class="crew-class">${u.className} · LVL ${u.level}</div>
        <div class="crew-stats">
          <span>HP <b>${u.hp}/${u.maxHp}</b></span>
          <span>DMG <b>${u.damage}</b></span>
          <span>ARM <b>${u.armor}</b></span>
          <span>CRIT <b>${u.critChance}%</b></span>
        </div>
      </div>
      <div class="crew-level">${u.level}</div>`;
    el.addEventListener('click', () => { Game.selectedCrewIndex = i; renderCrewScreen(); openUnitModal(u); });
    body.appendChild(el);
  });
}

function openUnitModal(u){
  const modal = document.getElementById('modal');
  const inner = document.getElementById('modal-inner');
  const healCost = Math.max(50, (u.maxHp-u.hp)*3);
  inner.innerHTML = `
    <h2>${u.name} · ${u.className}</h2>
    <p>Level ${u.level} · XP ${u.xp}/${u.xpNext}</p>
    <div class="stat-row"><span>Health</span><b>${u.hp}/${u.maxHp}</b></div>
    <div class="stat-row"><span>Damage</span><b>${u.damage}</b></div>
    <div class="stat-row"><span>Armor</span><b>${u.armor}</b></div>
    <div class="stat-row"><span>Move</span><b>${u.move}</b></div>
    <div class="stat-row"><span>Range</span><b>${u.range}</b></div>
    <div class="stat-row"><span>Crit</span><b>${u.critChance}%</b></div>
    <div class="stat-row"><span>Weapon</span><b>${ITEMS[u.weapon].name}</b></div>
    <div class="stat-row"><span>Armor Item</span><b>${ITEMS[u.armor_item].name}</b></div>
    <div class="stat-row"><span>Skill Points</span><b>${u.skillPoints}</b></div>
    <div class="upgrade-row" style="margin-top:10px;">
      <div class="name">Full Repair</div>
      <div class="cost">¢ ${healCost}</div>
      <button id="modal-heal" ${u.hp>=u.maxHp || Game.credits<healCost?'disabled':''}>HEAL</button>
    </div>
    <button class="btn magenta" id="modal-close" style="width:100%;margin-top:12px;">CLOSE</button>`;
  inner.querySelector('#modal-heal').addEventListener('click', () => {
    if (Game.credits >= healCost){ Game.credits -= healCost; u.hp = u.maxHp; toast(`${u.name} repaired.`); updateOverworldHUD(); openUnitModal(u); }
  });
  inner.querySelector('#modal-close').addEventListener('click', () => { modal.classList.remove('open'); renderCrewScreen(); });
  modal.classList.add('open');
}

function renderSkills(body){
  const u = Game.roster[Game.selectedCrewIndex];
  if (!u){ body.innerHTML = '<p>No unit selected.</p>'; return; }
  const tree = SKILL_TREES[u.className] || [];
  body.innerHTML = `
    <div style="display:flex;gap:10px;align-items:center;margin-bottom:10px;flex-wrap:wrap;">
      <div style="font-family:'Orbitron';font-size:12px;letter-spacing:2px;color:var(--cyan);">${u.name.toUpperCase()}</div>
      <div style="font-size:10px;color:#8fa8b8;">${u.className} · LVL ${u.level}</div>
      <div style="flex:1;"></div>
      <div style="font-family:'Orbitron';font-size:10px;color:#ffe060;">SP: <b>${u.skillPoints}</b></div>
    </div>
    <div style="font-size:10px;color:#6fa8b8;margin-bottom:8px;">Tap a highlighted skill to unlock.</div>
    <div class="skill-tree"></div>`;
  const grid = body.querySelector('.skill-tree');
  tree.forEach(branch => {
    const b = document.createElement('div');
    b.className = 'branch';
    b.innerHTML = `<div class="branch-title" style="color:${branch.color};">${branch.name}</div>`;
    branch.skills.forEach(sk => {
      const rank = u.skills.filter(x => x === sk.id).length;
      const maxed = rank >= sk.max;
      const reqs = sk.req || [];
      const prereq = reqs.every(r => u.skills.includes(r));
      const canBuy = !maxed && prereq && u.skillPoints >= sk.cost;
      const state = maxed ? 'unlocked' : rank > 0 ? 'unlocked' : canBuy ? 'available' : 'locked';
      const node = document.createElement('div');
      node.className = 'skill-node ' + state;
      node.innerHTML = `
        ${rank > 0 ? `<div class="skill-rank">${rank}/${sk.max}</div>` : ''}
        <div>${sk.name}</div>
        <div style="font-size:7px;opacity:.85;margin-top:2px;">${sk.desc}</div>
        <div style="font-size:7px;margin-top:2px;color:var(--orange);">${sk.cost} SP</div>`;
      node.addEventListener('click', () => {
        if (!canBuy) return;
        u.skillPoints -= sk.cost;
        u.skills.push(sk.id);
        if (sk.active && !u.skills.includes(sk.active)) u.skills.push(sk.active);
        applySkillsToUnit(u);
        toast(`${sk.name} unlocked!`);
        saveGame(0);
        renderSkills(body);
      });
      b.appendChild(node);
    });
    grid.appendChild(b);
  });
}

function applySkillsToUnit(u){
  const base = CLASS_DEFS[u.className];
  u.damage = base.dmg;
  u.armor = base.armor;
  u.move = base.move;
  u.range = base.range;
  u.critChance = 5;
  const w = ITEMS[u.weapon];
  if (w){ u.damage = w.dmg; u.range = w.range; }
  const ar = ITEMS[u.armor_item];
  let baseHp = base.hp;
  if (ar){ u.armor += ar.armor; baseHp += (ar.hp||0); if (ar.move) u.move += ar.move; }
  u.maxHp = baseHp;
  u.cyber.forEach(c => {
    const it = ITEMS[c]; if (!it) return;
    if (it.crit) u.critChance += it.crit;
    if (it.move) u.move += it.move;
    if (it.armor) u.armor += it.armor;
    if (it.hp) u.maxHp += it.hp;
  });
  u.maxAp = base.ap + (u.cyber.includes('cyber_neural') ? 1 : 0);
  u.ap = Math.min(u.ap, u.maxAp);
  u.damage += (u.level-1)*3;
  u.maxHp += (u.level-1)*10;
  // Passives
  u.skills.forEach(sid => {
    const skill = findSkillByAnyId(u.className, sid);
    if (!skill || !skill.passive) return;
    if (sid === 'g_aim' || sid === 'a_mark') u.critChance += 10;
    if (sid === 'g_dual') u.damage += Math.floor(u.damage*0.05);
    if (sid === 's_rage' || sid === 'h_brute') u.damage += Math.floor(u.damage*0.05);
    if (sid === 'n_silent' || sid === 'a_dash') u.move += 2;
  });
  // Background
  if (u === Game.roster[0]){
    const bg = BACKGROUNDS[Game.background];
    if (bg && bg.stat){
      if (bg.stat.hp) u.maxHp += bg.stat.hp;
      if (bg.stat.armor) u.armor += bg.stat.armor;
      if (bg.stat.move) u.move += bg.stat.move;
      if (bg.stat.crit) u.critChance += bg.stat.crit;
      if (bg.stat.dmg) u.damage += bg.stat.dmg;
    }
  }
  if (u.hp > u.maxHp) u.hp = u.maxHp;
}

function findSkillByAnyId(cn, sid){
  const tree = SKILL_TREES[cn] || [];
  for (const b of tree) for (const sk of b.skills) if (sk.id === sid) return sk;
  return null;
}

function renderInventory(body){
  const u = Game.roster[Game.selectedCrewIndex];
  if (!u){ body.innerHTML = '<p>No unit selected.</p>'; return; }
  body.innerHTML = `
    <div style="display:flex;gap:10px;align-items:center;margin-bottom:10px;">
      <div style="font-family:'Orbitron';font-size:12px;letter-spacing:2px;color:var(--cyan);">${u.name.toUpperCase()}</div>
      <div style="flex:1;"></div>
      <div style="font-family:'Orbitron';font-size:10px;color:var(--orange);">¢ ${Game.credits.toLocaleString()}</div>
    </div>`;

  // Weapons
  body.appendChild(section('WEAPONS', Object.entries(ITEMS).filter(([k,v])=>v.type==='weapon').map(([k,v])=>makeSlot(k,v,u,'weapon'))));
  body.appendChild(section('ARMOR', Object.entries(ITEMS).filter(([k,v])=>v.type==='armor').map(([k,v])=>makeSlot(k,v,u,'armor'))));
  body.appendChild(section('CYBERWARE', Object.entries(ITEMS).filter(([k,v])=>v.type==='cyber').map(([k,v])=>makeSlot(k,v,u,'cyber'))));
  const cons = Object.entries(ITEMS).filter(([k,v])=>v.type==='consumable');
  const grid = document.createElement('div');
  grid.className = 'inv-grid';
  cons.forEach(([k,v]) => {
    const el = document.createElement('div');
    el.className = 'inv-slot';
    el.innerHTML = `${ICONS[v.icon]||''}<div class="name">${v.name}</div><div class="qty">×${u.inventory[k]||0}</div>`;
    grid.appendChild(el);
  });
  const s = document.createElement('div');
  s.className = 'inv-section';
  s.innerHTML = '<h3>CONSUMABLES</h3>';
  s.appendChild(grid);
  body.appendChild(s);
}

function section(title, items){
  const s = document.createElement('div');
  s.className = 'inv-section';
  s.innerHTML = `<h3>${title}</h3>`;
  const g = document.createElement('div');
  g.className = 'inv-grid';
  items.forEach(el => g.appendChild(el));
  s.appendChild(g);
  return s;
}

function makeSlot(itemId, item, unit, slotType){
  const equipped = (slotType === 'weapon' && unit.weapon === itemId) ||
                   (slotType === 'armor' && unit.armor_item === itemId) ||
                   (slotType === 'cyber' && unit.cyber.includes(itemId));
  const el = document.createElement('div');
  el.className = 'inv-slot' + (equipped ? ' equipped' : '');
  el.innerHTML = `${ICONS[item.icon]||''}<div class="name">${item.name}</div>`;
  el.addEventListener('click', () => {
    if (slotType === 'weapon') unit.weapon = itemId;
    else if (slotType === 'armor') unit.armor_item = itemId;
    else if (slotType === 'cyber'){
      const idx = unit.cyber.indexOf(itemId);
      if (idx >= 0) unit.cyber.splice(idx,1);
      else if (unit.cyber.length < 2) unit.cyber.push(itemId);
      else { toast('Max 2 cyberware.'); return; }
    }
    applySkillsToUnit(unit);
    renderCrewScreen();
    toast(`${item.name} equipped.`);
    saveGame(0);
  });
  return el;
}

// ================= MISSION → COMBAT =================
function startMission(mission){
  document.getElementById('contact-panel').classList.remove('open');
  Game.activeMission = mission;
  Game.roster.forEach(u => { u.hp = u.maxHp; u.ap = u.maxAp; });
  setTimeout(() => { showScreen('combat'); initCombat(mission); }, 200);
}

function initCombat(mission){
  Game.combatCanvas = document.getElementById('fx');
  Game.combatCtx = Game.combatCanvas.getContext('2d');
  resizeCombatCanvas();
  window.removeEventListener('resize', resizeCombatCanvas);
  window.addEventListener('resize', resizeCombatCanvas);
  buildGrid(mission);
  createCombatUnits(mission);
  Game.gameOver = false;
  Game.pendingAbility = null;
  Game.pendingItem = null;
  Game.particles = []; Game.floats = []; Game.tracers = [];
  buildTurnQueue();
  Game.turnIndex = 0;
  Game.selectedUnit = Game.units.find(u => u.team === 'player');
  document.getElementById('log').innerHTML = '';
  logMsg(`Contract: ${mission.name}`, 'sys');
  logMsg(mission.desc, 'sys');
  crewBanter('start');
  updateCombat();
  showBanner('MISSION START', '#00f0ff');
  requestAnimationFrame(combatLoop);
  advanceTurn();
}

function resizeCombatCanvas(){
  const board = document.getElementById('board');
  if (!board) return;
  const rect = board.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  Game.combatCanvas.width = rect.width * dpr;
  Game.combatCanvas.height = rect.height * dpr;
  Game.combatCtx.setTransform(dpr,0,0,dpr,0,0);
}

function buildGrid(mission){
  const gridEl = document.getElementById('grid');
  gridEl.innerHTML = '';
  Game.grid = [];
  for (let y=0;y<GRID_SIZE;y++){
    for (let x=0;x<GRID_SIZE;x++){
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.dataset.x = x; cell.dataset.y = y;
      cell.addEventListener('click', () => onCombatCellClick(x,y));
      gridEl.appendChild(cell);
      let obstacle=false, cover=false, hazard=false;
      const seed = (x*13 + y*31 + (mission.id.charCodeAt(2)||0)) % 100;
      if (seed < 9 && !(x<3 && y>6) && !(x>6 && y<3)) obstacle = true;
      if (!obstacle && seed > 60 && seed < 74) cover = true;
      if (!obstacle && !cover && seed > 88 && seed < 92) hazard = true;
      const c = {x,y,obstacle,cover,hazard,unit:null,el:cell,coverDir:null};
      Game.grid.push(c);
      if (obstacle) cell.classList.add('obstacle');
      else if (cover){ cell.classList.add('cover'); c.coverDir = ['N','S','E','W'][(x+y)%4]; }
      else if (hazard) cell.classList.add('hazard');
    }
  }
}

function createCombatUnits(mission){
  Game.units = [];
  const positions = [[0,9],[1,9],[2,9]];
  Game.roster.forEach((u, i) => {
    const [px,py] = positions[i] || [0,9];
    const cu = {
      name:u.name, className:u.className, team:'player',
      x:px, y:py,
      maxHp:u.maxHp, hp:u.hp,
      maxAp:u.maxAp, ap:u.maxAp,
      move:u.move, range:u.range,
      damage:u.damage, armor:u.armor,
      critChance:u.critChance,
      weapon:u.weapon,
      abilities:[...u.skills],
      inventory:{...u.inventory},
      statuses:{}, facing:'N', overwatch:false,
      el:null, dead:false, rosterRef:u,
      speed: 10 + u.move
    };
    Game.units.push(cu);
  });

  const enemyPositions = [[9,0],[8,0],[7,0],[9,1],[8,1],[6,0],[9,2],[7,2]];
  // A hunter response can take ordinary open-ground encounters beyond the eight
  // authored enemy slots. Never silently put extra enemies on [9,0]: that makes
  // the previous occupant unselectable in the grid's one-unit-per-cell model.
  // Preserve all eight authored positions and allocate only the overflow here;
  // shaped arenas still apply their own deployment after this legacy setup.
  const reservedSpawns = new Set(Game.units.map(u => `${u.x}:${u.y}`));
  function overflowEnemyPosition(){
    const candidates = Game.grid.filter(c =>
      !c.obstacle && !c.arenaVoid && !c.door && c.objectiveIndex == null &&
      !reservedSpawns.has(`${c.x}:${c.y}`)
    );
    // Prefer northern enemy-side rows, then use remaining legal floor if full.
    candidates.sort((a,b) => (a.y<5 ? 0 : 1)-(b.y<5 ? 0 : 1) || a.y-b.y || b.x-a.x);
    if (!candidates.length) throw new Error('Combat arena has no legal tile for an additional enemy');
    return [candidates[0].x,candidates[0].y];
  }
  mission.enemies.forEach((type, i) => {
    const [px,py] = enemyPositions[i] || overflowEnemyPosition();
    reservedSpawns.add(`${px}:${py}`);
    const def = ENEMY_DEFS[type];
    const scale = 1 + (mission.diff-1)*0.12;
    const e = {
      name:type+' '+(i+1), className:type, team:'enemy',
      x:px, y:py,
      maxHp:Math.round(def.hp*scale), hp:Math.round(def.hp*scale),
      maxAp:def.ap, ap:def.ap,
      move:def.move, range:def.range,
      damage:Math.round(def.dmg*scale), armor:def.armor,
      critChance:5, weapon:def.weapon,
      abilities:[], inventory:{},
      statuses:{}, facing:'S', overwatch:false,
      el:null, dead:false, speed:def.speed
    };
    Game.units.push(e);
  });

  Game.grid.forEach(c=>c.unit=null);
  Game.units.forEach(u=>{ const c=cellAt(u.x,u.y); if(c) c.unit=u; });
}

function buildTurnQueue(){
  Game.turnQueue = [...Game.units].filter(u=>u.hp>0).sort((a,b)=>b.speed-a.speed);
  Game.turnIndex = 0;
}

function advanceTurn(){
  if (Game.gameOver) return;
  let safety = 0;
  while (Game.turnIndex < Game.turnQueue.length && safety < Game.turnQueue.length*2){
    const u = Game.turnQueue[Game.turnIndex];
    if (u && u.hp > 0 && !u.dead) break;
    Game.turnIndex++; safety++;
  }
  if (Game.turnIndex >= Game.turnQueue.length){
    Game.units.forEach(u => { if (u.team==='player') u.ap = u.maxAp; });
    buildTurnQueue();
  }
  const cur = Game.turnQueue[Game.turnIndex];
  if (!cur) return;
  Game.selectedUnit = cur;
  Game.selectedUnit = cur;
  Game.turn = cur.team;
  document.getElementById('turn-indicator').textContent = cur.team==='player'?'PLAYER TURN':'ENEMY TURN';
  document.getElementById('turn-indicator').className = 'turn' + (cur.team==='enemy'?' enemy':'');
  updateCombat();
  renderInitiative();
  if (cur.team === 'enemy') setTimeout(() => enemyAITakeTurn(cur), 400);
}

async function endUnitTurn(){
  const cur = Game.turnQueue[Game.turnIndex];
  if (cur) cur.ap = 0;
  Game.turnIndex++;
  updateCombat();
  renderInitiative();
  await sleep(150);
  advanceTurn();
}

function renderInitiative(){
  const strip = document.getElementById('init-strip');
  strip.innerHTML = '';
  Game.turnQueue.forEach((u, i) => {
    if (u.hp <= 0) return;
    const el = document.createElement('div');
    el.className = 'init-token ' + u.team;
    if (i === Game.turnIndex) el.classList.add('active');
    if (i < Game.turnIndex) el.classList.add('done');
    el.textContent = u.name[0].toUpperCase();
    el.title = u.name;
    strip.appendChild(el);
  });
}

// LOS + flank + cover
function bresenhamLine(x0,y0,x1,y1){
  const p=[]; const dx=Math.abs(x1-x0), dy=Math.abs(y1-y0);
  const sx=x0<x1?1:-1, sy=y0<y1?1:-1;
  let err=dx-dy, x=x0, y=y0;
  while(true){ p.push({x,y}); if(x===x1&&y===y1)break; const e2=2*err; if(e2>-dy){err-=dy;x+=sx;} if(e2<dx){err+=dx;y+=sy;} }
  return p;
}
function hasLOS(from,to){
  const line = bresenhamLine(from.x,from.y,to.x,to.y);
  for (let i=1;i<line.length-1;i++){
    const c = cellAt(line[i].x, line[i].y);
    if (c && c.obstacle) return false;
  }
  return true;
}
function computeFlank(a,t){
  const dx=a.x-t.x, dy=a.y-t.y;
  const fx=Math.sign(dx), fy=Math.sign(dy);
  const fv = {N:{x:0,y:-1},S:{x:0,y:1},E:{x:1,y:0},W:{x:-1,y:0}}[t.facing]||{x:0,y:1};
  const dot = fx*fv.x + fy*fv.y;
  if (dot > 0) return 'front';
  if (dot < 0) return 'back';
  return 'side';
}
function coverBonusFor(t,a){
  const tc = cellAt(t.x,t.y);
  if (!tc || !tc.cover) return 0;
  const dx=a.x-t.x, dy=a.y-t.y;
  const dir = Math.abs(dx)>Math.abs(dy) ? (dx>0?'E':'W') : (dy>0?'S':'N');
  return tc.coverDir === dir ? 3 : 1;
}

// ================= COMBAT RENDER =================
function combatLoop(){
  if (Game.screen !== 'combat') return;
  const ctx = Game.combatCtx;
  const rect = Game.combatCanvas.getBoundingClientRect();
  const W = rect.width, H = rect.height;
  ctx.clearRect(0,0,W,H);
  for (let i=Game.tracers.length-1;i>=0;i--){
    const t = Game.tracers[i];
    ctx.globalAlpha = Math.max(0,t.life);
    ctx.strokeStyle = t.color; ctx.lineWidth = 2.2; ctx.lineCap='round';
    ctx.shadowColor = t.color; ctx.shadowBlur=14;
    ctx.beginPath(); ctx.moveTo(t.ax,t.ay); ctx.lineTo(t.bx,t.by); ctx.stroke();
    ctx.strokeStyle='#fff'; ctx.lineWidth=0.9; ctx.shadowBlur=6;
    ctx.beginPath(); ctx.moveTo(t.ax,t.ay); ctx.lineTo(t.bx,t.by); ctx.stroke();
    t.life -= 0.07;
    if (t.life <= 0) Game.tracers.splice(i,1);
  }
  for (let i=Game.particles.length-1;i>=0;i--){
    const p = Game.particles[i];
    p.x += p.vx; p.y += p.vy; p.vy += 0.10;
    p.vx *= 0.97; p.vy *= 0.97; p.life -= 0.022;
    if (p.life <= 0){ Game.particles.splice(i,1); continue; }
    ctx.globalAlpha = p.life*0.95;
    ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 12;
    ctx.beginPath(); ctx.arc(p.x,p.y,Math.max(0.2,p.size*p.life),0,Math.PI*2); ctx.fill();
  }
  for (let i=Game.floats.length-1;i>=0;i--){
    const f = Game.floats[i];
    f.y += f.vy; f.vy *= 0.97; f.life -= 0.016;
    if (f.life <= 0){ Game.floats.splice(i,1); continue; }
    const a = Math.min(1,f.life*1.6);
    ctx.globalAlpha = a;
    ctx.font = `bold ${Math.max(12, Math.round(W/46))}px 'Orbitron'`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = f.color; ctx.shadowColor = f.color; ctx.shadowBlur = 16;
    ctx.fillText(f.text, f.x, f.y);
    ctx.fillStyle = '#fff'; ctx.shadowBlur = 6;
    ctx.fillText(f.text, f.x, f.y);
  }
  ctx.shadowBlur = 0; ctx.globalAlpha = 1;
  requestAnimationFrame(combatLoop);
}

function boardPx(gx,gy){
  const rect = Game.combatCanvas.getBoundingClientRect();
  const cw = rect.width/GRID_SIZE, ch = rect.height/GRID_SIZE;
  return {x:(gx+0.5)*cw, y:(gy+0.5)*ch};
}
function spawnParticles(gx,gy,color,count=12,spread=3){
  const p = boardPx(gx,gy);
  const rect = Game.combatCanvas.getBoundingClientRect();
  const scale = rect.width/560;
  for (let i=0;i<count;i++){
    const a = Math.random()*Math.PI*2;
    const sp = (0.6+Math.random()*spread)*scale*2;
    Game.particles.push({x:p.x,y:p.y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life:1,color,size:(1.2+Math.random()*2.4)*Math.max(0.7,scale)});
  }
}
function floatText(gx,gy,text,color){ const p = boardPx(gx,gy); Game.floats.push({x:p.x,y:p.y,text,color,life:1,vy:-0.9}); }
function tracer(fx0,fy0,tx,ty,color){ const a=boardPx(fx0,fy0), b=boardPx(tx,ty); Game.tracers.push({ax:a.x,ay:a.y,bx:b.x,by:b.y,color,life:1}); }
function shake(kind='sm'){ const b=document.getElementById('board'); b.classList.remove('shake-sm','shake-md'); void b.offsetWidth; b.classList.add(kind==='md'?'shake-md':'shake-sm'); }
function showBanner(text, color){
  const board = document.getElementById('board');
  const el = document.createElement('div');
  el.className='banner'; el.textContent=text;
  el.style.color=color;
  el.style.textShadow = `0 0 20px ${color}, 0 0 40px ${color}, 0 0 60px ${color}`;
  board.appendChild(el);
  requestAnimationFrame(()=>el.classList.add('show'));
  setTimeout(()=>{ el.classList.remove('show'); setTimeout(()=>el.remove(),400); }, 900);
}
function logMsg(text, cls){
  const el = document.getElementById('log');
  const div = document.createElement('div');
  if (cls) div.className = cls;
  div.textContent = '> '+text;
  el.appendChild(div); el.scrollTop = el.scrollHeight;
}

// ================= SYNC =================
function syncCombatUnits(){
  const layer = document.getElementById('units');
  Game.units.forEach(u => {
    if (u.hp <= 0 && !u.dead){
      u.dead = true;
      if (u.el){
        const el = u.el; el.classList.add('dead');
        setTimeout(()=>{ if(el.parentNode) el.remove(); }, 600);
        u.el = null;
      }
    }
    if (u.dead) return;
    if (!u.el){
      const el = document.createElement('div');
      el.className = `unit ${u.team}`;
      el.innerHTML = `
        <div class="shadow"></div>
        ${SPRITES[u.className]||SPRITES.Guard}
        <div class="statuses"></div>
        <div class="hpbar"><i></i></div>`;
      layer.appendChild(el);
      u.el = el;
      // PWA12.58: cache stable descendants once instead of querying the unit subtree
      // on every combat presentation refresh.
      u._combatHpFill = el.querySelector('.hpbar i');
      u._combatStatuses = el.querySelector('.statuses');
    }
    const left=(u.x*10)+'%',top=(u.y*10)+'%';
    if(u._combatLeft!==left){u.el.style.left=left;u._combatLeft=left}
    if(u._combatTop!==top){u.el.style.top=top;u._combatTop=top}
    const selected=u===Game.selectedUnit;
    if(u._combatSelected!==selected){u.el.classList.toggle('selected',selected);u._combatSelected=selected}
    const hpFill = u._combatHpFill || (u._combatHpFill=u.el.querySelector('.hpbar i'));
    if (hpFill){
      const hpRatio=Math.max(0,u.hp/u.maxHp),hpWidth=(hpRatio*100)+'%',hpLow=hpRatio<0.3;
      if(u._combatHpWidth!==hpWidth){hpFill.style.width=hpWidth;u._combatHpWidth=hpWidth}
      if(u._combatHpLow!==hpLow){hpFill.classList.toggle('low',hpLow);u._combatHpLow=hpLow}
    }
    const st = u._combatStatuses || (u._combatStatuses=u.el.querySelector('.statuses'));
    // PWA12.61: status presentation is binary even when effect durations tick.
    // Keep the original seven-icon order, followed by legacy poison/bleed icons.
    // Updating only when these visible flags or the status node change avoids
    // destroying/recreating every icon on unchanged combat refreshes.
    const statuses=u.statuses||{};
    const statusBits=(statuses.shock?1:0)|(statuses.burn?2:0)|
      (u.disabledTurns>0?4:0)|(statuses.marked?8:0)|
      (statuses.armor_up?16:0)|(statuses.cloak?32:0)|
      (u.overwatch?64:0)|(statuses.poison?128:0)|(statuses.bleed?256:0);
    if(st && (u._combatStatusBits!==statusBits || u._combatStatusNode!==st)){
      st.replaceChildren();
      if(statusBits&1)addSt(st,'st-shock');
      if(statusBits&2)addSt(st,'st-burn');
      if(statusBits&4)addSt(st,'st-stun');
      if(statusBits&8)addSt(st,'st-marked');
      if(statusBits&16)addSt(st,'st-armor');
      if(statusBits&32)addSt(st,'st-cloak');
      if(statusBits&64)addSt(st,'st-overwatch');
      if(statusBits&128)addSt(st,'st-poison');
      if(statusBits&256)addSt(st,'st-burn'); // Existing bleed artwork uses st-burn.
      u._combatStatusBits=statusBits;
      u._combatStatusNode=st;
    }
  });
}
function addSt(p,c){ const i=document.createElement('i'); i.className=c; p.appendChild(i); }
function flashHit(u){ if(!u.el) return; u.el.classList.remove('hit'); void u.el.offsetWidth; u.el.classList.add('hit'); }

// ================= HIGHLIGHTS =================
function refreshCombatHighlights(){
  Game.grid.forEach(c=>{ if(c.el) c.el.classList.remove('move-range','attack-range','flank-range','los-blocked'); });
  if (!Game.selectedUnit || Game.gameOver) return;
  if (!(Game.selectedUnit.team === 'player' && Game.turn === 'player')) return;
  Game.grid.forEach(c => {
    if (c.obstacle) return;
    const d = Math.abs(Game.selectedUnit.x-c.x)+Math.abs(Game.selectedUnit.y-c.y);
    if (c.unit && c.unit.team !== Game.selectedUnit.team && c.unit.hp > 0 && d <= Game.selectedUnit.range && hasLOS(Game.selectedUnit, c.unit)){
      const f = computeFlank(Game.selectedUnit, c.unit);
      c.el.classList.add(f === 'front' ? 'attack-range' : 'flank-range');
    } else if (!c.unit && d <= Game.selectedUnit.move && d > 0){
      c.el.classList.add('move-range');
    }
  });
}

// ================= HUD =================
function updateCombatHUD(){
  const nameEl = document.getElementById('sel-name');
  const hpFill = document.getElementById('sel-hp-fill');
  const hpText = document.getElementById('sel-hp-text');
  const apPips = document.getElementById('sel-ap-pips');
  const portrait = document.getElementById('portrait');
  if (Game.selectedUnit){
    nameEl.textContent = `${Game.selectedUnit.name.toUpperCase()} · ${Game.selectedUnit.className}`;
    const pct = Math.max(0,(Game.selectedUnit.hp/Game.selectedUnit.maxHp)*100);
    hpFill.style.width = pct+'%';
    hpFill.classList.toggle('low', pct<30);
    hpText.textContent = `${Math.max(0,Game.selectedUnit.hp)}/${Game.selectedUnit.maxHp}`;
    portrait.innerHTML = window.CRAssets?.classPortrait?.(Game.selectedUnit.className,Game.selectedUnit.name)||SPRITES[Game.selectedUnit.className]||'';
    portrait.className = 'portrait ' + Game.selectedUnit.team;
    apPips.innerHTML = '';
    for (let i=0;i<Game.selectedUnit.maxAp;i++){
      const p = document.createElement('i');
      if (i >= Game.selectedUnit.ap) p.classList.add('spent');
      apPips.appendChild(p);
    }
  }
}

function updateCombatActions(){
  const el = document.getElementById('actions');
  el.innerHTML = '';
  if (!Game.selectedUnit || Game.gameOver) return;
  const isPlayerTurn = Game.selectedUnit.team === 'player' && Game.turn === 'player';
  if (isPlayerTurn){
    Game.selectedUnit.abilities.forEach(sid => {
      const ab = ABILITY_DEFS[sid];
      if (!ab) return;
      const btn = document.createElement('button');
      // Show the complete command name and AP cost; gameplay continues to use the original ability handler.
      const cost = ab.cost||1;
      btn.dataset.v14ApCost = String(cost);
      btn.innerHTML = `${ICONS[ab.icon]||''}<span>${sid}</span><small class="v14-action-ap">${cost} AP</small>`;
      btn.title = `${sid} · ${cost} AP — ${ab.desc||''}`;
      btn.setAttribute('aria-label', btn.title);
      btn.disabled = Game.selectedUnit.ap < (ab.cost||1);
      btn.addEventListener('click', () => useAbility(sid, ab));
      el.appendChild(btn);
    });
    if (!Game.selectedUnit.overwatch && Game.selectedUnit.ap >= 1){
      const btn = document.createElement('button');
      btn.dataset.v14ApCost = '1';
      btn.innerHTML = `${ICONS.rifle}<span>Overwatch</span><small class="v14-action-ap">1 AP</small>`;
      btn.title = 'Overwatch · 1 AP — Fire a reaction shot.';
      btn.setAttribute('aria-label', btn.title);
      btn.addEventListener('click', () => {
        Game.selectedUnit.overwatch = true;
        Game.selectedUnit.ap -= 1;
        logMsg(`${Game.selectedUnit.name} sets Overwatch.`, 'sys');
        updateCombat();
      });
      el.appendChild(btn);
    }
    Object.entries(Game.selectedUnit.inventory).forEach(([k,v]) => {
      if (!v || v <= 0) return;
      const it = ITEMS[k];
      if (!it || it.type !== 'consumable') return;
      const btn = document.createElement('button');
      btn.className = 'item-btn';
      btn.innerHTML = `${ICONS[it.icon]||''}<span>${it.name.split(' ')[0]}×${v}</span>`;
      btn.title = it.desc;
      btn.addEventListener('click', () => useConsumable(Game.selectedUnit, k));
      el.appendChild(btn);
    });
  }
  const endBtn = document.createElement('button');
  endBtn.textContent = 'END TURN';
  endBtn.className = 'end-turn';
  endBtn.disabled = !isPlayerTurn;
  endBtn.addEventListener('click', endUnitTurn);
  el.appendChild(endBtn);
}

function updateCombat(){
  syncCombatUnits();
  refreshCombatHighlights();
  updateCombatHUD();
  updateCombatActions();
}

// ================= INPUT =================
function onCombatCellClick(x,y){
  if (Game.gameOver || Game.turn !== 'player') return;
  const c = cellAt(x,y);
  if (!c) return;
  const unit = c.unit;
  const cur = Game.selectedUnit;
  if (!cur || cur.team !== 'player') return;
  if (Game.pendingItem){
    if (Game.pendingItem.stun || Game.pendingItem.smoke){
      executeTileItem(Game.pendingItem, x, y);
      Game.pendingItem = null;
      updateCombat(); return;
    }
  }
  if (Game.pendingAbility){
    if (unit && unit.team !== cur.team){
      const d = Math.abs(cur.x-unit.x)+Math.abs(cur.y-unit.y);
      if (d <= Game.pendingAbility.range && hasLOS(cur,unit)){
        if (cur.ap >= Game.pendingAbility.cost){
          executeAbility(Game.pendingAbility, unit);
          Game.pendingAbility = null;
          updateCombat();
        } else logMsg('Not enough AP.', 'sys');
      } else logMsg('Cannot target.', 'sys');
    } else { Game.pendingAbility = null; logMsg('Cancelled.', 'sys'); updateCombat(); }
    return;
  }
  if (unit && unit === cur) return;
  if (unit && unit.team !== cur.team && unit.hp > 0){
    const d = Math.abs(cur.x-unit.x)+Math.abs(cur.y-unit.y);
    if (d <= cur.range && hasLOS(cur,unit)){
      if (cur.ap >= 1) basicAttack(cur, unit);
      else logMsg('No AP.', 'sys');
    } else logMsg('Out of range.', 'sys');
    return;
  }
  if (!unit && !c.obstacle){
    const d = combatPathDistance(cur,c.x,c.y);
    if (d <= cur.move && d > 0){
      if (cur.ap >= 1){
        cur.facing = Math.abs(c.x-cur.x) > Math.abs(c.y-cur.y) ? (c.x>cur.x?'E':'W') : (c.y>cur.y?'S':'N');
        moveUnit(cur, x, y);
      } else logMsg('No AP.', 'sys');
    } else logMsg('Too far.', 'sys');
  }
}

// ================= ACTIONS =================
function basicAttack(a, t){
  const f = computeFlank(a,t);
  const fMult = f === 'back' ? 1.5 : f === 'side' ? 1.25 : 1;
  const cover = coverBonusFor(t,a);
  const marked = t.statuses.marked ? 1.5 : 1;
  const crit = Math.random()*100 < a.critChance;
  const cMult = crit ? 1.8 : 1;
  let dmg = a.damage * fMult * marked * cMult - t.armor - cover;
  dmg = Math.max(1, Math.floor(dmg));
  if (a.statuses.cloak){ dmg *= 2; delete a.statuses.cloak; }
  a.ap -= 1;
  a.overwatch = false;
  const color = a.team === 'player' ? '#00f0ff' : '#ff2244';
  tracer(a.x,a.y,t.x,t.y,color);
  spawnParticles(a.x,a.y,color,6,2);
  setTimeout(() => {
    spawnParticles(t.x,t.y, a.team==='player'?'#ffaa00':'#ff2244', 16, 3.5);
    flashHit(t);
    floatText(t.x,t.y,'-'+dmg, crit?'#ffe060':'#ff5566');
    if (f==='back') floatText(t.x,t.y-0.6,'BACKSTAB','#ff00aa');
    if (crit) floatText(t.x,t.y-1.1,'CRIT','#ffe060');
    shake(crit?'md':'sm');
    t.hp -= dmg;
    logMsg(`${a.name} hits ${t.name} for ${dmg}${crit?' CRIT':''}${f==='back'?' (backstab)':''}.`, crit?'crit':(a.team==='player'?'hit-player':'hit-enemy'));
    if (t.hp <= 0) onUnitDeath(t);
    checkWinLose();
    updateCombat();
  }, 130);
}

function onUnitDeath(u){
  logMsg(`${u.name} is down!`, 'sys');
  spawnParticles(u.x,u.y, u.team==='player'?'#00f0ff':'#ff2244', 28, 4);
  shake('md');
  const c = cellAt(u.x,u.y);
  if (c) c.unit = null;
}

function moveUnit(u, x, y){
  const oc = cellAt(u.x,u.y);
  const nc = cellAt(x,y);
  if (oc) oc.unit = null;
  if (nc) nc.unit = u;
  u.x = x; u.y = y;
  u.ap -= 1;
  if (nc.hazard){
    const d = 8;
    u.hp -= d;
    floatText(x,y,'-'+d,'#ff6600');
    logMsg(`${u.name} takes ${d} from hazard!`, 'sys');
    if (u.hp <= 0) onUnitDeath(u);
  }
  triggerOverwatch(u);
  updateCombat();
}

function triggerOverwatch(mover){
  const opp = mover.team === 'player' ? 'enemy' : 'player';
  for (const u of Game.units){
    if (u.team === opp && u.overwatch && u.hp > 0 &&
        Math.abs(u.x-mover.x)+Math.abs(u.y-mover.y) <= u.range && hasLOS(u,mover)){
      u.overwatch = false;
      logMsg(`${u.name} OVERWATCH!`, u.team==='player'?'good':'sys');
      setTimeout(() => basicAttack(u, mover), 200);
      break;
    }
  }
}

function useConsumable(user, key){
  if (!user || !user.inventory[key] || user.inventory[key] <= 0) return;
  const it = ITEMS[key];
  if (!it) return;
  if (it.target === 'tile'){
    Game.pendingItem = {...it, key};
    logMsg(`Select tile for ${it.name}.`, 'sys');
    return;
  }
  if (it.target === 'self'){
    user.inventory[key]--;
    if (it.heal){
      user.hp = Math.min(user.maxHp, user.hp + it.heal);
      floatText(user.x,user.y,'+'+it.heal,'#00ff88');
      spawnParticles(user.x,user.y,'#00ff88',16,3);
      logMsg(`${user.name} uses ${it.name}.`, 'good');
    }
    if (it.ap){
      user.ap += it.ap;
      floatText(user.x,user.y,'+'+it.ap+'AP','#ffe060');
      logMsg(`${user.name} gains ${it.ap} AP.`, 'good');
    }
    updateCombat();
  }
}

function executeTileItem(item, x, y){
  const cur = Game.selectedUnit;
  if (!cur) return;
  const key = item.key;
  if (!cur.inventory[key] || cur.inventory[key] <= 0) return;
  cur.inventory[key]--;
  const r = item.radius || 1;
  Game.units.filter(u => Math.abs(u.x-x)+Math.abs(u.y-y) <= r && u.hp > 0).forEach(t => {
    if (item.stun && t.team === 'enemy'){
      t.disabledTurns = Math.max(t.disabledTurns, item.stun);
      floatText(t.x,t.y,'STUN','#b060ff');
      spawnParticles(t.x,t.y,'#b060ff',14,3);
    }
    if (item.smoke && t.team === 'player'){
      t.armor += 3;
      t.statuses.armor_up = (t.statuses.armor_up||0) + 2;
      floatText(t.x,t.y,'SMOKE','#8fa8b8');
    }
  });
  shake('md');
  logMsg(`${cur.name} uses ${item.name}.`, 'sys');
}

function useAbility(sid, ab){
  if (!Game.selectedUnit || Game.selectedUnit.ap < (ab.cost||1)){ logMsg('Not enough AP.', 'sys'); return; }
  if (ab.target === 'enemy'){ Game.pendingAbility = {...ab, sid}; logMsg(`Select target for ${sid}.`, 'sys'); updateCombat(); }
  else { executeAbility({...ab, sid}, null); updateCombat(); }
}

function executeAbility(ab, t){
  const u = Game.selectedUnit;
  if (!u) return;
  const sid = ab.sid;
  if (sid === 'Ghost in the Machine'){
    if (!t) return;
    t.disabledTurns = 1;
    u.ap -= ab.cost;
    tracer(u.x,u.y,t.x,t.y,'#00f0ff');
    spawnParticles(t.x,t.y,'#00f0ff',20,3);
    floatText(t.x,t.y,'DISABLED','#00f0ff');
    shake('sm');
    logMsg(`${u.name} disables ${t.name}.`, 'hit-player');
  } else if (sid === 'Overload'){
    u.ap -= ab.cost;
    const dmg = ab.base || 8;
    Game.units.filter(x=>x.team!==u.team && x.hp>0 && Math.abs(x.x-u.x)+Math.abs(x.y-u.y)<=3).forEach((e,i)=>{
      setTimeout(()=>{
        spawnParticles(e.x,e.y,'#ff00aa',14,3);
        flashHit(e);
        e.hp -= dmg;
        floatText(e.x,e.y,'-'+dmg,'#ff00aa');
        logMsg(`Overload hits ${e.name} for ${dmg}.`, 'hit-player');
        if (e.hp <= 0) onUnitDeath(e);
        checkWinLose(); updateCombat();
      }, i*80);
    });
    shake('md');
  } else if (sid === 'Nano Repair'){
    u.ap -= ab.cost;
    u.hp = Math.min(u.maxHp, u.hp + (ab.base||20));
    spawnParticles(u.x,u.y,'#00ff88',16,3);
    floatText(u.x,u.y,'+'+(ab.base||20),'#00ff88');
    logMsg(`${u.name} repairs.`, 'good');
  } else if (sid === 'Headshot'){
    if (!t) return;
    u.ap -= ab.cost;
    const crit = Math.random()*100 < Math.max(u.critChance, 40);
    const dmg = Math.floor(u.damage * (crit ? 3 : 1.5));
    tracer(u.x,u.y,t.x,t.y,'#ffe060');
    spawnParticles(t.x,t.y,'#ffe060',24,4);
    flashHit(t);
    t.hp -= dmg;
    floatText(t.x,t.y,'-'+dmg, crit?'#ffe060':'#ffaa00');
    if (crit) floatText(t.x,t.y-0.6,'HEADSHOT','#ffe060');
    shake('md');
    logMsg(`${u.name} headshots ${t.name} for ${dmg}.`, 'crit');
    if (t.hp <= 0) onUnitDeath(t);
  } else if (sid === 'Fan the Hammer'){
    u.ap -= ab.cost;
    const es = Game.units.filter(x=>x.team!==u.team && x.hp>0 && Math.abs(x.x-u.x)+Math.abs(x.y-u.y)<=3);
    if (es.length === 0){ logMsg('No enemies.', 'sys'); return; }
    es.forEach((e,i)=>{
      setTimeout(()=>{
        tracer(u.x,u.y,e.x,e.y,'#ffaa00');
        spawnParticles(e.x,e.y,'#ffaa00',12,3);
        flashHit(e);
        const dmg = Math.max(1, Math.floor(u.damage/2) - e.armor);
        e.hp -= dmg;
        floatText(e.x,e.y,'-'+dmg,'#ffaa00');
        logMsg(`Fan hits ${e.name} for ${dmg}.`, 'hit-player');
        if (e.hp <= 0) onUnitDeath(e);
        checkWinLose(); updateCombat();
      }, i*100);
    });
  } else if (sid === 'Suppressive Fire'){
    if (!t) return;
    u.ap -= ab.cost;
    tracer(u.x,u.y,t.x,t.y,'#00f0ff');
    spawnParticles(t.x,t.y,'#00f0ff',18,3);
    flashHit(t);
    const dmg = Math.max(1, (ab.base||12) - t.armor);
    t.hp -= dmg;
    t.statuses.shock = ab.turns || 2;
    floatText(t.x,t.y,'-'+dmg,'#00f0ff');
    floatText(t.x,t.y-0.6,'SHOCK','#00f0ff');
    logMsg(`${u.name} shocks ${t.name}.`, 'hit-player');
    if (t.hp <= 0) onUnitDeath(t);
  } else if (sid === 'Blade Dance'){
    u.ap -= ab.cost;
    const es = Game.units.filter(x=>x.team!==u.team && x.hp>0 && Math.abs(x.x-u.x)+Math.abs(x.y-u.y)<=1);
    if (es.length === 0){ logMsg('No adjacent enemies.', 'sys'); return; }
    es.forEach((e,i)=>{
      setTimeout(()=>{
        spawnParticles(e.x,e.y,'#ff00aa',22,4);
        flashHit(e);
        const dmg = Math.max(1, u.damage - e.armor);
        e.hp -= dmg;
        e.statuses.burn = 2;
        floatText(e.x,e.y,'-'+dmg,'#ff00aa');
        floatText(e.x,e.y-0.6,'BLEED','#ff6600');
        shake('md');
        logMsg(`Blade Dance hits ${e.name} for ${dmg}.`, 'hit-player');
        if (e.hp <= 0) onUnitDeath(e);
        checkWinLose(); updateCombat();
      }, i*140);
    });
  } else if (sid === 'Riposte'){
    u.ap -= ab.cost;
    u.armor += 3;
    u.statuses.armor_up = 2;
    floatText(u.x,u.y,'+ARMOR','#ffe060');
    logMsg(`${u.name} gains armor.`, 'good');
  } else if (sid === 'Charge'){
    if (!t) return;
    u.ap -= ab.cost;
    const adj = [];
    for (const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){
      const c = cellAt(t.x+dx,t.y+dy);
      if (c && !c.obstacle && !c.unit) adj.push(c);
    }
    if (adj.length){
      const best = adj.reduce((a,b)=>Math.abs(a.x-u.x)+Math.abs(a.y-u.y) < Math.abs(b.x-u.x)+Math.abs(b.y-u.y) ? a : b);
      const oc = cellAt(u.x,u.y); oc.unit = null;
      const nc = cellAt(best.x,best.y); nc.unit = u;
      u.x = best.x; u.y = best.y;
    }
    setTimeout(()=>{
      const dmg = Math.floor(u.damage * 1.5);
      tracer(u.x,u.y,t.x,t.y,'#ff2244');
      spawnParticles(t.x,t.y,'#ff2244',22,4);
      flashHit(t);
      t.hp -= dmg;
      floatText(t.x,t.y,'-'+dmg,'#ff2244');
      shake('md');
      logMsg(`${u.name} charges ${t.name} for ${dmg}.`, 'hit-player');
      if (t.hp <= 0) onUnitDeath(t);
      checkWinLose(); updateCombat();
    }, 250);
  } else if (sid === 'One Shot One Kill'){
    if (!t) return;
    u.ap -= ab.cost;
    tracer(u.x,u.y,t.x,t.y,'#00ff88');
    spawnParticles(u.x,u.y,'#00ff88',8,2);
    setTimeout(()=>{
      spawnParticles(t.x,t.y,'#00ff88',30,5);
      flashHit(t);
      const dmg = ab.base || 35;
      t.hp -= dmg;
      floatText(t.x,t.y,'-'+dmg,'#00ff88');
      shake('md');
      logMsg(`${u.name} snipes ${t.name} for ${dmg}.`, 'crit');
      if (t.hp <= 0) onUnitDeath(t);
      checkWinLose(); updateCombat();
    }, 150);
  } else if (sid === 'Mark Target'){
    if (!t) return;
    u.ap -= ab.cost;
    t.statuses.marked = 2;
    floatText(t.x,t.y,'MARKED','#ff00aa');
    logMsg(`${u.name} marks ${t.name}.`, 'hit-player');
  } else if (sid === 'Ghost Protocol'){
    u.ap -= ab.cost;
    u.statuses.cloak = 1;
    floatText(u.x,u.y,'CLOAK','#6666ff');
    logMsg(`${u.name} cloaks.`, 'good');
  } else if (sid === 'Backstab'){
    if (!t) return;
    u.ap -= ab.cost;
    const f = computeFlank(u,t);
    const mult = f === 'back' ? 2 : 1;
    const dmg = Math.floor((ab.base||30) * mult);
    tracer(u.x,u.y,t.x,t.y,'#b060ff');
    spawnParticles(t.x,t.y,'#b060ff',20,4);
    flashHit(t);
    t.hp -= dmg;
    floatText(t.x,t.y,'-'+dmg,'#b060ff');
    if (f === 'back') floatText(t.x,t.y-0.6,'BACKSTAB','#ff00aa');
    shake('sm');
    logMsg(`${u.name} backstabs ${t.name} for ${dmg}.`, 'crit');
    if (t.hp <= 0) onUnitDeath(t);
  } else if (sid === 'Overwatch'){
    u.ap -= ab.cost;
    u.overwatch = true;
    floatText(u.x,u.y,'OVERWATCH','#00ff88');
    logMsg(`${u.name} sets Overwatch.`, 'sys');
  }
  checkWinLose();
}

// ================= ENEMY AI =================
async function enemyAITakeTurn(enemy){
  if (Game.gameOver || enemy.hp <= 0 || enemy.dead){ endUnitTurn(); return; }
  if (enemy.disabledTurns > 0){
    enemy.disabledTurns--;
    logMsg(`${enemy.name} is stunned.`, 'sys');
    spawnParticles(enemy.x,enemy.y,'#b060ff',8,1.5);
    updateCombat();
    await sleep(500);
    endUnitTurn(); return;
  }
  enemy.ap = enemy.maxAp;
  enemy.overwatch = false;
  const players = Game.units.filter(u=>u.team==='player' && u.hp>0);
  if (players.length === 0){ endUnitTurn(); return; }
  let target = players[0], best = Infinity;
  for (const p of players){
    const d = Math.abs(enemy.x-p.x)+Math.abs(enemy.y-p.y);
    const los = hasLOS(enemy,p);
    const hpR = p.hp/p.maxHp;
    const score = d*2 + hpR*10 - (los?5:0);
    if (score < best){ best = score; target = p; }
  }
  let dist = Math.abs(enemy.x-target.x)+Math.abs(enemy.y-target.y);
  let steps = enemy.move;
  while (steps > 0 && (dist > enemy.range || !hasLOS(enemy,target))){
    const dx = Math.sign(target.x-enemy.x);
    const dy = Math.sign(target.y-enemy.y);
    let moved = false;
    const order = Math.abs(target.x-enemy.x) >= Math.abs(target.y-enemy.y) ? [[dx,0],[0,dy]] : [[0,dy],[dx,0]];
    for (const [mx,my] of order){
      if (mx===0 && my===0) continue;
      const nx = enemy.x+mx, ny = enemy.y+my;
      const c = cellAt(nx,ny);
      if (!c || c.obstacle || c.unit) continue;
      const oc = cellAt(enemy.x,enemy.y); oc.unit = null;
      c.unit = enemy;
      enemy.x = nx; enemy.y = ny;
      enemy.facing = Math.abs(mx) > Math.abs(my) ? (mx>0?'E':'W') : (my>0?'S':'N');
      moved = true; break;
    }
    if (!moved) break;
    steps--;
    dist = Math.abs(enemy.x-target.x)+Math.abs(enemy.y-target.y);
    updateCombat();
    await sleep(150);
  }
  if (Math.abs(enemy.x-target.x)+Math.abs(enemy.y-target.y) <= enemy.range && hasLOS(enemy,target)){
    const cover = coverBonusFor(target,enemy);
    const f = computeFlank(enemy,target);
    const fMult = f === 'back' ? 1.5 : f === 'side' ? 1.25 : 1;
    const dmg = Math.max(1, Math.floor(enemy.damage * fMult) - target.armor - cover);
    tracer(enemy.x,enemy.y,target.x,target.y,'#ff2244');
    spawnParticles(enemy.x,enemy.y,'#ff2244',6,2);
    await sleep(120);
    spawnParticles(target.x,target.y,'#ff2244',16,3.5);
    flashHit(target);
    floatText(target.x,target.y,'-'+dmg,'#ff5566');
    shake('sm');
    target.hp -= dmg;
    logMsg(`${enemy.name} hits ${target.name} for ${dmg}.`, 'hit-enemy');
    if (target.hp <= 0) onUnitDeath(target);
    updateCombat();
    await sleep(420);
  }
  checkWinLose();
  if (!Game.gameOver) endUnitTurn();
}

// ================= WIN/LOSE =================
function checkWinLose(){
  const pa = Game.units.filter(u=>u.team==='player' && u.hp>0);
  const ea = Game.units.filter(u=>u.team==='enemy' && u.hp>0);
  if (pa.length === 0){
    Game.gameOver = true;
    showBanner('MISSION FAILED', '#ff2244');
    logMsg('=== MISSION FAILED ===', 'sys');
    updateCombat();
    setTimeout(()=>returnToOverworld(false), 2200);
  } else if (ea.length === 0){
    Game.gameOver = true;
    showBanner('MISSION COMPLETE', '#00ff88');
    logMsg('=== MISSION ACCOMPLISHED ===', 'good');
    const m = Game.activeMission;
    if (m){
      Game.credits += m.reward;
      logMsg(`+¢${m.reward}`, 'good');
      // Faction rep
      const contact = Game.contacts.find(c=>c.id===m.contact);
      if (contact && FACTIONS[contact.faction]){
        Game.rep[contact.faction] = (Game.rep[contact.faction]||0) + m.factionRepGain;
        logMsg(`+${m.factionRepGain} rep with ${FACTIONS[contact.faction].name}`, 'good');
      }
      if (m.factionRepLoss){
        Object.entries(m.factionRepLoss).forEach(([f,v])=>{
          Game.rep[f] = (Game.rep[f]||0) + v;
          logMsg(`${v} rep with ${FACTIONS[f].name}`, 'sys');
        });
      }
      Game.missionHistory.push({...m, day:Game.day});
      // XP
      Game.units.filter(u=>u.team==='player' && u.hp>0).forEach(cu=>{
        if (cu.rosterRef){
          cu.rosterRef.xp += m.xp;
          if (cu.rosterRef.xp >= cu.rosterRef.xpNext){
            cu.rosterRef.xp -= cu.rosterRef.xpNext;
            cu.rosterRef.level++;
            cu.rosterRef.xpNext = 100 * cu.rosterRef.level;
            cu.rosterRef.skillPoints += 1;
            logMsg(`${cu.rosterRef.name} leveled to ${cu.rosterRef.level}! +1 SP`, 'good');
          }
        }
      });
      Game.units.filter(u=>u.team==='player').forEach(cu=>{ if (cu.rosterRef) cu.rosterRef.hp = Math.max(1, cu.hp); });
      if (contact) contact.missions = contact.missions.filter(x=>x.id!==m.id);
      // Story triggers
      if (!Game.storyFlags.story_mission_1_complete){
        Game.storyFlags.story_mission_1_complete = true;
        setTimeout(()=>playStory('story_mission_1_success'), 2400);
      }
    }
    updateCombat();
    saveGame(0);
    setTimeout(()=>returnToOverworld(true), 2200);
  }
}

function returnToOverworld(success){
  Game.activeMission = null;
  Game.roster.forEach(u=>u.hp=u.maxHp);
  if (Game.screen === 'story') return;
  showScreen('overworld-screen');
  initOverworld();
  if (success) toast('Contract complete.');
  else toast('Mission failed.');
}

// ================= SAVE / LOAD =================
const SAVE_KEY = 'chrome_requiem_save_';

function serializeGame(){
  return JSON.stringify({
    version: 4,
    playerName: Game.playerName,
    playerClass: Game.playerClass,
    background: Game.background,
    credits: Game.credits,
    day: Game.day,
    hour: Game.hour,
    rep: Game.rep,
    roster: Game.roster,
    contacts: Game.contacts.map(c=>({ id:c.id, name:c.name, role:c.role, x:c.x, y:c.y, color:c.color, faction:c.faction, missions:c.missions })),
    vendors: Game.vendors,
    ovPlayer: Game.ovPlayer,
    missionHistory: Game.missionHistory,
    journal: Game.journal,
    storyFlags: Game.storyFlags,
    savedAt: Date.now()
  });
}

function saveGame(slot){
  try {
    localStorage.setItem(SAVE_KEY + slot, serializeGame());
    if (slot === 0) toast('Autosaved');
    else toast('Game saved.');
  } catch(e){ toast('Save failed: ' + e.message); }
}

function loadGame(slot){
  try {
    const raw = localStorage.getItem(SAVE_KEY + slot);
    if (!raw){ toast('Empty slot.'); return false; }
    const data = JSON.parse(raw);
    Game.playerName = data.playerName;
    Game.playerClass = data.playerClass;
    Game.background = data.background;
    Game.credits = data.credits;
    Game.day = data.day;
    Game.hour = data.hour;
    Game.rep = data.rep;
    Game.roster = data.roster;
    Game.contacts = data.contacts;
    Game.vendors = data.vendors;
    Game.ovPlayer = data.ovPlayer;
    Game.missionHistory = data.missionHistory || [];
    Game.journal = data.journal || [];
    Game.storyFlags = data.storyFlags || {};
    Game.loadedFromSave = true;
    showScreen('overworld-screen');
    initOverworld();
    toast('Loaded save.');
    return true;
  } catch(e){ toast('Load failed: ' + e.message); return false; }
}

function renderLoadMenu(){
  const el = document.getElementById('load-slots');
  el.innerHTML = '';
  [0,1,2].forEach(slot => {
    const raw = localStorage.getItem(SAVE_KEY + slot);
    const card = document.createElement('button');
    card.className = 'btn';
    card.style.cssText = 'width:100%;margin-bottom:6px;text-align:left;padding:10px 14px;';
    if (raw){
      try {
        const d = JSON.parse(raw);
        const date = new Date(d.savedAt);
        const label = slot === 0 ? 'AUTOSAVE' : `SLOT ${slot}`;
        card.innerHTML = `<b>${label}</b> — ${d.playerName} (${d.playerClass}) · Day ${d.day} · ¢${d.credits}<br><span style="opacity:.6;font-size:9px;">${date.toLocaleString()}</span>`;
      } catch(e){
        card.innerHTML = `<b>SLOT ${slot}</b> — corrupt`;
      }
      card.addEventListener('click', () => { loadGame(slot); });
    } else {
      const label = slot === 0 ? 'AUTOSAVE' : `SLOT ${slot}`;
      card.innerHTML = `<b>${label}</b> — empty`;
      card.disabled = true;
    }
    el.appendChild(card);
  });
}



