const SAVE_VERSION = 5;
const INJURY_DEFS = {
  broken_arm:{name:'Broken Arm',desc:'−2 damage',damage:-2},
  concussion:{name:'Concussion',desc:'−1 AP',ap:-1},
  leg_trauma:{name:'Leg Trauma',desc:'−1 move',move:-1},
  burns:{name:'Chrome Burns',desc:'−10 max HP',hp:-10}
};
const TRAIT_POOL = ['Paranoid','Ex-Corp','Idealist','Loyal','Hotshot','Streetwise','Pragmatist','Chrome Curious'];
const V5Original = {
  showScreen, initOverworld, resizeOverworld, onOverworldClick, generateMissions, setupWorld,
  startNewGame, makeUnit, applySkillsToUnit, renderRoster, openUnitModal, renderInventory,
  purchaseItem, openVendor, startMission, buildGrid, createCombatUnits, updateCombatActions,
  updateCombat, syncCombatUnits, moveUnit, basicAttack, onUnitDeath, executeTileItem, executeAbility,
  enemyAITakeTurn, endUnitTurn, advanceTurn, checkWinLose, returnToOverworld, advanceTime,
  triggerTravelEvent, serializeGame, loadGame
};

function hashString(str){let h=2166136261>>>0;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function seededRandom(){
  Game.rngState=(Game.rngState+0x6D2B79F5)|0;let t=Game.rngState;
  t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;
}
function pick(arr){return arr[Math.floor(seededRandom()*arr.length)]}
function ensureV5State(){
  if (!Number.isFinite(Game.rngState)) Game.rngState=hashString(`${Game.playerName||'Vex'}:${Game.day||1}:chrome`)|0;
  Game.turn=Game.turn||'player';
  Game.stash=Game.stash||{weapons:[],armor:[]};
  Game.safehouse=Game.safehouse||{workshop:1,infirmary:1,bar:1,server:1};
  Game.heat=Game.heat||{meridian:0,wraiths:0,iron:0,chrome:0,spine:0};
  Game.factionPower=Game.factionPower||{meridian:55,wraiths:45,iron:48,chrome:42,spine:35};
  Game.districtControl=Game.districtControl||{nero:'meridian',undercity:'wraiths',steelworks:'iron',neon:'chrome',spine:'spine',mirage:'meridian'};
  Game.rival=Game.rival||{name:'Black Halo',score:0,lastDay:Game.day||1};Game.achievements=Game.achievements||[];
  Game.objective=Game.objective||null; Game.alerted=!!Game.alerted; Game.turnNumber=Game.turnNumber||1;
  Game.losCache=Game.losCache||new Map(); Game.ovStaticDirty=Game.ovStaticDirty!==false;
  Game.roster.forEach(ensureUnitMeta);
  syncOwnedGear();
}
function ensureUnitMeta(u){
  if(!u) return u;
  if(!Array.isArray(u.traits)){const h=hashString(u.name+u.className);u.traits=[TRAIT_POOL[h%TRAIT_POOL.length],TRAIT_POOL[(h>>>4)%TRAIT_POOL.length]].filter((v,i,a)=>a.indexOf(v)===i)}
  if(!Number.isFinite(u.loyalty)) u.loyalty=u===Game.roster[0]?5:1;
  if(!u.opinions){const h=hashString(u.name);const f=Object.keys(FACTIONS);u.opinions={};f.forEach((k,i)=>u.opinions[k]=((h>>>(i*3))%5)-2)}
  if(!Array.isArray(u.injuries)) u.injuries=[];
  if(typeof u.personalUnlocked!=='boolean')u.personalUnlocked=false;if(!Number.isFinite(u.arcProgress))u.arcProgress=0;
  return u;
}
function syncOwnedGear(){
  Game.stash=Game.stash||{weapons:[],armor:[]};
  Game.roster.forEach(u=>{if(u.weapon&&!Game.stash.weapons.includes(u.weapon))Game.stash.weapons.push(u.weapon);if(u.armor_item&&!Game.stash.armor.includes(u.armor_item))Game.stash.armor.push(u.armor_item)});
}
function sfx(type){
  try{
    const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const a=sfx.ctx||(sfx.ctx=new AC());if(a.state==='suspended')a.resume();
    const now=a.currentTime,g=a.createGain();g.connect(a.destination);g.gain.setValueAtTime(.0001,now);
    if(type==='shot'){
      const len=Math.floor(a.sampleRate*.07),buf=a.createBuffer(1,len,a.sampleRate),d=buf.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);const src=a.createBufferSource();src.buffer=buf;const f=a.createBiquadFilter();f.type='highpass';f.frequency.value=500;src.connect(f);f.connect(g);g.gain.exponentialRampToValueAtTime(.14,now+.004);g.gain.exponentialRampToValueAtTime(.0001,now+.08);src.start(now);src.stop(now+.09);
    }else{const o=a.createOscillator();o.connect(g);o.type=type==='emp'?'sawtooth':type==='hit'?'triangle':'square';o.frequency.setValueAtTime(type==='emp'?420:type==='hit'?180:620,now);o.frequency.exponentialRampToValueAtTime(type==='emp'?70:90,now+.11);g.gain.exponentialRampToValueAtTime(.08,now+.006);g.gain.exponentialRampToValueAtTime(.0001,now+.13);o.start(now);o.stop(now+.14)}
  }catch(e){}
}
window.addEventListener('pointerdown',()=>{if(sfx.ctx&&sfx.ctx.state==='suspended')sfx.ctx.resume()},{passive:true});
const Events={_m:new Map(),on(name,fn){if(!this._m.has(name))this._m.set(name,[]);this._m.get(name).push(fn)},emit(name,data){for(const fn of this._m.get(name)||[]){try{fn(data)}catch(e){console.error(e)}}}};
const ACHIEVEMENTS={first_blood:'FIRST BLOOD',ghost:'GHOST CONTRACT',hard_case:'HARD CASE',faction_ally:'CONNECTED',chrome_max:'FULLY CHROMED'};
function unlockAchievement(id){Game.achievements=Game.achievements||[];if(Game.achievements.includes(id))return;Game.achievements.push(id);const n=ACHIEVEMENTS[id]||id;addJournal('main','Achievement',n);toast(`ACHIEVEMENT · ${n}`)}
Events.on('unit:died',u=>{if(u.team==='enemy')unlockAchievement('first_blood')});
Events.on('mission:success',m=>{if(Game.objective?.quiet)unlockAchievement('ghost');if(Game.roster.some(u=>u.hp>0&&u.hp<=10))unlockAchievement('hard_case');if(Object.values(Game.rep).some(v=>v>=70))unlockAchievement('faction_ally');if(Game.roster.some(u=>u.cyber?.length>=2))unlockAchievement('chrome_max')});
const BANTER={Hacker:{start:['Network is dirty. Give me a line and I can own it.'],win:['Their security stack is going to need a priest.'],fail:['I can scrub the logs. I cannot scrub broken bones.']},Gunslinger:{start:['Call the angles. I will handle the noise.'],win:['Clean enough. Pay better next time.'],fail:['That was ugly. I hate ugly.']},'Cyber Sword':{start:['Point me at the hard target.'],win:['Steel still settles arguments.'],fail:['Next time, I close the distance faster.']},Sniper:{start:['I have lanes. Keep them in my glass.'],win:['Target picture is empty.'],fail:['We stayed exposed too long.']},AgentEX:{start:['Quiet feet. Quiet room. Quiet payday.'],win:['They never saw the real attack.'],fail:['Someone saw too much.']}};
function crewBanter(kind='start'){const pool=Game.roster.filter(u=>u.hp>0);if(!pool.length)return;const u=pool[Math.floor(seededRandom()*pool.length)],lines=BANTER[u.className]?.[kind];if(lines?.length)logMsg(`${u.name}: “${pick(lines)}”`,'sys')}


// Screen lifecycle: animation loops stop when their owning screen exits.
showScreen=function(name){
  const prev=Game.screen;
  if(prev==='overworld-screen'&&name!==prev&&Game.ovAnim){cancelAnimationFrame(Game.ovAnim);Game.ovAnim=null}
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));const el=document.getElementById(name);if(el)el.classList.add('active');Game.screen=name;
};

// Mobile/touch-safe world selection: click/tap computes its own tile instead of relying on hover.
onOverworldClick=function(e){
  if(e&&Game.ovCanvas){const rect=Game.ovCanvas.getBoundingClientRect(),tile=Game.ovTile,offX=(rect.width-OV_W*tile)/2,offY=(rect.height-OV_H*tile)/2;const tx=Math.floor((e.clientX-rect.left-offX)/tile),ty=Math.floor((e.clientY-rect.top-offY)/tile);if(tx>=0&&tx<OV_W&&ty>=0&&ty<OV_H)Game.hoverTile={x:tx,y:ty}}
  if(!Game.hoverTile)return;const{x,y}=Game.hoverTile;
  const contact=Game.contacts.find(c=>c.x===x&&c.y===y);if(contact&&Math.abs(contact.x-Game.ovPlayer.x)<=4&&Math.abs(contact.y-Game.ovPlayer.y)<=4){openContactPanel(contact);return}
  const vendor=Game.vendors.find(v=>v.x===x&&v.y===y);if(vendor&&Math.abs(vendor.x-Game.ovPlayer.x)<=4&&Math.abs(vendor.y-Game.ovPlayer.y)<=4){openVendor(vendor);return}
  if(!isWalkable(x,y)){toast('Blocked.');return}const path=findPath(Game.ovPlayer,{x,y});if(path&&path.length>1){Game.pendingPath=path;if(path.length>5&&seededRandom()<.35)Game.storyFlags._pendingTravelEvent=path.length;toast(`Moving (${path.length-1} tiles)`)}else toast('No route.');
};

initOverworld=function(){
  ensureV5State();V5Original.initOverworld();ensureSafehouseButton();
  if(!Game.storyFlags.tutorialSeen&&(Game.storyFlags.prologue_start||Game.storyFlags.prologue_rebel)){Game.storyFlags.tutorialSeen=true;setTimeout(showTutorial,450)}
};
function showTutorial(){
  const modal=document.getElementById('modal'),inner=document.getElementById('modal-inner');
  inner.innerHTML=`<h2>FIELD BRIEFING</h2><p><b>1.</b> Tap a contact marker for contracts. Different contract types now have different win conditions.</p><p><b>2.</b> In combat, yellow ◆ tiles are objectives. Use the OBJECTIVE action when it appears.</p><p><b>3.</b> Gunfire raises ALERT. AgentEX, cloaking and silent takedowns let you reach objectives before the room wakes up.</p><p>Damage and injuries persist after missions. Use the <b>SAFE</b> button between jobs.</p><button class="btn primary" id="tutorial-ok" style="width:100%">UNDERSTOOD</button>`;
  inner.querySelector('#tutorial-ok').onclick=()=>modal.classList.remove('open');modal.classList.add('open');
}
function ensureSafehouseButton(){
  const bar=document.querySelector('#overworld-screen .topbar');if(!bar||document.getElementById('ov-safe-btn'))return;const b=document.createElement('button');b.className='btn small orange';b.id='ov-safe-btn';b.textContent='SAFE';b.onclick=openSafehouse;bar.insertBefore(b,document.getElementById('ov-menu-btn'));
}
function openSafehouse(){
  ensureV5State();const modal=document.getElementById('modal'),inner=document.getElementById('modal-inner');const injuries=Game.roster.flatMap(u=>u.injuries.map(i=>`${u.name}: ${INJURY_DEFS[i]?.name||i}`));const healBase=Game.roster.reduce((n,u)=>n+Math.max(0,u.maxHp-u.hp)*2,0),healCost=Math.max(60,Math.round(healBase*(1-Math.min(.45,(Game.safehouse.infirmary-1)*.15))));const treatCost=injuries.length?Math.max(100,260-(Game.safehouse.infirmary-1)*45):0;
  inner.innerHTML=`<h2>SAFEHOUSE</h2><p>Your crew's one place to disappear, repair and plan.</p>${injuries.length?`<div class="warning-box">INJURIES: ${injuries.join(' · ')}</div>`:''}<div class="safe-grid">${[['workshop','WORKSHOP','Weapon and armor vendors are 5% cheaper per upgrade (max 20%).'],['infirmary','INFIRMARY','Cheaper healing and injury treatment.'],['bar','BAR','Crew morale, rumors and recruitment network.'],['server','SERVER ROOM','Unlocks rare black-market stock.']].map(([k,n,d])=>`<div class="safe-room"><b>${n} · LV ${Game.safehouse[k]}</b><p>${d}</p><button class="btn small" data-upgrade="${k}">UPGRADE ¢${600*Game.safehouse[k]}</button></div>`).join('')}</div><div class="upgrade-row"><div class="name">Heal entire crew</div><div class="cost">¢ ${healCost}</div><button class="btn small" id="safe-heal" ${Game.credits<healCost?'disabled':''}>HEAL</button></div><div class="upgrade-row"><div class="name">Treat one injury</div><div class="cost">¢ ${treatCost}</div><button class="btn small" id="safe-treat" ${!injuries.length||Game.credits<treatCost?'disabled':''}>TREAT</button></div><button class="btn magenta" id="safe-close" style="width:100%;margin-top:10px">LEAVE</button>`;
  inner.querySelectorAll('[data-upgrade]').forEach(btn=>btn.onclick=()=>{const k=btn.dataset.upgrade,c=600*Game.safehouse[k];if(Game.credits<c)return;Game.credits-=c;Game.safehouse[k]++;updateOverworldHUD();saveGame(0);openSafehouse()});
  inner.querySelector('#safe-heal').onclick=()=>{if(Game.credits<healCost)return;Game.credits-=healCost;Game.roster.forEach(u=>u.hp=u.maxHp);updateOverworldHUD();saveGame(0);openSafehouse()};
  inner.querySelector('#safe-treat').onclick=()=>{if(Game.credits<treatCost)return;const u=Game.roster.find(x=>x.injuries.length);if(!u)return;Game.credits-=treatCost;const gone=u.injuries.shift();applySkillsToUnit(u);addJournal('main','Recovery',`${u.name} recovered from ${INJURY_DEFS[gone]?.name||gone}.`);updateOverworldHUD();saveGame(0);openSafehouse()};
  inner.querySelector('#safe-close').onclick=()=>modal.classList.remove('open');modal.classList.add('open');
}

// New game state, crew traits and shared owned-gear stash.
startNewGame=function(name,className,background){Game.rngState=hashString(`${name}:${className}:${background}:chrome-requiem-v5`)|0;Game.stash={weapons:[],armor:[]};Game.safehouse={workshop:1,infirmary:1,bar:1,server:1};Game.heat={meridian:0,wraiths:0,iron:0,chrome:0,spine:0};Game.factionPower={meridian:55,wraiths:45,iron:48,chrome:42,spine:35};Game.districtControl={nero:'meridian',undercity:'wraiths',steelworks:'iron',neon:'chrome',spine:'spine',mirage:'meridian'};Game.rival={name:'Black Halo',score:0,lastDay:1};V5Original.startNewGame(name,className,background);Game.roster.forEach(ensureUnitMeta);if(Game.roster[0])Game.roster[0].loyalty=5;syncOwnedGear();saveGame(0)};
makeUnit=function(name,className,level){const u=V5Original.makeUnit(name,className,level);ensureUnitMeta(u);return u};

applySkillsToUnit=function(u){
  if(!u)return;ensureUnitMeta(u);const oldMax=Math.max(1,u.maxHp||1),oldHp=Math.max(0,u.hp??oldMax),ratio=Math.min(1,oldHp/oldMax);V5Original.applySkillsToUnit(u);
  for(const id of u.injuries){const inj=INJURY_DEFS[id];if(!inj)continue;if(inj.damage)u.damage=Math.max(1,u.damage+inj.damage);if(inj.move)u.move=Math.max(1,u.move+inj.move);if(inj.ap)u.maxAp=Math.max(1,u.maxAp+inj.ap);if(inj.hp)u.maxHp=Math.max(20,u.maxHp+inj.hp)}
  u.ap=Math.min(u.ap,u.maxAp);u.hp=oldHp<=0?0:Math.max(1,Math.min(u.maxHp,Math.round(u.maxHp*ratio)));
};

renderRoster=function(body){
  body.innerHTML='';Game.roster.forEach((u,i)=>{ensureUnitMeta(u);const el=document.createElement('div');el.className='crew-card'+(i===Game.selectedCrewIndex?' active':'');el.innerHTML=`<div class="crew-portrait">${window.CRAssets?.classPortrait?.(u.className,u.name)||SPRITES[u.className]}</div><div class="crew-info"><div class="crew-name">${u.name}</div><div class="crew-class">${u.className} · LVL ${u.level}</div><div class="crew-stats"><span>HP <b>${u.hp}/${u.maxHp}</b></span><span>DMG <b>${u.damage}</b></span><span>ARM <b>${u.armor}</b></span><span>LOY <b>${u.loyalty>=0?'+':''}${u.loyalty}</b></span></div><div class="meta-chips">${u.traits.map(t=>`<span class="meta-chip">${t}</span>`).join('')}${u.injuries.map(id=>`<span class="meta-chip injury">${INJURY_DEFS[id]?.name||id}</span>`).join('')}${u.personalUnlocked?'<span class="meta-chip loyal">PERSONAL PERK</span>':''}</div></div><div class="crew-level">${u.level}</div>`;el.onclick=()=>{Game.selectedCrewIndex=i;renderCrewScreen();openUnitModal(u)};body.appendChild(el)});
};
openUnitModal=function(u){
  ensureUnitMeta(u);const modal=document.getElementById('modal'),inner=document.getElementById('modal-inner'),healCost=Math.max(50,(u.maxHp-u.hp)*3),injury=u.injuries[0],treatCost=injury?260:0;
  inner.innerHTML=`<h2>${u.name} · ${u.className}</h2><p>Level ${u.level} · XP ${u.xp}/${u.xpNext} · Loyalty ${u.loyalty>=0?'+':''}${u.loyalty}</p><div class="meta-chips">${u.traits.map(t=>`<span class="meta-chip">${t}</span>`).join('')}${u.injuries.map(id=>`<span class="meta-chip injury">${INJURY_DEFS[id]?.name||id}: ${INJURY_DEFS[id]?.desc||''}</span>`).join('')}</div><div class="stat-row"><span>Health</span><b>${u.hp}/${u.maxHp}</b></div><div class="stat-row"><span>Damage</span><b>${u.damage}</b></div><div class="stat-row"><span>Armor</span><b>${u.armor}</b></div><div class="stat-row"><span>Move / AP</span><b>${u.move} / ${u.maxAp}</b></div><div class="stat-row"><span>Weapon</span><b>${ITEMS[u.weapon]?.name||'—'}</b></div><div class="stat-row"><span>Armor</span><b>${ITEMS[u.armor_item]?.name||'—'}</b></div><div class="upgrade-row"><div class="name">Field repair</div><div class="cost">¢ ${healCost}</div><button class="btn small" id="modal-heal" ${u.hp>=u.maxHp||Game.credits<healCost?'disabled':''}>HEAL</button></div>${injury?`<div class="upgrade-row"><div class="name">Treat ${INJURY_DEFS[injury]?.name||injury}</div><div class="cost">¢ ${treatCost}</div><button class="btn small" id="modal-treat" ${Game.credits<treatCost?'disabled':''}>TREAT</button></div>`:''}<button class="btn magenta" id="modal-close" style="width:100%;margin-top:12px">CLOSE</button>`;
  const hb=inner.querySelector('#modal-heal');if(hb)hb.onclick=()=>{if(Game.credits>=healCost){Game.credits-=healCost;u.hp=u.maxHp;updateOverworldHUD();openUnitModal(u)}};const tb=inner.querySelector('#modal-treat');if(tb)tb.onclick=()=>{if(Game.credits>=treatCost&&u.injuries.length){Game.credits-=treatCost;u.injuries.shift();applySkillsToUnit(u);openUnitModal(u)}};inner.querySelector('#modal-close').onclick=()=>{modal.classList.remove('open');renderCrewScreen()};modal.classList.add('open');
};

renderInventory=function(body){
  ensureV5State();const u=Game.roster[Game.selectedCrewIndex];if(!u){body.innerHTML='<p>No unit selected.</p>';return}body.innerHTML=`<div style="display:flex;gap:10px;align-items:center;margin-bottom:10px"><div style="font-family:'Orbitron';font-size:12px;letter-spacing:2px;color:var(--cyan)">${u.name.toUpperCase()}</div><div style="flex:1"></div><div style="font-family:'Orbitron';font-size:10px;color:var(--orange)">¢ ${Game.credits.toLocaleString()}</div></div>`;
  const ownedW=Game.stash.weapons.filter(k=>ITEMS[k]);const ownedA=Game.stash.armor.filter(k=>ITEMS[k]);body.appendChild(section('OWNED WEAPONS',ownedW.map(k=>makeSlot(k,ITEMS[k],u,'weapon'))));body.appendChild(section('OWNED ARMOR',ownedA.map(k=>makeSlot(k,ITEMS[k],u,'armor'))));
  const cyber=Object.entries(ITEMS).filter(([k,v])=>v.type==='cyber'&&(u.cyber.includes(k)||u.inventory['owned_'+k])).map(([k,v])=>makeSlot(k,v,u,'cyber'));body.appendChild(section('CYBERWARE',cyber));
  const cons=Object.entries(ITEMS).filter(([k,v])=>v.type==='consumable'),grid=document.createElement('div');grid.className='inv-grid';cons.forEach(([k,v])=>{const el=document.createElement('div');el.className='inv-slot';el.innerHTML=`${ICONS[v.icon]||''}<div class="name">${v.name}</div><div class="qty">×${u.inventory[k]||0}</div>`;grid.appendChild(el)});const sec=document.createElement('div');sec.className='inv-section';sec.innerHTML='<h3>CONSUMABLES</h3>';sec.appendChild(grid);body.appendChild(sec);
};

