ITEMS.rifle_mk2={name:'Warhawk AR // VECTOR',type:'weapon',icon:'rifle',dmg:14,range:6,ap:2,desc:'Rare tuned rifle. +range, +damage.',rare:true};WEAPON_PRICES.rifle_mk2=2100;
ITEMS.blade_monoedge={name:'Ronin // Monoedge',type:'weapon',icon:'blade',dmg:22,range:1,ap:1,bleed:true,desc:'Unique monoedge. Brutal close damage.',rare:true};WEAPON_PRICES.blade_monoedge=2400;
ITEMS.armor_adaptive={name:'Adaptive Weave',type:'armor',icon:'armor_stealth',armor:4,hp:18,stealth:true,desc:'Rare stealth/combat hybrid.',rare:true};ARMOR_PRICES.armor_adaptive=2300;
ABILITY_DEFS['Deadeye Protocol']={cost:1,range:0,target:'self',icon:'cyber_optics',desc:'Next basic attack is a guaranteed critical hit.'};
ABILITY_DEFS['Adrenal Overdrive']={cost:1,range:0,target:'self',icon:'cyber_reflex',desc:'Suffer 10 HP to gain +2 AP now.'};
ABILITY_DEFS['Zero Day']={cost:2,range:6,target:'enemy',icon:'emp',desc:'Disable and mark a target for 2 turns.'};
