ABILITY_DEFS['Vanish']={cost:1,range:0,target:'self',icon:'armor_stealth',desc:'Cloak for 2 turns.'};
const PERSONAL_ABILITY={Hacker:'Zero Day',Gunslinger:'Deadeye Protocol','Cyber Sword':'Adrenal Overdrive',Sniper:'Ghost Round',AgentEX:'Vanish'};

openVendor=function(vendor){ensureV5State();const fac=vendor.id==='v_gun'?'iron':vendor.type==='armor'?'meridian':vendor.type==='cyber'?'chrome':'spine';const canRare=(Game.rep[fac]||0)>=40||Game.safehouse.server>=3;if(canRare){if(vendor.type==='weapon'){for(const k of ['rifle_mk2','blade_monoedge'])if(!vendor.stock.includes(k))vendor.stock.push(k)}if(vendor.type==='armor'&&!vendor.stock.includes('armor_adaptive'))vendor.stock.push('armor_adaptive')}V5Original.openVendor(vendor)};
purchaseItem=function(vendor,itemKey,price,item){
  if(Game.credits<price){toast('Not enough credits.');return}ensureV5State();Game.credits-=price;const target=Game.roster[Game.selectedCrewIndex]||Game.roster[0];
  if(item.type==='consumable')target.inventory[itemKey]=(target.inventory[itemKey]||0)+1;
  else if(item.type==='cyber'){if(target.cyber.includes(itemKey)){Game.credits+=price;toast('Already installed.');return}if(target.cyber.length>=2){Game.credits+=price;toast('Max 2 cyberware.');return}target.cyber.push(itemKey);target.inventory['owned_'+itemKey]=1;applySkillsToUnit(target)}
  else if(item.type==='weapon'){if(!Game.stash.weapons.includes(itemKey))Game.stash.weapons.push(itemKey);target.weapon=itemKey;applySkillsToUnit(target)}
  else if(item.type==='armor'){if(!Game.stash.armor.includes(itemKey))Game.stash.armor.push(itemKey);target.armor_item=itemKey;applySkillsToUnit(target)}
  toast(`Purchased ${item.name}.`);updateOverworldHUD();document.getElementById('vendor-cr').innerHTML=`¢ <b style="color:#ffaa00">${Game.credits.toLocaleString()}</b>`;saveGame(0);
};

// Mission generation: faction-specific enemies and actual objective metadata.
generateMissions=function(){
  ensureV5State();const templates=[
    {type:'eliminate',name:'Sweep & Clear',desc:'Neutralize the hostile cell.',base:520},
    {type:'extract',name:'Data Extraction',desc:'Reach the terminal and complete a 3-stage upload.',base:700},
    {type:'sabotage',name:'Sabotage Grid',desc:'Plant charges on two infrastructure nodes.',base:780},
    {type:'bounty',name:'Priority Bounty',desc:'Kill the marked target. Other hostiles are optional.',base:900},
    {type:'heist',name:'Black ICE Heist',desc:'Hack three nodes in order. The alarm escalates after first breach.',base:1050},
    {type:'hold',name:'Hot Extraction',desc:'Hold the extraction beacon for three turns.',base:850}
  ];
  const pool={meridian:['Guard','Enforcer','Drone'],wraiths:['Drone','Enforcer','Guard'],iron:['Guard','Heavy','Brute'],chrome:['Enforcer','Brute','Heavy'],spine:['Guard','Drone','Enforcer']};
  for(const c of Game.contacts){c.missions=[];const crep=Game.rep[c.faction]||0;if(crep<=-50)continue;const count=2+Math.floor(seededRandom()*2)+(crep>=70?1:0);for(let i=0;i<count;i++){const t=pick(templates),diff=1+Math.floor(seededRandom()*3);let targets=Object.keys(FACTIONS).filter(f=>f!==c.faction);const targetFac=pick(targets),ep=pool[targetFac];let enemies=[];const n=2+diff;if(t.type==='bounty'){enemies=[...(Array.from({length:Math.max(2,diff)},()=>pick(ep))),diff===3?'Boss':'Enforcer']}else enemies=Array.from({length:n},()=>pick(ep));const bonus=crep>=30?1.15:1;c.missions.push({id:`m_${c.id}_${Game.day}_${i}_${Math.floor(seededRandom()*9999)}`,contact:c.id,type:t.type,name:t.name,desc:t.desc,enemies,diff,reward:Math.round((t.base+diff*180+seededRandom()*180)*bonus),xp:70+diff*35,targetFaction:targetFac,factionRepGain:6+diff*2,factionRepLoss:{[targetFac]:-(6+diff*2)},objective:t.type})}}
};

// Real objective system.
function objectiveCellsFor(type){
  if(type==='extract')return[{x:5,y:4,kind:'terminal'}];if(type==='sabotage')return[{x:4,y:4,kind:'relay'},{x:6,y:6,kind:'relay'}];if(type==='heist')return[{x:3,y:6,kind:'node'},{x:5,y:4,kind:'node'},{x:7,y:2,kind:'node'}];if(type==='hold')return[{x:5,y:5,kind:'beacon'}];return[];
}
function setupObjective(mission){
  const type=mission.objective||mission.type||'eliminate',cells=objectiveCellsFor(type);
  const needsExfil=type==='extract'||type==='heist';
  // This is transient mission state. It is deliberately excluded from campaign saves.
  Game.objective={type,cells,progress:0,required:type==='extract'?3:type==='hold'?3:cells.length,completed:false,quiet:true,preAlarmClean:true,targetId:null,exfil:needsExfil?{x:1,y:8}:null,exfilReady:false,exfilAnnounced:false};
  cells.forEach((o,i)=>{const c=cellAt(o.x,o.y);if(c){c.obstacle=false;c.cover=false;c.hazard=false;c.objectiveIndex=i;c.el.className='cell objective-cell'}});
  if(needsExfil){
    const c=cellAt(1,8);
    if(c){c.obstacle=false;c.cover=false;c.hazard=false;c.rubble=false;c.objectiveIndex=null;c.el.className='cell v14-exfil-cell';c.el.dataset.exfil='1';}
  }
  ensureObjectiveHud();updateObjectiveHud();
}
function ensureObjectiveHud(){const board=document.getElementById('board');if(!board)return;let h=document.getElementById('objective-hud');if(!h){h=document.createElement('div');h.id='objective-hud';board.appendChild(h)}}
function objectiveText(){
  const o=Game.objective;if(!o)return'OBJECTIVE';
  if(o.exfilReady)return'PAYLOAD SECURED · EXFILTRATION COMPLETE';
  if(o.completed&&o.exfil)return`PAYLOAD SECURED · RETURN TO EXFIL [${String(o.exfil.x).padStart(2,'0')},${String(o.exfil.y).padStart(2,'0')}] · 1 AP`;
  if(o.type==='eliminate')return'ELIMINATE · Neutralize all hostiles';
  if(o.type==='bounty')return'BOUNTY · Eliminate the marked target';
  if(o.type==='extract')return`EXTRACT DATA · Upload ${o.progress}/${o.required} · THEN EXFIL`;
  if(o.type==='sabotage')return`SABOTAGE · Charges ${o.progress}/${o.required}`;
  if(o.type==='heist')return`HEIST · Node ${Math.min(o.progress+1,o.required)}/${o.required}${Game.alerted?' · ALARM ACTIVE':' · UNDETECTED'} · THEN EXFIL`;
  if(o.type==='hold')return`HOT EXTRACTION · Hold ${o.progress}/${o.required}`;
  return o.type.toUpperCase();
}
function updateObjectiveHud(){const h=document.getElementById('objective-hud');if(h){h.classList.toggle('v14-exfil-stage',!!Game.objective?.completed&&!!Game.objective?.exfil);h.innerHTML=`<div class="obj-title">CONTRACT OBJECTIVE</div>${objectiveText()}`}}
function markObjectiveCellDone(i){const o=Game.objective?.cells?.[i];if(!o)return;const c=cellAt(o.x,o.y);if(c)c.el.classList.add('objective-done')}
function nearObjective(u,o,range=0){return Math.abs(u.x-o.x)+Math.abs(u.y-o.y)<=range}
function objectiveActionAvailable(u){
  const o=Game.objective;if(!o)return null;
  if(o.completed){
    if(o.exfil&&!o.exfilReady&&nearObjective(u,o.exfil,1))return{label:'EXFIL · 1 AP',run:()=>completeExfiltration(u)};
    return null;
  }
  if(o.type==='extract'&&nearObjective(u,o.cells[0]))return{label:'UPLOAD',run:()=>progressObjective(u)};
  if(o.type==='sabotage'){const idx=o.cells.findIndex((c,i)=>!c.done&&nearObjective(u,c,1));if(idx>=0)return{label:'PLANT CHARGE',run:()=>progressObjective(u,idx)}}
  if(o.type==='heist'){const idx=o.progress;if(o.cells[idx]&&nearObjective(u,o.cells[idx]))return{label:'BREACH NODE',run:()=>progressObjective(u,idx)}}
  return null;
}
function completeExfiltration(u){
  const o=Game.objective;
  if(Game.gameOver||Game.turn!=='player'||Game.selectedUnit!==u||u.team!=='player'||u.hp<=0||u.ap<1||!o?.completed||!o.exfil||o.exfilReady||!nearObjective(u,o.exfil,1))return false;
  u.ap--;o.exfilReady=true;
  logMsg(`${u.name} confirms squad extraction. Payload transmitted.`, 'good');
  updateObjectiveHud();checkWinLose();return true;
}
function progressObjective(u,idx=0){
  const o=Game.objective;if(!o||u.ap<1){logMsg('Need 1 AP.','sys');return}u.ap--;sfx('emp');
  if(o.type==='extract'){o.progress++;floatText(u.x,u.y,`UPLOAD ${o.progress}/${o.required}`,'#ffe060');if(o.progress>=o.required)o.completed=true}
  else if(o.type==='sabotage'){const c=o.cells[idx];if(c&&!c.done){c.done=true;o.progress++;markObjectiveCellDone(idx);floatText(c.x,c.y,'CHARGE SET','#ff6600');if(o.progress>=o.required)o.completed=true}}
  else if(o.type==='heist'){if(idx===o.progress){o.cells[idx].done=true;markObjectiveCellDone(idx);o.progress++;floatText(u.x,u.y,'NODE BREACHED','#00f0ff');if(o.progress===1){o.preAlarmClean=!Game.alerted;setAlerted('ICE alarm tripped')}if(o.progress>=o.required)o.completed=true}}
  if(o.completed&&o.exfil&&!o.exfilAnnounced){
    o.exfilAnnounced=true;
    logMsg('Payload secured. Return an operative to the green EXFIL marker and spend 1 AP.', 'good');
    showBanner('RETURN TO EXFIL', '#79f4b6');
  }
  updateObjectiveHud();updateCombat();checkWinLose();
}

buildGrid=function(mission){
  const gridEl=document.getElementById('grid');gridEl.innerHTML='';Game.grid=[];if(!gridEl.dataset.delegated){gridEl.addEventListener('click',e=>{const cell=e.target.closest('.cell');if(cell)onCombatCellClick(+cell.dataset.x,+cell.dataset.y)});gridEl.dataset.delegated='1'}
  const mh=hashString(mission.id||mission.name||'mission');for(let y=0;y<GRID_SIZE;y++)for(let x=0;x<GRID_SIZE;x++){const cell=document.createElement('div');cell.className='cell';cell.dataset.x=x;cell.dataset.y=y;gridEl.appendChild(cell);let obstacle=false,cover=false,hazard=false;const seed=(x*13+y*31+(mh%97))%100;if(seed<9&&!(x<3&&y>6)&&!(x>6&&y<3))obstacle=true;if(!obstacle&&seed>60&&seed<74)cover=true;if(!obstacle&&!cover&&seed>88&&seed<93)hazard=true;const c={x,y,obstacle,cover,hazard,unit:null,el:cell,coverDir:null,coverHp:cover?15:0,coverMax:cover?15:0,rubble:false};Game.grid.push(c);if(obstacle)cell.classList.add('obstacle');else if(cover){cell.classList.add('cover');c.coverDir=['N','S','E','W'][(x+y)%4]}else if(hazard)cell.classList.add('hazard')}
  Game.losCache=new Map();setupObjective(mission);
};
createCombatUnits=function(mission){V5Original.createCombatUnits(mission);const stealth=['heist','extract'].includes(mission.type);Game.units.filter(u=>u.team==='enemy').forEach((e,i)=>{e.awareness=stealth?0:100;e.alerted=!stealth;e.disabledTurns=e.disabledTurns||0;if(mission.type==='bounty'&&i===Game.units.filter(x=>x.team==='enemy').length-1){e.isObjectiveTarget=true;e.name='TARGET // '+e.name;Game.objective.targetId=e.name}});Game.alerted=!stealth;Game.turnNumber=1;updateObjectiveHud()};

startMission=function(mission){
  document.getElementById('contact-panel').classList.remove('open');Game.activeMission=mission;ensureV5State();Game.roster.forEach(u=>{u.ap=u.maxAp;u.wasDowned=false});advanceTime(30);setTimeout(()=>{showScreen('combat');initCombat(mission)},180)
};

// Timed statuses + objective hold progress.
function tickEndStatuses(u){
  if(!u||!u.statuses)return;if(u.statuses.burn){u.hp-=5;damageCoverAt(cellAt(u.x,u.y),5);floatText(u.x,u.y,'-5 BURN','#ff6600');u.statuses.burn--;if(u.statuses.burn<=0)delete u.statuses.burn;if(u.hp<=0)onUnitDeath(u)}
  if(u.statuses.poison){u.hp-=4;floatText(u.x,u.y,'-4 POISON','#88ff22');u.statuses.poison--;if(u.statuses.poison<=0)delete u.statuses.poison;if(u.hp<=0)onUnitDeath(u)}if(u.statuses.bleed){u.hp-=6;floatText(u.x,u.y,'-6 BLEED','#ff2244');u.statuses.bleed--;if(u.statuses.bleed<=0)delete u.statuses.bleed;if(u.hp<=0)onUnitDeath(u)}if(u.statuses.shock){u.statuses.shock--;if(u.statuses.shock<=0)delete u.statuses.shock}if(u.statuses.marked){u.statuses.marked--;if(u.statuses.marked<=0)delete u.statuses.marked}if(u.statuses.cloak){u.statuses.cloak--;if(u.statuses.cloak<=0)delete u.statuses.cloak}
  if(u.statuses.armor_up){u.statuses.armor_up--;if(u.statuses.armor_up<=0){u.armor=Math.max(0,u.armor-3);delete u.statuses.armor_up}}
}
endUnitTurn=async function(){const cur=Game.turnQueue[Game.turnIndex];if(cur){tickEndStatuses(cur);cur.ap=0;if(Game.objective?.type==='hold'&&cur.team==='player'&&!Game.objective.completed&&nearObjective(cur,Game.objective.cells[0])){Game.objective.progress++;floatText(cur.x,cur.y,`HOLD ${Game.objective.progress}/${Game.objective.required}`,'#ffe060');if(Game.objective.progress>=Game.objective.required)Game.objective.completed=true;updateObjectiveHud();checkWinLose()}}Game.turnIndex++;updateCombat();renderInitiative();await sleep(130);advanceTurn()};

// Coalesced UI update: one DOM/render pass per animation frame.
let combatUpdateScheduled=false;
function renderCombatNow(){checkBossPhases();syncCombatUnits();refreshCombatHighlights();updateCombatHUD();updateCombatActions();updateObjectiveHud()}
updateCombat=function(){if(combatUpdateScheduled)return;combatUpdateScheduled=true;requestAnimationFrame(()=>{combatUpdateScheduled=false;renderCombatNow()})};

// LOS cache is safe for the mission because only cover (not blocking obstacles) is destructible.
hasLOS=function(from,to){const key=`${from.x},${from.y}>${to.x},${to.y}`;if(Game.losCache?.has(key))return Game.losCache.get(key);const line=bresenhamLine(from.x,from.y,to.x,to.y);let ok=true;for(let i=1;i<line.length-1;i++){const c=cellAt(line[i].x,line[i].y);if(c&&c.obstacle){ok=false;break}}if(Game.losCache)Game.losCache.set(key,ok);return ok};
coverBonusFor=function(t,a){const skills=a.rosterRef?.skills||a.skills||a.abilities||[];if(skills.includes('g_trick'))return 0;const tc=cellAt(t.x,t.y);if(!tc)return 0;if(tc.rubble)return 1;if(!tc.cover)return 0;const dx=a.x-t.x,dy=a.y-t.y,dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'E':'W'):(dy>0?'S':'N');return tc.coverDir===dir?3:1};
function combatPathDistance(u,tx,ty){
  if(u.x===tx&&u.y===ty)return 0;const q=[{x:u.x,y:u.y,d:0}],seen=new Set([`${u.x},${u.y}`]);while(q.length){const cur=q.shift();for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const x=cur.x+dx,y=cur.y+dy,k=`${x},${y}`,c=cellAt(x,y);if(!c||seen.has(k)||c.obstacle||(c.unit&&!(x===tx&&y===ty)))continue;const d=cur.d+1;if(x===tx&&y===ty)return d;seen.add(k);q.push({x,y,d})}}return Infinity;
}
refreshCombatHighlights=function(){Game.grid.forEach(c=>{if(c.el)c.el.classList.remove('move-range','attack-range','flank-range','los-blocked')});const u=Game.selectedUnit;if(!u||Game.gameOver||u.team!=='player'||Game.turn!=='player')return;Game.grid.forEach(c=>{if(c.obstacle)return;const d=Math.abs(u.x-c.x)+Math.abs(u.y-c.y);if(c.unit&&c.unit.team!==u.team&&c.unit.hp>0&&d<=u.range&&hasLOS(u,c.unit)){const f=computeFlank(u,c.unit);c.el.classList.add(f==='front'?'attack-range':'flank-range')}else if(!c.unit&&combatPathDistance(u,c.x,c.y)<=u.move&&!(c.x===u.x&&c.y===u.y))c.el.classList.add('move-range')})};
function damageCoverAt(c,amount){if(!c||!c.cover)return;c.coverHp-=amount;if(c.coverHp<=0){c.cover=false;c.rubble=true;c.el.classList.remove('cover');c.el.classList.add('rubble');floatText(c.x,c.y,'COVER DOWN','#ffaa00');spawnParticles(c.x,c.y,'#ffaa00',18,3);sfx('hit')}}

// Awareness/stealth.
function setAlerted(reason){if(Game.alerted)return;Game.alerted=true;Game.objective&&(Game.objective.quiet=false);Game.units.filter(u=>u.team==='enemy').forEach(e=>{e.awareness=100;e.alerted=true});logMsg(`ALERT: ${reason}`,'sys');showBanner('ALERT','#ff2244');sfx('emp');updateObjectiveHud()}
function updateAwarenessForMove(mover){if(mover.team!=='player'||Game.alerted)return;for(const e of Game.units.filter(x=>x.team==='enemy'&&x.hp>0)){const d=Math.abs(e.x-mover.x)+Math.abs(e.y-mover.y);if(d>6||!hasLOS(e,mover))continue;const gain=mover.statuses.cloak?8:(mover.className==='AgentEX'?18:30);e.awareness=Math.min(100,(e.awareness||0)+gain);if(e.awareness>=100){setAlerted(`${e.name} spotted ${mover.name}`);break}else if(e.awareness>=60)logMsg(`${e.name} is suspicious (${e.awareness}%).`,'sys')}}
moveUnit=function(u,x,y){V5Original.moveUnit(u,x,y);if(u.team==='player')updateAwarenessForMove(u);else{const c=cellAt(x,y);if(c?.hazard&&u.hp>0){u.hp-=8;floatText(x,y,'-8 HAZARD','#ff6600');if(u.hp<=0)onUnitDeath(u)}}};

function unitSkills(u){return u?.rosterRef?.skills||u?.skills||u?.abilities||[]}
function hasSkill(u,id){return unitSkills(u).includes(id)}

// Multiple overwatch shooters now all react. Snapshot eligibility before shots mutate state.
triggerOverwatch=function(mover){const opp=mover.team==='player'?'enemy':'player',shooters=Game.units.filter(u=>u.team===opp&&u.overwatch&&u.hp>0&&Math.abs(u.x-mover.x)+Math.abs(u.y-mover.y)<=u.range&&hasLOS(u,mover));shooters.forEach((u,i)=>{u.overwatch=false;logMsg(`${u.name} OVERWATCH!`,u.team==='player'?'good':'sys');setTimeout(()=>{if(mover.hp>0){u._reactionAttack=true;basicAttack(u,mover);u._reactionAttack=false}},120+i*140)})};

basicAttack=function(a,t){
  const weapon=ITEMS[a.weapon]||{},reaction=!!a._reactionAttack,cost=reaction?0:(weapon.ap||1);if(!reaction&&a.ap<cost){logMsg(`Need ${cost} AP for ${weapon.name||'attack'}.`,'sys');return}
  const tc=cellAt(t.x,t.y),silent=a.team==='player'&&['blade','mono'].includes(a.weapon);if(a.team==='player'&&!silent)setAlerted('gunfire');sfx(silent?'hit':'shot');const unaware=t.team==='enemy'&&!Game.alerted&&(t.awareness||0)<100,flank=computeFlank(a,t),oldDmg=a.damage;
  let mult=1;if(unaware&&silent&&flank==='back')mult*=1.35;if(hasSkill(a,'s_rage')&&a.hp<a.maxHp*.5)mult*=1.2;if(hasSkill(a,'h_brute')&&(t.disabledTurns>0||t.statuses?.shock))mult*=1.25;a.damage=Math.floor(a.damage*mult);
  const preAp=a.ap,oldCrit=a.critChance;if(a.statuses?.deadeye){a.critChance=100;delete a.statuses.deadeye}V5Original.basicAttack(a,t);a.damage=oldDmg;a.critChance=oldCrit;if(reaction)a.ap=preAp;else if(cost>1)a.ap-=cost-1;
  setTimeout(()=>{
    damageCoverAt(tc,3);if(unaware&&silent&&t.hp>0)setAlerted('failed silent takedown');
    if(t.hp>0&&weapon.burst){const d=Math.max(1,Math.floor(oldDmg*.45)-t.armor);t.hp-=d;floatText(t.x,t.y,'-'+d,'#ffaa00');logMsg(`${a.name}'s burst adds ${d} damage.`,'hit-player');if(t.hp<=0)onUnitDeath(t)}
    if(weapon.aoe){Game.units.filter(e=>e.team!==a.team&&e!==t&&e.hp>0&&Math.abs(e.x-t.x)+Math.abs(e.y-t.y)<=1).forEach(e=>{const d=Math.max(1,Math.floor(oldDmg*.35)-Math.floor(e.armor/2));e.hp-=d;floatText(e.x,e.y,'-'+d,'#ff6600');if(e.hp<=0)onUnitDeath(e)})}
    if(weapon.chain){const e=Game.units.find(e=>e.team!==a.team&&e!==t&&e.hp>0&&Math.abs(e.x-t.x)+Math.abs(e.y-t.y)<=2);if(e){const d=Math.max(1,Math.floor(oldDmg*.5)-e.armor);e.hp-=d;tracer(t.x,t.y,e.x,e.y,'#00f0ff');floatText(e.x,e.y,'-'+d,'#00f0ff');if(e.hp<=0)onUnitDeath(e)}}
    if(weapon.bleed&&t.hp>0){t.statuses.bleed=Math.max(t.statuses.bleed||0,2);floatText(t.x,t.y,'BLEED','#ff2244')}
    if(weapon.pierce){const dx=Math.sign(t.x-a.x),dy=Math.sign(t.y-a.y),behind=Game.units.find(e=>e.team!==a.team&&e!==t&&e.hp>0&&e.x===t.x+dx&&e.y===t.y+dy);if(behind){const d=Math.max(1,Math.floor(oldDmg*.5)-behind.armor);behind.hp-=d;tracer(t.x,t.y,behind.x,behind.y,'#00ff88');floatText(behind.x,behind.y,'-'+d,'#00ff88');if(behind.hp<=0)onUnitDeath(behind)}}
    checkBossPhases();checkWinLose();updateCombat();
  },180)
};
onUnitDeath=function(u){Events.emit('unit:died',u);if(u.team==='player'&&u.rosterRef)u.rosterRef.wasDowned=true;V5Original.onUnitDeath(u);const board=document.getElementById('board');board.classList.remove('killcam');void board.offsetWidth;board.classList.add('killcam');sfx('hit');if(u.isObjectiveTarget&&Game.objective){Game.objective.completed=true;updateObjectiveHud();setTimeout(checkWinLose,100)}};

// Smoke/riposte no longer stack permanent armor.
executeTileItem=function(item,x,y){const cur=Game.selectedUnit;if(!cur||!cur.inventory[item.key]||cur.inventory[item.key]<=0)return;cur.inventory[item.key]--;const r=item.radius||1;Game.units.filter(u=>Math.abs(u.x-x)+Math.abs(u.y-y)<=r&&u.hp>0).forEach(t=>{if(item.stun&&t.team==='enemy'){t.disabledTurns=Math.max(t.disabledTurns||0,item.stun);floatText(t.x,t.y,'STUN','#b060ff')}if(item.smoke&&t.team==='player'){if(!t.statuses.armor_up)t.armor+=3;t.statuses.armor_up=Math.max(t.statuses.armor_up||0,2);floatText(t.x,t.y,'SMOKE','#8fa8b8')}});sfx('emp');shake('md');logMsg(`${cur.name} uses ${item.name}.`,'sys');updateCombat()};
const baseExecuteAbility=V5Original.executeAbility;
executeAbility=function(ab,t){
  const u=Game.selectedUnit;if(!u)return;
  if(ab.sid==='Deadeye Protocol'){if(u.ap<1)return;u.ap--;u.statuses.deadeye=1;floatText(u.x,u.y,'DEADEYE','#ffe060');logMsg(`${u.name} primes a deadeye shot.`,'good');updateCombat();return}
  if(ab.sid==='Adrenal Overdrive'){if(u.ap<1||u.hp<=10)return;u.ap--;u.hp-=10;u.ap+=2;floatText(u.x,u.y,'+2 AP / -10 HP','#ff2244');logMsg(`${u.name} overdrives combat stimulators.`,'good');updateCombat();return}
  if(ab.sid==='Zero Day'){if(!t||u.ap<2)return;u.ap-=2;t.disabledTurns=Math.max(t.disabledTurns||0,2);t.statuses.marked=Math.max(t.statuses.marked||0,2);tracer(u.x,u.y,t.x,t.y,'#00f0ff');floatText(t.x,t.y,'ZERO DAY','#00f0ff');sfx('emp');updateCombat();return}
  if(ab.sid==='Ghost Round'){if(!t||u.ap<2)return;u.ap-=2;const dmg=Math.max(1,Math.floor(u.damage*1.8)-Math.floor(t.armor/2));t.hp-=dmg;tracer(u.x,u.y,t.x,t.y,'#00ff88');floatText(t.x,t.y,'-'+dmg,'#00ff88');logMsg(`${u.name} fires a ghost round for ${dmg}.`,'crit');if(t.hp<=0)onUnitDeath(t);checkWinLose();updateCombat();return}
  if(ab.sid==='Vanish'){if(u.ap<1)return;u.ap--;u.statuses.cloak=3;floatText(u.x,u.y,'VANISH','#6666ff');logMsg(`${u.name} drops off every local sensor.`,'good');updateCombat();return}
  if(ab.sid==='Riposte'){if(u.ap<ab.cost)return;u.ap-=ab.cost;if(!u.statuses.armor_up)u.armor+=3;u.statuses.armor_up=Math.max(u.statuses.armor_up||0,2);floatText(u.x,u.y,'+ARMOR','#ffe060');logMsg(`${u.name} braces for return fire.`,'good');updateCombat();return}
  baseExecuteAbility(ab,t);if(ab.sid==='Ghost Protocol'&&u){u.statuses.cloak=(hasSkill(u,'n_phase')||hasSkill(u,'a_veil'))?3:2}if(ab.sid==='Ghost in the Machine'&&t&&hasSkill(u,'h_override'))t.disabledTurns=Math.max(t.disabledTurns||0,2);if(ab.sid==='Overload'&&hasSkill(u,'h_burn'))Game.units.filter(e=>e.team!==u.team&&e.hp>0&&Math.abs(e.x-u.x)+Math.abs(e.y-u.y)<=3).forEach(e=>e.statuses.burn=Math.max(e.statuses.burn||0,2));if(ab.sid==='Backstab'&&t&&hasSkill(u,'a_poison'))t.statuses.poison=Math.max(t.statuses.poison||0,2);sfx(ab.sid==='Ghost in the Machine'||ab.sid==='Overload'?'emp':'hit');setTimeout(checkBossPhases,180)
};

updateCombatActions=function(){
  V5Original.updateCombatActions();const el=document.getElementById('actions'),u=Game.selectedUnit;if(!u||u.team!=='player'||Game.turn!=='player'||Game.gameOver)return;const act=objectiveActionAvailable(u);if(act){const b=document.createElement('button');b.className='item-btn'+(Game.objective?.completed&&Game.objective?.exfil?' v14-exfil-action':'');b.innerHTML=`${ICONS.cyber_neural}<span>${act.label}</span>`;b.disabled=u.ap<1;b.onclick=act.run;el.insertBefore(b,el.lastElementChild)}
  const enemies=Game.units.filter(e=>e.team==='enemy'&&e.hp>0&&(e.awareness||0)<100);const target=enemies.find(e=>Math.abs(e.x-u.x)+Math.abs(e.y-u.y)<=1&&computeFlank(u,e)==='back');if(target&&['blade','mono'].includes(u.weapon)&&u.ap>=1){const b=document.createElement('button');b.className='item-btn';b.innerHTML=`${ICONS.blade}<span>TAKEDOWN</span>`;b.onclick=()=>{u.ap--;const dmg=Math.max(40,Math.floor(u.damage*2.2));target.hp-=dmg;spawnParticles(target.x,target.y,'#b060ff',22,4);floatText(target.x,target.y,'-'+dmg,'#b060ff');logMsg(`${u.name} performs a silent takedown on ${target.name}.`,'crit');if(target.hp<=0)onUnitDeath(target);else setAlerted('takedown failed');checkWinLose();updateCombat()};el.insertBefore(b,el.lastElementChild)}
};

syncCombatUnits=function(){
  V5Original.syncCombatUnits();
  // PWA12.61: poison/bleed join the main status signature; keep the existing
  // awareness bar but reuse its DOM nodes and skip unchanged style/class writes.
  for(const u of Game.units){
    if(u.team!=='enemy'||!u.el)continue;
    let a=u._combatAwareness;
    if(!a||u._combatAwarenessEl!==u.el){
      a=u.el.querySelector('.awareness');
      if(!a){a=document.createElement('div');a.className='awareness';a.innerHTML='<i></i>';u.el.appendChild(a)}
      u._combatAwareness=a;
      u._combatAwarenessEl=u.el;
      u._combatAwarenessFill=a.querySelector('i');
      u._combatAwarenessWidth=undefined;
      u._combatAlerted=undefined;
    }
    const width=`${u.awareness??100}%`,alerted=(u.awareness??100)>=100;
    if(u._combatAwarenessWidth!==width){
      if(u._combatAwarenessFill)u._combatAwarenessFill.style.width=width;
      u._combatAwarenessWidth=width;
    }
    if(u._combatAlerted!==alerted){u.el.classList.toggle('alerted',alerted);u._combatAlerted=alerted}
  }
};

// Hazard-aware, awareness-aware enemy AI. PWA12.14 adds lightweight faction
// doctrine without changing initiative/AP rules or introducing real-time behavior.
const ENEMY_DOCTRINE_V14={
  meridian:{name:'SECURITY GRID',rangeBias:1.25,coverBias:3.0,woundedBias:5,flankBias:1.0,preferredRange:'long',behavior:'lockdown'},
  wraiths:{name:'GHOST HUNT',rangeBias:.85,coverBias:1.2,woundedBias:8,flankBias:3.0,preferredRange:'flank',behavior:'reposition'},
  iron:{name:'PRESSURE LINE',rangeBias:.55,coverBias:.5,woundedBias:4,flankBias:1.4,preferredRange:'close',behavior:'breach'},
  chrome:{name:'SHOCK ASSAULT',rangeBias:.7,coverBias:.8,woundedBias:6,flankBias:2.2,preferredRange:'close',behavior:'shock'},
  spine:{name:'CONTRACT FIRE',rangeBias:1.0,coverBias:1.8,woundedBias:7,flankBias:1.8,preferredRange:'mid',behavior:'focus'}
};
window.ENEMY_DOCTRINE_V14=ENEMY_DOCTRINE_V14;
// PWA12.26: unit-role layer. Doctrine answers how a faction fights; role answers
// what this body contributes to the squad. This keeps mixed enemy compositions
// tactically legible without changing initiative, AP, or wall-clock behavior.
const ENEMY_ROLE_V14={
  Guard:{name:'ANCHOR',rangeShift:1,coverBias:1.25,flankBias:0,targetWounded:0},
  Drone:{name:'SKIRMISHER',rangeShift:0,coverBias:.45,flankBias:1.35,targetWounded:1},
  Enforcer:{name:'HUNTER',rangeShift:0,coverBias:.7,flankBias:.85,targetWounded:2},
  Heavy:{name:'SUPPRESSOR',rangeShift:1,coverBias:1.4,flankBias:0,targetWounded:1},
  Brute:{name:'BREACHER',rangeShift:-2,coverBias:.1,flankBias:.25,targetWounded:1},
  Boss:{name:'COMMANDER',rangeShift:0,coverBias:1.0,flankBias:.5,targetWounded:2}
};
window.ENEMY_ROLE_V14=ENEMY_ROLE_V14;
function enemyRoleV14(enemy){return ENEMY_ROLE_V14[enemy?.className]||ENEMY_ROLE_V14.Enforcer}
// PWA12.20: deterministic doctrine telemetry for balance/QA. Metrics are observational only.
const DOCTRINE_TELEMETRY_V14={};
function doctrineMetricV14(doc,key,amount=1){const id=doc?.behavior||'unknown',m=DOCTRINE_TELEMETRY_V14[id]||(DOCTRINE_TELEMETRY_V14[id]={turns:0,moves:0,overwatch:0,flanks:0,breaches:0,shocks:0,attacks:0,damage:0,coveredTurns:0,flankAttacks:0,targetSelections:0,targetCounts:{},damageByTarget:{},roles:{}});m.roles=m.roles||{};m[key]=(m[key]||0)+amount}
function doctrineRoleMetricV14(doc,role,key,amount=1){const id=doc?.behavior||'unknown';doctrineMetricV14(doc,'turns',0);const m=DOCTRINE_TELEMETRY_V14[id],rid=role?.name||'UNKNOWN',r=m.roles[rid]||(m.roles[rid]={turns:0,moves:0,attacks:0,damage:0,coveredTurns:0,flankAttacks:0,targetSelections:0});r[key]=(r[key]||0)+amount}
function doctrineTargetMetricV14(doc,bucket,target,amount=1){const id=doc?.behavior||'unknown';doctrineMetricV14(doc,'targetSelections',0);const m=DOCTRINE_TELEMETRY_V14[id],key=doctrineTargetKeyV14(target)||'unknown';m[bucket]=m[bucket]||{};m[bucket][key]=(m[bucket][key]||0)+amount}
function doctrineTelemetrySnapshotV14(){return JSON.parse(JSON.stringify(DOCTRINE_TELEMETRY_V14))}
function doctrineTelemetrySummaryV14(){const out={};for(const[id,m]of Object.entries(DOCTRINE_TELEMETRY_V14)){const counts=Object.values(m.targetCounts||{}),total=counts.reduce((a,b)=>a+b,0),max=counts.length?Math.max(...counts):0,roles={};for(const[rid,r]of Object.entries(m.roles||{}))roles[rid]={...JSON.parse(JSON.stringify(r)),coverRate:r.turns?r.coveredTurns/r.turns:0,flankAttackRate:r.attacks?r.flankAttacks/r.attacks:0,damagePerAttack:r.attacks?r.damage/r.attacks:0,movesPerTurn:r.turns?r.moves/r.turns:0};out[id]={...JSON.parse(JSON.stringify(m)),roles,targetConcentration:total?max/total:0,coverRate:m.turns?m.coveredTurns/m.turns:0,flankAttackRate:m.attacks?m.flankAttacks/m.attacks:0,damagePerAttack:m.attacks?m.damage/m.attacks:0}}return out}
function resetDoctrineTelemetryV14(){Object.keys(DOCTRINE_TELEMETRY_V14).forEach(k=>delete DOCTRINE_TELEMETRY_V14[k])}
window.CR14DoctrineTelemetry=Object.freeze({snapshot:doctrineTelemetrySnapshotV14,summary:doctrineTelemetrySummaryV14,reset:resetDoctrineTelemetryV14});
function enemyDoctrineV14(){return ENEMY_DOCTRINE_V14[Game.activeMission?.targetFaction]||ENEMY_DOCTRINE_V14.spine}
function enemyCellScoreV14(enemy,target,c,doc){
  const d=Math.abs(c.x-target.x)+Math.abs(c.y-target.y),haz=c.hazard?20:0,role=enemyRoleV14(enemy);
  let ideal=Math.max(1,enemy.range-1);if(doc.preferredRange==='close')ideal=Math.min(2,enemy.range);else if(doc.preferredRange==='long')ideal=Math.max(2,enemy.range);ideal=Math.max(1,Math.min(enemy.range,ideal+role.rangeShift));
  const rangeGap=Math.abs(d-ideal)*doc.rangeBias,probe={x:c.x,y:c.y,facing:enemy.facing};const cover=coverBonusFor(probe,target)||0;
  const flankKind=computeFlank(probe,target),flank=flankKind==='back'?(doc.flankBias+role.flankBias):flankKind==='side'?(doc.flankBias+role.flankBias)*.5:0;
  return rangeGap+d*.35+haz-cover*(doc.coverBias+role.coverBias)-flank;
}
function doctrineTargetKeyV14(u){return u?.rosterRef?.id||u?.id||u?.name||null}
function doctrineSquadTargetBiasV14(enemy,p,doc){
  const key=doctrineTargetKeyV14(p);if(!key)return 0;
  const allies=Game.units.filter(u=>u!==enemy&&u.team==='enemy'&&u.hp>0&&u.doctrineTargetKey===key).length;
  // PWA12.22: faction squads now coordinate without changing initiative/AP rules.
  // Security Grid spreads lanes; pressure/shock/focus doctrines deliberately converge fire.
  if(doc.behavior==='lockdown')return allies*1.5;
  if(doc.behavior==='focus')return allies*-3.0;
  if(doc.behavior==='breach')return allies*-1.6;
  if(doc.behavior==='shock')return allies*-1.8;
  if(doc.behavior==='reposition')return allies*.8;
  return 0;
}
function enemyTargetScoreV14(enemy,p,doc){
  const d=Math.abs(enemy.x-p.x)+Math.abs(enemy.y-p.y),los=hasLOS(enemy,p),wounded=1-(p.hp/p.maxHp),flank=computeFlank(enemy,p),role=enemyRoleV14(enemy);
  let score=d*2-(doc.woundedBias+role.targetWounded)*wounded-(los?5:0)+doctrineSquadTargetBiasV14(enemy,p,doc);
  if(doc.behavior==='focus'&&p.statuses?.marked)score-=4;
  if(doc.behavior==='reposition'&&(flank==='side'||flank==='back'))score-=doc.flankBias*1.5;
  return score;
}
function enemyShouldRepositionV14(enemy,target,doc,dist){
  const role=enemyRoleV14(enemy);if(role.name==='BREACHER')return dist>1||!hasLOS(enemy,target);
  if(doc.behavior==='breach'||doc.behavior==='shock')return dist>Math.min(2,enemy.range)||!hasLOS(enemy,target);
  if(doc.behavior==='reposition'&&hasLOS(enemy,target)&&dist<=enemy.range){const f=computeFlank(enemy,target);return f==='front'&&enemy.move>0}
  return dist>enemy.range||!hasLOS(enemy,target);
}
function enemyDoctrineIntentV14(enemy,doc,text){enemy.doctrineIntent=text;logMsg(`${enemy.name} // ${doc.name}: ${text}`,'sys')}
async function enemyDoctrineFinishV14(enemy,target,doc,dist){
  if(doc.behavior==='lockdown'&&enemy.ap>0&&dist<=enemy.range&&hasLOS(enemy,target)){
    const cover=coverBonusFor(enemy,target)||0;
    if(cover>0&&target.hp/target.maxHp>.45){enemy.overwatch=true;enemy.ap=Math.max(0,enemy.ap-1);doctrineMetricV14(doc,'overwatch');enemyDoctrineIntentV14(enemy,doc,'locks the lane on Overwatch');updateCombat();await sleep(180);return true}
  }
  return false;
}
enemyAITakeTurn=async function(enemy){
  if(Game.gameOver||enemy.hp<=0||enemy.dead){endUnitTurn();return}if(enemy.disabledTurns>0){enemy.disabledTurns--;logMsg(`${enemy.name} is stunned.`,'sys');await sleep(300);endUnitTurn();return}enemy.ap=enemy.maxAp;enemy.overwatch=false;const players=Game.units.filter(u=>u.team==='player'&&u.hp>0);if(!players.length){endUnitTurn();return}
  const doctrine=enemyDoctrineV14(),role=enemyRoleV14(enemy);doctrineMetricV14(doctrine,'turns');doctrineRoleMetricV14(doctrine,role,'turns');enemy.doctrineRole=role.name;let target=players[0],best=Infinity;for(const p of players){const score=enemyTargetScoreV14(enemy,p,doctrine);if(score<best){best=score;target=p}}enemy.doctrineTargetKey=doctrineTargetKeyV14(target);doctrineMetricV14(doctrine,'targetSelections');doctrineRoleMetricV14(doctrine,role,'targetSelections');doctrineTargetMetricV14(doctrine,'targetCounts',target);if((coverBonusFor(enemy,target)||0)>0){doctrineMetricV14(doctrine,'coveredTurns');doctrineRoleMetricV14(doctrine,role,'coveredTurns')}
  if(!Game.alerted&&(enemy.awareness||0)<100){const d=Math.abs(enemy.x-target.x)+Math.abs(enemy.y-target.y);if(d<=6&&hasLOS(enemy,target)){enemy.awareness=Math.min(100,(enemy.awareness||0)+(target.statuses.cloak?12:42));if(enemy.awareness>=100)setAlerted(`${enemy.name} acquired a target`)}if(!Game.alerted){logMsg(`${enemy.name} scans the area (${enemy.awareness||0}% alert).`,'sys');await sleep(220);endUnitTurn();return}}
  let dist=Math.abs(enemy.x-target.x)+Math.abs(enemy.y-target.y),steps=enemy.move,repositioned=false;while(steps>0&&enemyShouldRepositionV14(enemy,target,doctrine,dist)){const candidates=[[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dy])=>cellAt(enemy.x+dx,enemy.y+dy)).filter(c=>c&&!c.obstacle&&!c.unit).sort((a,b)=>enemyCellScoreV14(enemy,target,a,doctrine)-enemyCellScoreV14(enemy,target,b,doctrine));if(!candidates.length)break;const before=enemyCellScoreV14(enemy,target,{...cellAt(enemy.x,enemy.y),x:enemy.x,y:enemy.y},doctrine),c=candidates[0];if(doctrine.behavior==='reposition'&&dist<=enemy.range&&hasLOS(enemy,target)&&enemyCellScoreV14(enemy,target,c,doctrine)>=before)break;const oc=cellAt(enemy.x,enemy.y);oc.unit=null;c.unit=enemy;const mx=c.x-enemy.x,my=c.y-enemy.y;enemy.x=c.x;enemy.y=c.y;enemy.facing=Math.abs(mx)>Math.abs(my)?(mx>0?'E':'W'):(my>0?'S':'N');repositioned=true;doctrineMetricV14(doctrine,'moves');doctrineRoleMetricV14(doctrine,role,'moves');if(c.hazard){enemy.hp-=8;floatText(c.x,c.y,'-8 HAZARD','#ff6600');if(enemy.hp<=0){onUnitDeath(enemy);checkWinLose();return}}steps--;dist=Math.abs(enemy.x-target.x)+Math.abs(enemy.y-target.y);updateCombat();await sleep(110)}
  if(repositioned){const f=computeFlank(enemy,target);if(doctrine.behavior==='reposition'&&(f==='side'||f==='back')){doctrineMetricV14(doctrine,'flanks');enemyDoctrineIntentV14(enemy,doctrine,`${f.toUpperCase()} angle acquired`)}else if(doctrine.behavior==='breach'&&dist<=2){doctrineMetricV14(doctrine,'breaches');enemyDoctrineIntentV14(enemy,doctrine,'breach distance achieved')}else if(doctrine.behavior==='shock'&&dist<=2){doctrineMetricV14(doctrine,'shocks');enemyDoctrineIntentV14(enemy,doctrine,'shock range achieved')}}
  if(await enemyDoctrineFinishV14(enemy,target,doctrine,dist)){if(!Game.gameOver)endUnitTurn();return}
  if(dist<=enemy.range&&hasLOS(enemy,target)){const cover=coverBonusFor(target,enemy),f=computeFlank(enemy,target),fm=f==='back'?1.5:f==='side'?1.25:1;let doctrineMult=1;if(doctrine.behavior==='shock'&&dist<=2)doctrineMult=1.12;const dmg=Math.max(1,Math.floor(enemy.damage*fm*doctrineMult)-target.armor-cover);doctrineMetricV14(doctrine,'attacks');doctrineRoleMetricV14(doctrine,role,'attacks');if(f==='side'||f==='back'){doctrineMetricV14(doctrine,'flankAttacks');doctrineRoleMetricV14(doctrine,role,'flankAttacks')}doctrineMetricV14(doctrine,'damage',dmg);doctrineRoleMetricV14(doctrine,role,'damage',dmg);doctrineTargetMetricV14(doctrine,'damageByTarget',target,dmg);tracer(enemy.x,enemy.y,target.x,target.y,'#ff2244');sfx('shot');await sleep(100);target.hp-=dmg;spawnParticles(target.x,target.y,'#ff2244',16,3);floatText(target.x,target.y,'-'+dmg,'#ff5566');damageCoverAt(cellAt(target.x,target.y),3);logMsg(`${enemy.name} hits ${target.name} for ${dmg}.`,'hit-enemy');if(doctrine.behavior==='shock'&&dist<=2&&target.hp>0){target.statuses.marked=Math.max(target.statuses.marked||0,1);floatText(target.x,target.y,'SHOCKED','#ff00aa')}if(target.hp<=0)onUnitDeath(target);await sleep(260)}checkWinLose();if(!Game.gameOver)endUnitTurn();
};

function checkBossPhases(){for(const b of Game.units.filter(u=>u.className==='Boss'&&u.hp>0)){if(!b.phase2&&b.hp<=b.maxHp*.5){b.phase2=true;b.armor+=2;showBanner('BOSS PHASE II','#ff00aa');logMsg(`${b.name} deploys emergency drones and hardens its plating.`,'sys');for(const pos of [[8,2],[7,1]])spawnEnemyReinforcement('Drone',pos[0],pos[1])}}}
function spawnEnemyReinforcement(type,x,y){const def=ENEMY_DEFS[type],c=cellAt(x,y);if(!c||c.obstacle||c.unit)return;const e={name:`${type} R`,className:type,team:'enemy',x,y,maxHp:def.hp,hp:def.hp,maxAp:def.ap,ap:def.ap,move:def.move,range:def.range,damage:def.dmg,armor:def.armor,critChance:5,weapon:def.weapon,abilities:[],inventory:{},statuses:{},facing:'S',overwatch:false,el:null,dead:false,speed:def.speed,awareness:100,alerted:true};Game.units.push(e);c.unit=e;Game.turnQueue.push(e);logMsg(`${type} reinforcement arrives.`,'sys')}

function addInjury(u){ensureUnitMeta(u);const ids=Object.keys(INJURY_DEFS),id=pick(ids);if(!u.injuries.includes(id))u.injuries.push(id);applySkillsToUnit(u);addJournal('main','Injury',`${u.name} suffered ${INJURY_DEFS[id].name}: ${INJURY_DEFS[id].desc}.`)}
function applyCrewReaction(m){
  const employer=Game.contacts.find(c=>c.id===m.contact)?.faction,target=m.targetFaction;
  for(const u of Game.roster.slice(1)){ensureUnitMeta(u);let delta=0;if(employer)delta+=Math.sign(u.opinions[employer]||0);if(target)delta-=Math.sign(u.opinions[target]||0);if(delta<0&&Game.safehouse?.bar>1&&seededRandom()<Math.min(.5,(Game.safehouse.bar-1)*.15))delta=0;u.loyalty=Math.max(-6,Math.min(8,u.loyalty+delta));
    if(u.loyalty>=2&&!u.personalUnlocked){u.arcProgress=Math.min(3,(u.arcProgress||0)+1);if(u.arcProgress<3)addJournal('story',`${u.name}: Personal Thread ${u.arcProgress}/3`,`${u.name} opens up after the contract. Their trust is becoming operationally significant.`);if(u.arcProgress>=3){u.personalUnlocked=true;const ability=PERSONAL_ABILITY[u.className];if(ability&&!u.skills.includes(ability))u.skills.push(ability);addJournal('story',`${u.name}: Personal Arc Complete`,`${u.name} resolves a personal conflict and unlocks ${ability||'a unique technique'}.`)}}
  }
  const leaving=Game.roster.slice(1).filter(u=>u.loyalty<=-6);for(const u of leaving){addJournal('main','Crew Departure',`${u.name} left the crew after repeated ideological conflicts.`);Game.roster=Game.roster.filter(x=>x!==u)}
}
function finalizeMissionSuccess(){const m=Game.activeMission;if(!m)return;Game.gameOver=true;crewBanter('win');showBanner('MISSION COMPLETE','#00ff88');logMsg('=== MISSION ACCOMPLISHED ===','good');let reward=m.reward;if(Game.objective?.type==='heist'&&Game.objective.preAlarmClean)reward+=150;Game.credits+=reward;logMsg(`+¢${reward}`,'good');const contact=Game.contacts.find(c=>c.id===m.contact);if(contact&&FACTIONS[contact.faction])Game.rep[contact.faction]=(Game.rep[contact.faction]||0)+m.factionRepGain;if(m.factionRepLoss)for(const[f,v]of Object.entries(m.factionRepLoss)){Game.rep[f]=(Game.rep[f]||0)+v;Game.heat[f]=Math.min(100,(Game.heat[f]||0)+Math.max(0,-v)*2)}Game.missionHistory.push({...m,day:Game.day});Game.units.filter(u=>u.team==='player').forEach(cu=>{if(!cu.rosterRef)return;cu.rosterRef.hp=Math.max(1,cu.hp);if(cu.rosterRef.wasDowned)addInjury(cu.rosterRef);if(cu.hp>0){cu.rosterRef.xp+=m.xp;while(cu.rosterRef.xp>=cu.rosterRef.xpNext){cu.rosterRef.xp-=cu.rosterRef.xpNext;cu.rosterRef.level++;cu.rosterRef.xpNext=100*cu.rosterRef.level;cu.rosterRef.skillPoints++;applySkillsToUnit(cu.rosterRef)}}});if(contact)contact.missions=contact.missions.filter(x=>x.id!==m.id);applyCrewReaction(m);Events.emit('mission:success',m);if(!Game.storyFlags.story_mission_1_complete){Game.storyFlags.story_mission_1_complete=true;setTimeout(()=>playStory('story_mission_1_success'),2400)}saveGame(0);setTimeout(()=>returnToOverworld(true),2100)}
function finalizeMissionFailure(){const m=Game.activeMission;if(!m)return;Game.gameOver=true;crewBanter('fail');showBanner('MISSION FAILED','#ff2244');logMsg('=== MISSION FAILED ===','sys');const fee=Math.min(Game.credits,100+(m.diff||1)*75);Game.credits-=fee;logMsg(`Emergency extraction cost ¢${fee}.`,'sys');const contact=Game.contacts.find(c=>c.id===m.contact);if(contact)Game.rep[contact.faction]=(Game.rep[contact.faction]||0)-3;Game.units.filter(u=>u.team==='player').forEach(cu=>{if(!cu.rosterRef)return;if(cu.rosterRef.wasDowned||cu.hp<=0){cu.rosterRef.hp=Math.max(1,Math.floor(cu.rosterRef.maxHp*.25));addInjury(cu.rosterRef)}else cu.rosterRef.hp=Math.max(1,cu.hp)});advanceTime(180);saveGame(0);setTimeout(()=>returnToOverworld(false),2100)}
checkWinLose=function(){if(Game.gameOver)return;const pa=Game.units.filter(u=>u.team==='player'&&u.hp>0),ea=Game.units.filter(u=>u.team==='enemy'&&u.hp>0);if(!pa.length){finalizeMissionFailure();return}const o=Game.objective;let win=false;if(!o)win=!ea.length;else if(o.type==='eliminate')win=!ea.length;else if(o.type==='bounty')win=o.completed||!ea.some(e=>e.isObjectiveTarget&&e.hp>0);else win=!!o.completed&&(!o.exfil||o.exfilReady);if(win)finalizeMissionSuccess()};
returnToOverworld=function(success){Game.activeMission=null;Game.objective=null;Game.alerted=false;Game.roster.forEach(u=>{if(u.hp<=0)u.hp=1;u.ap=u.maxAp});if(Game.screen==='story')return;showScreen('overworld-screen');initOverworld();toast(success?'Contract complete. Injuries persist.':'Mission failed. Emergency extraction completed.')};

// Faction world simulation, rival crew, and heat-driven bounty hunters.
function simulateWorldDay(){
  ensureV5State();for(const f of Object.keys(Game.factionPower))Game.factionPower[f]=Math.max(10,Math.min(90,Game.factionPower[f]+Math.floor(seededRandom()*7)-3));if(seededRandom()<.32){const keys=['nero','undercity','steelworks','neon','mirage'],d=pick(keys),def=Game.districtControl[d],att=pick(Object.keys(FACTIONS).filter(f=>f!==def&&f!=='spine'));if(Game.factionPower[att]+seededRandom()*25>Game.factionPower[def]+12){Game.districtControl[d]=att;addJournal('main','District Shift',`${FACTIONS[att].name} seized control of ${d}.`)}}
  Game.rival.score+=1+Math.floor(seededRandom()*3);if(Game.day%3===0){const jobs=Game.contacts.flatMap(c=>c.missions.map(m=>({c,m})));if(jobs.length){const stolen=pick(jobs);stolen.c.missions=stolen.c.missions.filter(x=>x.id!==stolen.m.id);addJournal('main','Rival Crew',`${Game.rival.name} completed "${stolen.m.name}" before you could take it.`)}}
  for(const f of Object.keys(Game.heat))Game.heat[f]=Math.max(0,Game.heat[f]-2);
}
advanceTime=function(minutes){const oldDay=Game.day;V5Original.advanceTime(minutes);if(Game.day!==oldDay)for(let d=oldDay+1;d<=Game.day;d++)simulateWorldDay()};
getDistrict=function(x,y){let key,name;if(x<8&&y>8){key='nero';name='Nero District'}else if(x>14&&y<8){key='undercity';name='Undercity'}else if(x>14&&y>8){key='steelworks';name='Steelworks'}else if(x<8&&y<8){key='neon';name='Neon Row'}else if(y>=7&&y<=9){key='spine';name='The Spine'}else{key='mirage';name='Mirage Heights'}const faction=Game.districtControl?.[key]||({nero:'meridian',undercity:'wraiths',steelworks:'iron',neon:'chrome',spine:'spine',mirage:'meridian'}[key]);return{name,control:faction==='spine'?'NEUTRAL':FACTIONS[faction].name.toUpperCase(),faction}};
triggerTravelEvent=function(){ensureV5State();const hot=Object.entries(Game.heat).sort((a,b)=>b[1]-a[1])[0];if(hot&&hot[1]>=40&&seededRandom()<.45){const[f,heat]=hot,panel=document.getElementById('travel-event');document.getElementById('te-title').textContent='BOUNTY HUNTERS';document.getElementById('te-text').textContent=`${FACTIONS[f].name} has put a live bounty on your crew. A hunter team closes the street.`;const ch=document.getElementById('te-choices');ch.innerHTML='';const fight=document.createElement('button');fight.className='btn';fight.textContent='Stand and fight';fight.onclick=()=>{panel.classList.remove('open');Game.heat[f]=Math.max(0,heat-15);startMission({id:`hunter_${Game.day}_${f}`,contact:null,type:'eliminate',objective:'eliminate',name:`${FACTIONS[f].short} Hunter Team`,desc:'Survive the faction hit squad.',enemies:['Enforcer','Enforcer',heat>70?'Boss':'Brute'],diff:Math.min(3,1+Math.floor(heat/35)),reward:250,xp:90,targetFaction:f,factionRepGain:0,factionRepLoss:{[f]:-4}})};const pay=document.createElement('button');pay.className='btn';const cost=300+heat*5;pay.textContent=`Burn contacts and disappear (¢${cost})`;pay.disabled=Game.credits<cost;pay.onclick=()=>{Game.credits-=cost;Game.heat[f]=Math.max(0,heat-25);panel.classList.remove('open');updateOverworldHUD()};ch.append(fight,pay);panel.classList.add('open');return}V5Original.triggerTravelEvent()};

// Save v5 with migrations; transient combat/canvas objects remain excluded.
serializeGame=function(){ensureV5State();return JSON.stringify({version:SAVE_VERSION,playerName:Game.playerName,playerClass:Game.playerClass,background:Game.background,credits:Game.credits,day:Game.day,hour:Game.hour,rep:Game.rep,roster:Game.roster,contacts:Game.contacts.map(c=>({id:c.id,name:c.name,role:c.role,x:c.x,y:c.y,color:c.color,faction:c.faction,missions:c.missions})),vendors:Game.vendors,ovPlayer:Game.ovPlayer,missionHistory:Game.missionHistory,journal:Game.journal,storyFlags:Game.storyFlags,rngState:Game.rngState,stash:Game.stash,safehouse:Game.safehouse,heat:Game.heat,factionPower:Game.factionPower,districtControl:Game.districtControl,rival:Game.rival,achievements:Game.achievements,savedAt:Date.now()})};
function migrateSave(data){data.version=data.version||4;data.stash=data.stash||{weapons:[],armor:[]};data.safehouse=data.safehouse||{workshop:1,infirmary:1,bar:1,server:1};data.heat=data.heat||{meridian:0,wraiths:0,iron:0,chrome:0,spine:0};data.factionPower=data.factionPower||{meridian:55,wraiths:45,iron:48,chrome:42,spine:35};data.districtControl=data.districtControl||{nero:'meridian',undercity:'wraiths',steelworks:'iron',neon:'chrome',spine:'spine',mirage:'meridian'};data.rival=data.rival||{name:'Black Halo',score:0,lastDay:data.day||1};data.achievements=data.achievements||[];data.rngState=Number.isFinite(data.rngState)?data.rngState:hashString(`${data.playerName||'Vex'}:${data.day||1}:migrated`)|0;(data.roster||[]).forEach(u=>{if(!Array.isArray(u.injuries))u.injuries=[];if(!Number.isFinite(u.loyalty))u.loyalty=1});data.version=SAVE_VERSION;return data}
loadGame=function(slot){try{const raw=localStorage.getItem(SAVE_KEY+slot);if(!raw){toast('Empty slot.');return false}const data=migrateSave(JSON.parse(raw));Game.playerName=data.playerName;Game.playerClass=data.playerClass;Game.background=data.background;Game.credits=data.credits;Game.day=data.day;Game.hour=data.hour;Game.rep=data.rep;Game.roster=data.roster||[];Game.contacts=data.contacts||[];Game.vendors=data.vendors||[];Game.ovPlayer=data.ovPlayer||{x:4,y:12};Game.missionHistory=data.missionHistory||[];Game.journal=data.journal||[];Game.storyFlags=data.storyFlags||{};Game.rngState=data.rngState;Game.stash=data.stash;Game.safehouse=data.safehouse;Game.heat=data.heat;Game.factionPower=data.factionPower;Game.districtControl=data.districtControl;Game.rival=data.rival;Game.achievements=data.achievements||[];Game.loadedFromSave=true;ensureV5State();Game.roster.forEach(u=>applySkillsToUnit(u));showScreen('overworld-screen');initOverworld();toast('Loaded v5 save.');return true}catch(e){toast('Load failed: '+e.message);return false}};

// Small mod API: content packs can extend mutable content dictionaries without editing rules.
window.ChromeRequiem={version:SAVE_VERSION,modules:{Events,Audio:{sfx},Rules:{combatPathDistance,hasLOS,coverBonusFor},Objectives:{progressObjective,objectiveActionAvailable}},registerContent(pack={}){if(pack.items)Object.assign(ITEMS,pack.items);if(pack.abilities)Object.assign(ABILITY_DEFS,pack.abilities);if(pack.factions)Object.assign(FACTIONS,pack.factions);return true},state:Game};

// Explicit v14 boundary around the final classic v5 kernel.
// Later ES modules should consume state/registries through CoreV14 instead of
// adding new direct dependencies on v5 lexical globals.
window.ChromeRequiemCoreV5=Object.freeze({
  version:5,
  get state(){return Game},
  get items(){return ITEMS},
  get abilities(){return ABILITY_DEFS},
  get factions(){return FACTIONS},
  get classes(){return CLASS_DEFS},
  get sprites(){return SPRITES},
  dimensions:Object.freeze({gridSize:GRID_SIZE,overworldWidth:OV_W,overworldHeight:OV_H}),
  getDistrict:(x,y)=>getDistrict(x,y),
  serialize:()=>serializeGame(),
  save:(slot=0,quiet=true)=>saveGame(slot,quiet),
  load:(slot=0)=>loadGame(slot),
  advanceTime:(minutes)=>advanceTime(minutes),
  startMission:(mission)=>startMission(mission),
  buildGrid:(mission)=>buildGrid(mission),
  createCombatUnits:(mission)=>createCombatUnits(mission),
  showScreen:(id)=>showScreen(id)
});

/* SOURCE: src/legacy/core-v5-api.js */
function kernel(){
  return globalThis.ChromeRequiemCoreV5??null;
}
function call(name,...args){
  const k=kernel(),fn=k?.[name];
  if(typeof fn!=='function')throw new Error(`CoreV14 kernel function unavailable: ${name}`);
  return fn(...args);
}

const CoreV14=Object.freeze({
  version:5,
  get state(){return kernel()?.state??null},
  get items(){return kernel()?.items??null},
  get abilities(){return kernel()?.abilities??null},
  get factions(){return kernel()?.factions??null},
  get classes(){return kernel()?.classes??null},
  get sprites(){return kernel()?.sprites??null},
  get dimensions(){return kernel()?.dimensions??Object.freeze({gridSize:10,overworldWidth:0,overworldHeight:0})},
  getDistrict:(...args)=>call('getDistrict',...args),
  serialize:(...args)=>call('serialize',...args),
  save:(...args)=>call('save',...args),
  load:(...args)=>call('load',...args),
  advanceTime:(...args)=>call('advanceTime',...args),
  startMission:(...args)=>call('startMission',...args),
  buildGrid:(...args)=>call('buildGrid',...args),
  createCombatUnits:(...args)=>call('createCombatUnits',...args),
  showScreen:(...args)=>call('showScreen',...args)
});

if(typeof globalThis!=='undefined'){
  globalThis.ChromeRequiemV14Domains=globalThis.ChromeRequiemV14Domains||{};
  globalThis.ChromeRequiemV14Domains.CoreV14=CoreV14;
}

