function v6rgba(hex,a){
  if(!hex||hex[0]!=='#') return `rgba(0,240,255,${a})`;
  let h=hex.slice(1); if(h.length===3) h=h.split('').map(c=>c+c).join('');
  const n=parseInt(h,16); return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;
}
function v6seed(x,y,s=0){let n=(x*374761393+y*668265263+s*1442695041)|0;n=(n^(n>>>13))*1274126177;n^=n>>>16;return((n>>>0)%10000)/10000}

function v6Human(o={}){
  const a=o.accent||'#00f0ff', p=o.primary||'#1a2634', s=o.secondary||'#0c1118', skin=o.skin||'#b98b76';
  const coat=o.coat?`<path d="M24 43 L18 72 L31 70 L40 55 L49 70 L62 72 L56 43 Z" fill="${s}" stroke="${a}" stroke-opacity=".35" stroke-width="1"/>`:'';
  const hood=o.hood?`<path d="M27 20 Q40 7 53 20 L50 33 H30 Z" fill="${s}" stroke="${a}" stroke-opacity=".48" stroke-width="1.2"/>`:'';
  const mask=o.mask?`<path d="M30 26 L50 26 L48 35 Q40 39 32 35 Z" fill="#080b10" stroke="${a}" stroke-width="1"/><path d="M34 29 H46" stroke="${a}" stroke-width="2"/>`:'';
  const visor=o.visor?`<path d="M31 25 H49 L47 31 H33 Z" fill="${v6rgba(a,.75)}" stroke="#dfffff" stroke-opacity=".45" stroke-width=".7"/>`:'';
  const shoulders=o.shoulders?`<path d="M21 39 L29 33 L34 40 L27 46 Z M59 39 L51 33 L46 40 L53 46 Z" fill="${p}" stroke="${a}" stroke-opacity=".6"/>`:'';
  const cyber=o.cyber?`<path d="M54 41 L62 45 L59 61 L53 58 Z" fill="#101a23" stroke="${a}" stroke-width="1.3"/><circle cx="58" cy="49" r="2" fill="${a}"/><path d="M57 52 L55 59" stroke="${a}" stroke-width="1"/>`:'';
  let weapon='';
  if(o.weapon==='rifle') weapon=`<g transform="rotate(-12 47 48)"><rect x="44" y="39" width="27" height="5" rx="2" fill="#151b23" stroke="${a}" stroke-width="1"/><rect x="60" y="37" width="9" height="2" fill="${a}"/><path d="M48 44 L43 55 L48 56 L52 45" fill="#171d24"/><circle cx="58" cy="41.5" r="1.2" fill="#fff" opacity=".65"/></g>`;
  if(o.weapon==='pistol') weapon=`<g><path d="M55 44 H69 V49 H62 L60 56 H55 L57 48 H53 Z" fill="#171e27" stroke="${a}" stroke-width="1"/><rect x="65" y="45" width="6" height="2" fill="${a}"/></g>`;
  if(o.weapon==='dual') weapon=`<g><path d="M55 43 H69 V47 H62 L60 53 H56 L57 47 H53 Z" fill="#171e27" stroke="${a}"/><path d="M25 43 H11 V47 H18 L20 53 H24 L23 47 H27 Z" fill="#171e27" stroke="${a}"/></g>`;
  if(o.weapon==='blade') weapon=`<g transform="rotate(7 57 42)"><path d="M55 16 L62 49 L58 51 L52 18 Z" fill="#d9ffff" stroke="${a}" stroke-width="1.4"/><path d="M56 22 L59 45" stroke="${a}" stroke-width="1.4"/><rect x="53" y="48" width="10" height="3" rx="1" fill="#232b35"/></g>`;
  if(o.weapon==='mono') weapon=`<g><path d="M57 20 Q69 34 60 55" fill="none" stroke="#eaffff" stroke-width="1.4"/><path d="M57 20 Q69 34 60 55" fill="none" stroke="${a}" stroke-width="4" opacity=".25"/><rect x="56" y="52" width="7" height="6" rx="2" fill="#18212a" stroke="${a}"/></g>`;
  const antenna=o.antenna?`<path d="M47 17 L54 8" stroke="${a}" stroke-width="1.2"/><circle cx="55" cy="7" r="2" fill="${a}"/>`:'';
  const extra=o.extra||'';
  return `<svg viewBox="0 0 80 80" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <ellipse cx="40" cy="71" rx="18" ry="4" fill="rgba(0,0,0,.30)"/>
    ${coat}${hood}
    <path d="M30 36 Q40 31 50 36 L55 58 L48 66 H32 L25 58 Z" fill="${p}" stroke="#05080c" stroke-width="1.5"/>
    <path d="M31 39 H49 L52 56 L46 61 H34 L28 56 Z" fill="${s}" stroke="${a}" stroke-opacity=".34" stroke-width="1"/>
    <path d="M34 39 L40 45 L46 39 L44 55 H36 Z" fill="${v6rgba(a,.15)}"/>
    ${shoulders}
    <path d="M31 18 Q40 11 49 18 L50 30 Q47 37 40 38 Q33 37 30 30 Z" fill="${skin}" stroke="#080b10" stroke-width="1.3"/>
    <path d="M29 22 Q40 13 51 22 L49 18 Q40 9 31 18 Z" fill="#171b23"/>
    ${mask}${visor}${antenna}
    <path d="M28 42 L20 48 L23 62 L29 58 Z" fill="${p}" stroke="#090c11" stroke-width="1.2"/>
    <path d="M52 42 L60 48 L57 62 L51 58 Z" fill="${p}" stroke="#090c11" stroke-width="1.2"/>
    ${cyber}${weapon}
    <path d="M34 65 L31 74 H38 L41 65 Z M46 65 L49 74 H42 L39 65 Z" fill="#10161e" stroke="#06080c" stroke-width="1.2"/>
    <path d="M31 74 H39" stroke="${a}" stroke-opacity=".45" stroke-width="1.4"/><path d="M41 74 H49" stroke="${a}" stroke-opacity=".45" stroke-width="1.4"/>
    <circle cx="40" cy="48" r="2.5" fill="${a}" opacity=".9"/><circle cx="40" cy="48" r="5" fill="none" stroke="${a}" stroke-opacity=".22"/>
    ${extra}
  </svg>`;
}
function v6Drone(){return `<svg viewBox="0 0 80 80" xmlns="http://www.w3.org/2000/svg"><ellipse cx="40" cy="68" rx="19" ry="4" fill="rgba(0,0,0,.32)"/><path d="M20 33 L29 23 H51 L60 33 L55 49 L45 56 H35 L25 49 Z" fill="#17232d" stroke="#ff405f" stroke-width="1.5"/><path d="M25 33 H55" stroke="#ff405f" stroke-opacity=".45"/><circle cx="40" cy="38" r="7" fill="#070a0d" stroke="#ff405f" stroke-width="1.5"/><circle cx="40" cy="38" r="3" fill="#ff405f"/><path d="M22 39 L10 45 L22 49 M58 39 L70 45 L58 49" fill="#111820" stroke="#ff405f"/><path d="M31 54 L27 64 M49 54 L53 64" stroke="#8f9aa5" stroke-width="3"/><circle cx="27" cy="64" r="3" fill="#ff405f"/><circle cx="53" cy="64" r="3" fill="#ff405f"/></svg>`}
function buildV6Sprites(){
  return {
    Hacker:v6Human({accent:'#00f0ff',primary:'#19354a',secondary:'#091721',hood:true,mask:true,cyber:true,weapon:'pistol',antenna:true,extra:'<path d="M20 34 Q13 38 16 50" fill="none" stroke="#00f0ff" stroke-width="1" opacity=".6"/><circle cx="16" cy="51" r="2" fill="#00f0ff"/>'}),
    Gunslinger:v6Human({accent:'#ffb144',primary:'#49301d',secondary:'#1d120b',coat:true,weapon:'dual',shoulders:true,extra:'<path d="M24 61 L18 70 M56 61 L62 70" stroke="#ffb144" stroke-opacity=".45"/>'}),
    'Cyber Sword':v6Human({accent:'#ff3f84',primary:'#4a1730',secondary:'#190914',mask:true,cyber:true,weapon:'blade',shoulders:true,extra:'<path d="M27 32 L22 24 M53 32 L58 24" stroke="#ff3f84" stroke-width="1.5"/>'}),
    Sniper:v6Human({accent:'#95ff67',primary:'#263a27',secondary:'#0d160f',coat:true,hood:true,visor:true,weapon:'rifle',extra:'<path d="M24 51 L16 61" stroke="#95ff67" stroke-opacity=".3"/>'}),
    AgentEX:v6Human({accent:'#c06dff',primary:'#312047',secondary:'#120b1c',coat:true,mask:true,visor:true,weapon:'mono',cyber:true,extra:'<path d="M18 35 Q13 47 20 63" fill="none" stroke="#c06dff" stroke-opacity=".32"/>'}),
    Guard:v6Human({accent:'#ff566d',primary:'#402127',secondary:'#190c0f',mask:true,weapon:'rifle'}),
    Enforcer:v6Human({accent:'#ff763b',primary:'#4a2618',secondary:'#1d0d08',mask:true,weapon:'rifle',shoulders:true,cyber:true}),
    Drone:v6Drone(),
    Brute:v6Human({accent:'#ff553d',primary:'#4b1a15',secondary:'#1b0807',mask:true,weapon:'blade',shoulders:true,cyber:true,extra:'<path d="M24 34 L17 30 M56 34 L63 30" stroke="#ff553d" stroke-width="2"/>'}),
    Boss:v6Human({accent:'#ffd65f',primary:'#382b35',secondary:'#120f16',coat:true,hood:true,mask:true,weapon:'rifle',shoulders:true,cyber:true,antenna:true,extra:'<path d="M26 37 H54" stroke="#ffd65f" stroke-width="1.3"/><path d="M26 60 H54" stroke="#ffd65f" stroke-opacity=".4"/>'})
  };
}
Object.assign(CoreV14.sprites,buildV6Sprites());

function v6BoardPoint(gx,gy){
  const b=document.getElementById('board');if(!b)return{x:0,y:0};const r=b.getBoundingClientRect();
  return{x:(gx+.5)*r.width/CoreV14.dimensions.gridSize,y:(gy+.5)*r.height/CoreV14.dimensions.gridSize};
}
function v6FxEl(cls,x,y,color){
  const b=document.getElementById('board');if(!b)return null;const el=document.createElement('div');el.className=cls;el.style.left=x+'px';el.style.top=y+'px';el.style.color=color||'#fff';b.appendChild(el);setTimeout(()=>el.remove(),520);return el;
}
function addImpactAtGrid(gx,gy,color='#fff'){const p=v6BoardPoint(gx,gy);v6FxEl('impact-ring',p.x,p.y,color);v6FxEl('impact-core',p.x,p.y,color);v6FxEl('shockwave',p.x,p.y,color)}
function addMuzzleAtGrid(gx,gy,color='#fff'){const p=v6BoardPoint(gx,gy);v6FxEl('muzzle-flash',p.x,p.y,color)}
function addBeamFx(ax,ay,bx,by,color='#fff'){
  const a=v6BoardPoint(ax,ay),b=v6BoardPoint(bx,by),dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)*180/Math.PI;
  const el=v6FxEl('beam-glow',a.x,a.y,color);if(el){el.style.width=len+'px';el.style.transform=`translate(0,-50%) rotate(${ang}deg)`;el.style.transformOrigin='0 50%'}
}

function renderCombatBackdrop(){
  const c=document.getElementById('board-bg'),b=document.getElementById('board');if(!c||!b)return;
  const r=b.getBoundingClientRect(),dpr=window.devicePixelRatio||1,W=r.width,H=r.height;c.width=Math.max(1,Math.round(W*dpr));c.height=Math.max(1,Math.round(H*dpr));
  const x=c.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);x.clearRect(0,0,W,H);
  const m=CoreV14.state.activeMission||{},contact=CoreV14.state.contacts?.find?.(q=>q.id===m.contact),fac=contact?.faction||m.targetFaction||'neutral',tone=FACTION_TONES[fac]||FACTION_TONES.neutral;
  let g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,'#0d1822');g.addColorStop(.52,'#091018');g.addColorStop(1,'#05080c');x.fillStyle=g;x.fillRect(0,0,W,H);
  const halo=x.createRadialGradient(W*.50,H*.08,8,W*.50,H*.08,W*.72);halo.addColorStop(0,v6rgba(tone.accent,.18));halo.addColorStop(.35,v6rgba(tone.accent,.045));halo.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=halo;x.fillRect(0,0,W,H);
  const tile=W/CoreV14.dimensions.gridSize;
  for(let y=0;y<CoreV14.dimensions.gridSize;y++)for(let z=0;z<CoreV14.dimensions.gridSize;z++){
    const px=z*tile,py=y*tile,rv=v6seed(z,y,(m.id||'v6').length);
    x.fillStyle=rv>.82?'rgba(26,35,45,.43)':'rgba(13,20,28,.38)';x.fillRect(px+2,py+2,tile-4,tile-4);
    x.strokeStyle='rgba(125,210,230,.045)';x.lineWidth=1;x.strokeRect(px+2.5,py+2.5,tile-5,tile-5);
    if(rv>.88){x.fillStyle=v6rgba(tone.accent,.10);x.fillRect(px+tile*.16,py+tile*.72,tile*.68,2)}
    if(rv<.08){x.fillStyle='rgba(255,185,72,.12)';x.fillRect(px+tile*.12,py+tile*.16,tile*.18,tile*.04);x.fillRect(px+tile*.7,py+tile*.16,tile*.18,tile*.04)}
  }
  // Industrial seams, drainage and cable runs.
  x.strokeStyle='rgba(0,0,0,.52)';x.lineWidth=Math.max(2,tile*.07);x.beginPath();x.moveTo(0,H*.48);x.lineTo(W,H*.48);x.stroke();
  x.strokeStyle=v6rgba(tone.accent,.17);x.lineWidth=1;x.beginPath();x.moveTo(0,H*.48-2);x.lineTo(W,H*.48-2);x.stroke();
  x.strokeStyle='rgba(145,175,190,.10)';x.lineWidth=Math.max(1,tile*.035);for(let i=1;i<5;i++){x.beginPath();x.moveTo(W*(i/5),0);x.lineTo(W*(i/5)+tile*.22,H);x.stroke()}
  // Edge conduits and warning rails.
  x.fillStyle='rgba(4,7,10,.85)';x.fillRect(0,0,W,tile*.10);x.fillRect(0,H-tile*.10,W,tile*.10);
  for(let i=0;i<14;i++){x.fillStyle=i%2?v6rgba(tone.warm,.38):'rgba(25,30,34,.75)';x.fillRect(i*W/14,H-tile*.095,W/28,tile*.055)}
  // Objective / hazard ground glows integrated into floor.
  (CoreV14.state.grid||[]).forEach(q=>{if(!q)return;const cx=(q.x+.5)*tile,cy=(q.y+.5)*tile;if(q.hazard){const h=x.createRadialGradient(cx,cy,1,cx,cy,tile*.48);h.addColorStop(0,'rgba(255,40,70,.18)');h.addColorStop(1,'rgba(255,40,70,0)');x.fillStyle=h;x.fillRect(cx-tile*.5,cy-tile*.5,tile,tile)}if(q.cover){x.fillStyle='rgba(0,0,0,.18)';x.fillRect(q.x*tile+tile*.15,q.y*tile+tile*.56,tile*.70,tile*.24)}});
  // Scuffs and grime.
  for(let i=0;i<55;i++){const px=v6seed(i,3,7)*W,py=v6seed(i,9,11)*H,rr=2+v6seed(i,5,13)*9;x.fillStyle=`rgba(0,0,0,${.035+v6seed(i,2,17)*.06})`;x.beginPath();x.ellipse(px,py,rr,rr*.35,v6seed(i,8,19)*3.14,0,Math.PI*2);x.fill()}
}

resizeCombatCanvas=function(){V6VisualOriginal.resizeCombatCanvas();renderCombatBackdrop()};
buildGrid=function(mission){V6VisualOriginal.buildGrid(mission);requestAnimationFrame(renderCombatBackdrop)};
initCombat=function(mission){V6VisualOriginal.initCombat(mission);requestAnimationFrame(renderCombatBackdrop)};
spawnParticles=function(x,y,color,count,spread){V6VisualOriginal.spawnParticles(x,y,color,count,spread);if(count>=16)addImpactAtGrid(x,y,color)};
tracer=function(ax,ay,bx,by,color){V6VisualOriginal.tracer(ax,ay,bx,by,color);addMuzzleAtGrid(ax,ay,color||'#fff');addBeamFx(ax,ay,bx,by,color||'#fff');addImpactAtGrid(bx,by,color||'#fff')};
flashHit=function(u){V6VisualOriginal.flashHit(u);if(u)addImpactAtGrid(u.x,u.y,u.team==='player'?'#00f0ff':'#ff405f')};
syncCombatUnits=function(){
  V6VisualOriginal.syncCombatUnits();
  CoreV14.state.units.forEach(u=>{if(!u.el)return;u.el.dataset.facing=u.facing||'S';u.el.dataset.class=u.className||'';if(!u.el.querySelector('.facing-notch')){const n=document.createElement('i');n.className='facing-notch';u.el.appendChild(n)}});
};
showBanner=function(text,color){V6VisualOriginal.showBanner(text,color);const b=document.getElementById('board');if(!b)return;b.style.boxShadow=`0 22px 62px rgba(0,0,0,.52),0 0 34px ${v6rgba(color||'#00f0ff',.30)},inset 0 0 160px ${v6rgba(color||'#00f0ff',.06)}`;setTimeout(()=>{if(b)b.style.boxShadow=''},850)};

renderOverworldStatic=function(){
  if(!CoreV14.state.ovCanvas||!CoreV14.state.ovMap||!CoreV14.state.ovMap.length)return;
  const r=CoreV14.state.ovCanvas.getBoundingClientRect(),W=r.width,H=r.height,tile=CoreV14.state.ovTile,dpr=window.devicePixelRatio||1;
  if(!CoreV14.state.ovStaticCanvas)CoreV14.state.ovStaticCanvas=document.createElement('canvas');CoreV14.state.ovStaticCanvas.width=Math.max(1,Math.round(W*dpr));CoreV14.state.ovStaticCanvas.height=Math.max(1,Math.round(H*dpr));
  const x=CoreV14.state.ovStaticCanvas.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);x.clearRect(0,0,W,H);const ox=(W-CoreV14.dimensions.overworldWidth*tile)/2,oy=(H-CoreV14.dimensions.overworldHeight*tile)/2;
  let sky=x.createLinearGradient(0,0,0,H*.55);sky.addColorStop(0,'#050b15');sky.addColorStop(.55,'#0a1c2d');sky.addColorStop(1,'#071018');x.fillStyle=sky;x.fillRect(0,0,W,H);
  let haze=x.createRadialGradient(W*.52,H*.17,10,W*.52,H*.17,H*.48);haze.addColorStop(0,'rgba(0,240,255,.17)');haze.addColorStop(.42,'rgba(255,0,170,.06)');haze.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=haze;x.fillRect(0,0,W,H);
  // Layered skyline for depth.
  for(let layer=0;layer<3;layer++)for(let i=0;i<26;i++){
    const bw=18+(i*17+layer*11)%54,bh=35+(i*37+layer*19)%115,bx=(i*47+layer*31)%Math.max(W,1),base=H*(.30+.015*layer),alpha=.45+layer*.16;
    x.fillStyle=`rgba(${7+layer*3},${15+layer*5},${24+layer*7},${alpha})`;x.fillRect(bx,base-bh,bw,bh);
    if(layer===2){for(let wy=0;wy<Math.floor(bh/10);wy++)for(let wx=0;wx<Math.floor(bw/8);wx++){if((i+wx*5+wy*7)%5!==0){const cs=['rgba(255,215,120,.42)','rgba(0,240,255,.29)','rgba(255,0,170,.25)'];x.fillStyle=cs[(i+wx+wy)%3];x.fillRect(bx+wx*8+2,base-bh+wy*10+3,3,3)}}}
  }
  // Elevated transit line.
  x.strokeStyle='rgba(130,200,220,.10)';x.lineWidth=6;x.beginPath();x.moveTo(0,H*.275);x.lineTo(W,H*.245);x.stroke();x.strokeStyle='rgba(0,240,255,.18)';x.lineWidth=1;x.beginPath();x.moveTo(0,H*.27);x.lineTo(W,H*.24);x.stroke();
  for(let y=0;y<CoreV14.dimensions.overworldHeight;y++)for(let z=0;z<CoreV14.dimensions.overworldWidth;z++){
    const px=ox+z*tile,py=oy+y*tile,v=CoreV14.state.ovMap[y][z],d=CoreV14.getDistrict(z,y),tone=FACTION_TONES[d.faction]||FACTION_TONES.neutral,rv=v6seed(z,y,22);
    if(v===0){
      let rg=x.createLinearGradient(px,py,px,py+tile);rg.addColorStop(0,'rgba(19,24,31,.96)');rg.addColorStop(1,'rgba(6,8,12,.98)');x.fillStyle=rg;x.fillRect(px,py,tile,tile);
      x.strokeStyle='rgba(255,255,255,.035)';x.strokeRect(px+.5,py+.5,tile-1,tile-1);x.strokeStyle=v6rgba(tone.accent,.11);x.beginPath();x.moveTo(px+tile*.12,py+tile*.22);x.lineTo(px+tile*.88,py+tile*.22);x.stroke();
      x.strokeStyle='rgba(255,206,104,.18)';x.setLineDash([Math.max(3,tile*.11),Math.max(4,tile*.16)]);x.beginPath();x.moveTo(px+tile*.5,py+tile*.08);x.lineTo(px+tile*.5,py+tile*.92);x.stroke();x.setLineDash([]);
      if(rv>.78){x.fillStyle='rgba(0,240,255,.08)';x.fillRect(px+tile*.08,py+tile*.79,tile*.84,tile*.05)}
    }else if(v===1){
      let bg=x.createLinearGradient(px,py,px,py+tile);bg.addColorStop(0,'rgba(20,29,40,.98)');bg.addColorStop(1,'rgba(7,11,17,.99)');x.fillStyle=bg;x.fillRect(px,py,tile,tile);
      x.fillStyle='rgba(0,0,0,.24)';x.fillRect(px+tile*.07,py+tile*.12,tile*.78,tile*.74);x.fillStyle='rgba(14,20,29,.98)';x.fillRect(px+tile*.10,py+tile*.23,tile*.72,tile*.53);x.fillStyle='rgba(255,255,255,.055)';x.fillRect(px+tile*.10,py+tile*.23,tile*.72,tile*.055);
      for(let wy=0;wy<3;wy++)for(let wx=0;wx<3;wx++){const lit=v6seed(z+wx,y+wy,35)>.33;x.fillStyle=lit?((wx+wy)%3===0?v6rgba(tone.accent,.48):'rgba(255,218,126,.40)'):'rgba(14,22,31,.92)';x.fillRect(px+tile*.18+wx*tile*.18,py+tile*.34+wy*tile*.12,tile*.075,tile*.055)}
      if((z*17+y*31)%6===0){x.fillStyle=v6rgba(tone.accent,.82);x.shadowColor=tone.accent;x.shadowBlur=10;x.fillRect(px+tile*.24,py+tile*.095,tile*.40,tile*.075);x.shadowBlur=0}
      if(rv>.86){x.strokeStyle=v6rgba(tone.accent,.30);x.beginPath();x.moveTo(px+tile*.12,py+tile*.82);x.lineTo(px+tile*.75,py+tile*.27);x.stroke()}
    }else{
      let pg=x.createRadialGradient(px+tile*.5,py+tile*.5,1,px+tile*.5,py+tile*.5,tile*.62);pg.addColorStop(0,v6rgba(tone.accent,.11));pg.addColorStop(1,'rgba(7,14,21,.97)');x.fillStyle=pg;x.fillRect(px,py,tile,tile);x.strokeStyle=v6rgba(tone.accent,.19);x.strokeRect(px+tile*.14,py+tile*.14,tile*.72,tile*.72);x.strokeStyle='rgba(255,255,255,.045)';x.strokeRect(px+tile*.26,py+tile*.26,tile*.48,tile*.48)
    }
  }
  // Wet reflective wash over lower city.
  let wet=x.createLinearGradient(0,H*.55,0,H);wet.addColorStop(0,'rgba(0,0,0,0)');wet.addColorStop(1,'rgba(0,15,25,.17)');x.fillStyle=wet;x.fillRect(0,H*.55,W,H*.45);
  CoreV14.state.ovStaticDirty=false;
};

// Refresh visual layer after resize and expose diagnostics/mod hooks.
window.addEventListener('resize',()=>{if(CoreV14.state.screen==='combat')requestAnimationFrame(renderCombatBackdrop)});
window.ChromeRequiem=window.ChromeRequiem||{};
window.ChromeRequiem.visuals={version:6,renderCombatBackdrop,buildV6Sprites,addImpactAtGrid,tones:FACTION_TONES};

