      const r=board.getBoundingClientRect(),W=r.width||1,H=r.height||1;
      V9Perf.view.combat={left:r.left||0,top:r.top||0,width:W,height:H,cw:W/GRID_SIZE,ch:H/GRID_SIZE,scale:W/560,dpr:window.devicePixelRatio||1};
