// ---------- One BFS field replaces dozens of BFS calls per highlight pass ----------
function v9OccupancySignature(){return (Game.units||[]).filter(u=>u.hp>0&&!u.dead).map(u=>`${u.x},${u.y}`).sort().join('|')}
function computeMovementFieldV9(u){
  const key=`${u.x},${u.y}|${v9OccupancySignature()}`;
  if(V9Perf.movementCache?.key===key){V9Perf.counters.movementHits++;return V9Perf.movementCache}
  V9Perf.counters.movementBuilds++;const dist=new Int16Array(GRID_SIZE*GRID_SIZE);dist.fill(-1);const parent=new Int16Array(GRID_SIZE*GRID_SIZE);parent.fill(-1);const sx=u.x,sy=u.y,si=sy*GRID_SIZE+sx;dist[si]=0;
  const q=new Int16Array(GRID_SIZE*GRID_SIZE);let head=0,tail=0;q[tail++]=si;const dirs=[[1,0],[-1,0],[0,1],[0,-1]];
  while(head<tail){const idx=q[head++],x=idx%GRID_SIZE,y=(idx/GRID_SIZE)|0,nd=dist[idx]+1;for(const[dx,dy]of dirs){const nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=GRID_SIZE||ny>=GRID_SIZE)continue;const ni=ny*GRID_SIZE+nx;if(dist[ni]>=0)continue;const c=Game.grid[ni];if(!c||c.obstacle||c.unit)continue;dist[ni]=nd;parent[ni]=idx;q[tail++]=ni}}
  return V9Perf.movementCache={key,dist,parent,start:si};
}
