  let s=document.getElementById('ov-salvage-v10');if(!s){const box=document.createElement('div');box.className='stat salv';box.innerHTML='⚙ <b id="ov-salvage-v10">0</b>';const cr=bar.querySelector('.credits');cr?.after(box);s=box.querySelector('b')}
  if(s)s.textContent=Game.salvage||0;
