const V10PrevUpdateOverworldHUD=updateOverworldHUD;
updateOverworldHUD=function(){const r=V10PrevUpdateOverworldHUD();ensureV10State();updateV10Topbar();return r};

// ---------- portrait overworld camera without changing canvas resolution ----------
function computeOverworldViewV10(){
  const wrap=document.querySelector('#overworld-screen .wrap'),m=PerformanceV14.metrics()?.overworld;if(!wrap||!m)return{zoom:1,tx:0,ty:0};
  const portrait=innerWidth<=650&&innerHeight>innerWidth*1.2&&!Game.v10Camera.full;const zoom=portrait?1.82:1;
  if(zoom===1)return{zoom:1,tx:0,ty:0};
  const px=m.offX+(Game.ovPlayer.x+.5)*m.tile,py=m.offY+(Game.ovPlayer.y+.5)*m.tile,W=m.width,H=m.height;
  let tx=W*.5-px*zoom,ty=H*.52-py*zoom;
  const left=m.offX*zoom,right=(m.offX+OV_W*m.tile)*zoom,top=m.offY*zoom,bottom=(m.offY+OV_H*m.tile)*zoom;
  const minTx=W-right,maxTx=-left,minTy=H-bottom,maxTy=-top;
  tx=(minTx<=maxTx)?Math.max(minTx,Math.min(maxTx,tx)):(W-(right-left))/2-left;
  ty=(minTy<=maxTy)?Math.max(minTy,Math.min(maxTy,ty)):(H-(bottom-top))/2-top;
  return{zoom,tx,ty};
}
function applyOverworldCameraV10(force=false){
  if(!Game.ovCanvas)return;ensureV10State();const v=computeOverworldViewV10(),c=Game.v10Camera;
  if(!force&&Math.abs(c.zoom-v.zoom)<.001&&Math.abs(c.tx-v.tx)<.5&&Math.abs(c.ty-v.ty)<.5)return;
  Object.assign(c,v);for(const el of [document.getElementById('overworld-static-v9'),Game.ovCanvas])if(el){el.style.transformOrigin='0 0';el.style.transform=`translate3d(${v.tx}px,${v.ty}px,0) scale(${v.zoom})`;el.style.willChange=v.zoom===1?'auto':'transform'};
}
function v10EventToWorldTile(e){
  const wrap=document.querySelector('#overworld-screen .wrap'),m=PerformanceV14.metrics()?.overworld;if(!wrap||!m)return null;const r=wrap.getBoundingClientRect(),c=Game.v10Camera||{zoom:1,tx:0,ty:0};
  const bx=(e.clientX-r.left-c.tx)/c.zoom,by=(e.clientY-r.top-c.ty)/c.zoom;const x=Math.floor((bx-m.offX)/m.tile),y=Math.floor((by-m.offY)/m.tile);return x>=0&&x<OV_W&&y>=0&&y<OV_H?{x,y}:null;
}
onOverworldMove=function(e){Game.hoverTile=v10EventToWorldTile(e)};
onOverworldClick=function(e){
  const t=v10EventToWorldTile(e);if(t)Game.hoverTile=t;if(!Game.hoverTile)return;const{x,y}=Game.hoverTile;
  const contact=Game.contacts.find(c=>c.x===x&&c.y===y);if(contact&&Math.abs(contact.x-Game.ovPlayer.x)<=4&&Math.abs(contact.y-Game.ovPlayer.y)<=4){openContactPanel(contact);return}
  const vendor=Game.vendors.find(v=>v.x===x&&v.y===y);if(vendor&&Math.abs(vendor.x-Game.ovPlayer.x)<=4&&Math.abs(vendor.y-Game.ovPlayer.y)<=4){openVendor(vendor);return}
  if(!isWalkable(x,y)){toast('Blocked.');return}const path=findPath(Game.ovPlayer,{x,y});if(path&&path.length>1){Game.pendingPath=path;if(path.length>5&&seededRandom()<.35)Game.storyFlags._pendingTravelEvent=path.length;toast(`Moving (${path.length-1} tiles)`)}else toast('No route.');
};

// ---------- time-of-day overlay + lightweight traffic donor polish ----------
function v10TimeLighting(ctx,W,H){
  const h=(Game.hour||0)%24;let col='rgba(4,10,25,.04)';if(h<5||h>=21)col='rgba(2,5,24,.25)';else if(h<7)col='rgba(80,25,55,.10)';else if(h>=18)col='rgba(60,20,65,.12)';ctx.save();ctx.fillStyle=col;ctx.fillRect(0,0,W,H);ctx.restore();
}
const V10Traffic={draw(t,ctx,m){ensureV10State();const night=((Game.hour||0)%24<6||(Game.hour||0)%24>=19)?1:.55;ctx.save();for(const v of Game.v10Traffic){if(v.axis===0){v.x=(v.x+v.speed*(t-(v.last||t)))%OV_W}else{v.y=(v.y+v.speed*(t-(v.last||t)))%OV_H}v.last=t;const px=m.offX+(v.x+.5)*m.tile,py=m.offY+(v.y+.5)*m.tile;ctx.fillStyle=v.color;ctx.globalAlpha=.42*night;ctx.shadowColor=v.color;ctx.shadowBlur=5;ctx.beginPath();ctx.arc(px,py,Math.max(1.1,m.tile*.07),0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0;ctx.globalAlpha=1;ctx.restore()}};
const V10PrevOverworldLoop=overworldLoop;
overworldLoop=function(t){V10PrevOverworldLoop(t);if(Game.screen!=='overworld-screen'||!Game.ovCtx)return;const m=PerformanceV14.metrics()?.overworld;if(m){v10TimeLighting(Game.ovCtx,m.width,m.height);V10Traffic.draw(t,Game.ovCtx,m)}applyOverworldCameraV10(false)};

// ---------- mercenary bazaar redesign ----------
const V10PrevOpenVendor=openVendor;
openVendor=function(vendor){
  if(vendor?.type!=='hire'){const g=document.getElementById('vendor-grid');g?.classList.remove('v10-hire-grid');return V10PrevOpenVendor(vendor)}
  MercenaryIntelligenceV14.ensureState();Game.vendorCurrent=vendor;document.getElementById('vendor-title').textContent='MERC BAZAAR // CONTRACTORS';document.getElementById('vendor-cr').innerHTML=`¢ <b style="color:#ffaa00">${Game.credits.toLocaleString()}</b>`;
  const grid=document.getElementById('vendor-grid');grid.className='vendor-grid v10-hire-grid';grid.innerHTML='';
  MercenaryIntelligenceV14.recruitmentPool.forEach(h=>{const hired=Game.hired.includes(h.id),full=Game.roster.length>=Game.crewMax,def=CLASS_DEFS[h.className],skill=findSkillByAnyId(h.className,h.startSkill)?.name||h.startSkill,el=document.createElement('div');el.className='v10-hire-card'+(hired?' hired':'');el.innerHTML=`<div class="crew-portrait">${window.CRAssets?.classPortrait?.(h.className,h.name)||SPRITES[h.className]}</div><div class="v10-hire-main"><div class="v10-hire-name">${h.name}</div><div class="v10-hire-class">${h.className.toUpperCase()} · CONTRACTOR</div><div class="v10-hire-desc">${h.desc}</div><div class="v10-hire-stats">HP ${def.hp} · DMG ${def.dmg} · MOVE ${def.move}<br><span class="v10-hire-skill">START: ${skill}</span></div></div><div class="v10-hire-buy"><div class="v10-hire-price">¢ ${h.cost}</div><button class="btn small" ${hired||full?'disabled':''}>${hired?'HIRED':full?'FULL':'HIRE'}</button></div>`;const b=el.querySelector('button');if(b&&!hired&&!full)b.onclick=()=>{if(MercenaryIntelligenceV14.hire(h.id))openVendor(vendor)};grid.appendChild(el)});showScreen('vendor');
};

// ---------- initiative portraits ----------
function renderInitiativeV10(){
  const strip=document.getElementById('init-strip');if(!strip)return;strip.innerHTML='';(Game.turnQueue||[]).forEach((u,i)=>{if(u.hp<=0||u.dead)return;const el=document.createElement('div');el.className='init-token v10-init '+u.team+(i===Game.turnIndex?' active':'')+(i<Game.turnIndex?' done':'');el.title=`${u.name} · ${u.className}`;el.innerHTML=`<div class="v10-init-face">${SPRITES[u.className]||SPRITES.Guard||''}</div><div class="v10-init-label">${u.name.slice(0,4).toUpperCase()}</div>`;strip.appendChild(el)})
}
renderInitiative=renderInitiativeV10;

// ---------- mission briefing / debrief ----------
function salvageEstimateV10(m){return Math.max(1,(m?.diff||1)*2+1)}
function showMissionBriefingV10(m){
  ensureV10UI();Game.pendingMission=m;const body=document.getElementById('v10-brief-body');const enemies=(m.enemies||[]).map(en=>{const d=ENEMY_DEFS[en]||{};return`<div class="v10-enemy-brief">${SPRITES[en]||SPRITES.Guard}<div><div class="v10-enemy-name">${en}</div><div class="v10-enemy-stats">HP ${d.hp||'?'} · DMG ${d.dmg||'?'} · ARM ${d.armor||0}</div></div></div>`}).join('');const crew=Game.roster.map(u=>`<div class="v10-crew-brief"><span>${u.name} · ${u.className}</span><span class="${u.hp<u.maxHp*.6?'v10-wounded':''}">${u.hp}/${u.maxHp}${u.injuries?.length?' · '+u.injuries.length+' INJ':''}</span></div>`).join('');
  body.innerHTML=`<div class="v10-brief-kicker">MISSION BRIEFING // ${FACTIONS[m.targetFaction]?.name||'INDEPENDENT'}</div><div class="v10-brief-title">${m.name}</div><div class="v10-brief-desc">${m.desc||''}</div><div class="v10-brief-grid"><div class="v10-panel"><div class="v10-panel-title">HOSTILE FORCES</div><div class="v10-enemies">${enemies||'<span style="color:#7894a4">Unknown force composition.</span>'}</div></div><div class="v10-panel"><div class="v10-panel-title">CONTRACT / CREW</div><div class="v10-brief-reward"><span>Reward</span><b>¢${m.reward||0}</b><span>XP</span><b>${m.xp||0}</b><span>Salvage estimate</span><b>⚙ ${salvageEstimateV10(m)}</b><span>Objective</span><b>${String(m.objective||m.type||'eliminate').toUpperCase()}</b></div><div style="margin-top:8px">${crew}</div></div></div><div class="v10-brief-actions"><button class="btn" id="v10-brief-cancel">ABORT</button><button class="btn primary" id="v10-brief-deploy">▶ DEPLOY</button></div>`;
  body.querySelector('#v10-brief-cancel').onclick=()=>{Game.pendingMission=null;showScreen('overworld-screen');initOverworld()};body.querySelector('#v10-brief-deploy').onclick=()=>{const mm=Game.pendingMission;Game.pendingMission=null;V10PrevStartMission(mm)};showScreen('v10-briefing');
}
const V10PrevStartMission=startMission;
startMission=function(m){return showMissionBriefingV10(m)};

let V10DeferredStory=null;
const V10PrevPlayStory=playStory;
playStory=function(key){if(Game.screen==='v10-debrief'){V10DeferredStory=key;return}return V10PrevPlayStory(key)};
function showDebriefV10(success,m,salvageGain){
  const body=document.getElementById('v10-debrief-body');const crew=Game.roster.map(u=>`<div class="v10-debrief-unit"><b>${u.name}</b><br>${u.className} · HP ${u.hp}/${u.maxHp}${u.injuries?.length?`<br><span class="v10-wounded">${u.injuries.map(i=>INJURY_DEFS[i]?.name||i).join(', ')}</span>`:''}</div>`).join('');body.innerHTML=`<div class="v10-brief-kicker">AFTER ACTION REPORT</div><div class="v10-brief-title" style="color:${success?'#73ffc0':'#ff778c'}">${success?'MISSION COMPLETE':'MISSION FAILED'}</div><div class="v10-brief-desc">${m?.name||'Contract'} · Day ${Game.day} · ${String(Game.hour).padStart(2,'0')}:00</div><div class="v10-brief-grid"><div class="v10-panel"><div class="v10-panel-title">CREW STATUS</div><div class="v10-debrief-crew">${crew}</div></div><div class="v10-panel"><div class="v10-panel-title">OUTCOME</div><div class="v10-brief-reward"><span>Credits</span><b>${success?'+'+(m?.reward||0):'Extraction loss'}</b><span>Salvage</span><b>⚙ ${salvageGain}</b><span>Stealth</span><b>${Game.objective?.quiet===false?'COMPROMISED':'CLEAN / N/A'}</b></div></div></div><div class="v10-brief-actions"><button class="btn primary" id="v10-debrief-continue">CONTINUE</button></div>`;body.querySelector('#v10-debrief-continue').onclick=()=>{if(V10DeferredStory){const k=V10DeferredStory;V10DeferredStory=null;V10PrevPlayStory(k)}else{showScreen('overworld-screen');initOverworld();toast(success?'Contract complete. Injuries persist.':'Mission failed. Emergency extraction completed.')}};showScreen('v10-debrief');
}
const V10PrevReturnToOverworld=returnToOverworld;
returnToOverworld=function(success){
  if(Game.screen==='story')return V10PrevReturnToOverworld(success);const m=Game.activeMission;if(!m)return V10PrevReturnToOverworld(success);let gain=0;if(success&&!m._v10SalvageAwarded){gain=salvageEstimateV10(m)+(Game.objective?.quiet!==false?1:0);Game.salvage=(Game.salvage||0)+gain;m._v10SalvageAwarded=true}Game.roster.forEach(u=>{if(u.hp<=0)u.hp=1;u.ap=u.maxAp});Game.activeMission=null;Game.alerted=false;updateV10Topbar();saveGame(0,true);showDebriefV10(success,m,gain);Game.objective=null;
};

// ---------- safehouse salvage / crafting ----------
function craftItemV10(id){
  ensureV10State();const r=V10_RECIPES.find(x=>x.id===id),item=ITEMS[id];if(!r||!item)return false;const ws=Game.safehouse?.workshop||1;if(ws<r.workshop){toast(`Workshop LV ${r.workshop} required.`);return false}if(Game.salvage<r.salvage||Game.credits<r.credits){toast('Not enough salvage or credits.');return false}Game.salvage-=r.salvage;Game.credits-=r.credits;const u=Game.roster[Game.selectedCrewIndex]||Game.roster[0];if(item.type==='consumable')u.inventory[id]=(u.inventory[id]||0)+1;else if(item.type==='weapon'){if(!Game.stash.weapons.includes(id))Game.stash.weapons.push(id)}else if(item.type==='armor'){if(!Game.stash.armor.includes(id))Game.stash.armor.push(id)}toast(`Crafted ${item.name}.`);saveGame(0,true);updateV10Topbar();openSafehouse();return true;
}
const V10PrevOpenSafehouse=openSafehouse;
openSafehouse=function(){V10PrevOpenSafehouse();ensureV10State();const inner=document.getElementById('modal-inner'),close=inner?.querySelector('#safe-close');if(!inner||inner.querySelector('.v10-salvage-strip'))return;const block=document.createElement('div');block.innerHTML=`<div class="v10-salvage-strip"><span>WORKSHOP FABRICATION</span><span>⚙ ${Game.salvage} SALVAGE</span></div><div class="v10-craft-grid">${V10_RECIPES.map(r=>{const locked=(Game.safehouse?.workshop||1)<r.workshop,ok=!locked&&Game.salvage>=r.salvage&&Game.credits>=r.credits;return`<div class="v10-craft${locked?' locked':''}"><div class="v10-craft-name">${ITEMS[r.id]?.name||r.name}</div><div class="v10-craft-cost">⚙ ${r.salvage} · ¢${r.credits} · WORKSHOP ${r.workshop}</div><button class="btn small" data-v10-craft="${r.id}" ${ok?'':'disabled'}>${locked?'LOCKED':'CRAFT'}</button></div>`}).join('')}</div>`;block.querySelectorAll('[data-v10-craft]').forEach(b=>b.onclick=()=>craftItemV10(b.dataset.v10Craft));inner.insertBefore(block,close||null)};

// ---------- hackable combat terminals ----------
const V10_HACK_OUTCOMES=[
  {id:'cache',label:'DATA CACHE',run(u){const g=90+Math.floor(seededRandom()*180);Game.credits+=g;Game.salvage++;floatText(u.x,u.y,`+¢${g} / ⚙1`,'#ffaa00');logMsg(`Terminal yields ¢${g} and salvage.`,'good')}},
  {id:'purge',label:'SECURITY PURGE',run(){Game.units.filter(e=>e.team==='enemy'&&e.hp>0).forEach(e=>{e.disabledTurns=Math.max(e.disabledTurns||0,1);floatText(e.x,e.y,'STUN','#b060ff')});logMsg('Security purge stuns hostiles.','good')}},
  {id:'turret',label:'DEFENCE TURRET',run(u){const es=Game.units.filter(e=>e.team==='enemy'&&e.hp>0);if(!es.length)return;const t=es[Math.floor(seededRandom()*es.length)],d=18+Math.floor(seededRandom()*14);tracer(u.x,u.y,t.x,t.y,'#ffe060');t.hp-=d;floatText(t.x,t.y,'-'+d,'#ffe060');spawnParticles(t.x,t.y,'#ffe060',18,3);if(t.hp<=0)onUnitDeath(t)}},
  {id:'uplink',label:'TACTICAL UPLINK',run(){Game.units.filter(e=>e.team==='enemy'&&e.hp>0).forEach(e=>e.statuses.marked=Math.max(e.statuses.marked||0,2));logMsg('Uplink marks all hostiles.','good')}}
];
function placeHackablesV10(m){
  const free=Game.grid.filter(c=>!c.obstacle&&!c.unit&&!c.cover&&!c.hazard&&!c.el?.classList.contains('objective-cell')&&c.y<7&&c.x>1);free.sort((a,b)=>hashString(`${m.id||m.name}:${a.x},${a.y}`)-hashString(`${m.id||m.name}:${b.x},${b.y}`));const n=(m.type==='heist'?2:1)+((m.diff||1)>=3?1:0);free.slice(0,Math.min(n,3)).forEach(c=>{c.hackable=true;c.hacked=false;c.el.classList.add('hackable-v10')});
}
const V10PrevBuildGrid=buildGrid;
buildGrid=function(m){const r=V10PrevBuildGrid(m);placeHackablesV10(m);return r};
function refreshHackableHighlightsV10(){const u=Game.selectedUnit;Game.grid?.forEach(c=>c.el?.classList.remove('ready-v10'));if(!u||u.team!=='player'||Game.turn!=='player')return;Game.grid.filter(c=>c.hackable&&!c.hacked).forEach(c=>{const d=Math.abs(u.x-c.x)+Math.abs(u.y-c.y);if(d<=Math.max(2,u.range))c.el.classList.add('ready-v10')})}
const V10PrevRefreshHighlights=refreshCombatHighlights;
refreshCombatHighlights=function(){const r=V10PrevRefreshHighlights();refreshHackableHighlightsV10();return r};
const V10PrevCellClick=onCombatCellClick;
onCombatCellClick=function(x,y){const c=cellAt(x,y),u=Game.selectedUnit;if(c?.hackable&&!c.hacked&&u?.team==='player'&&Game.turn==='player'&&!Game.pendingAbility&&!Game.pendingItem&&!Game.inspectMode&&!Game.moving){const d=Math.abs(u.x-x)+Math.abs(u.y-y);if(d>Math.max(2,u.range)){logMsg('Terminal out of range.','sys');return}if(u.ap<1){logMsg('Need 1 AP to hack.','sys');return}u.ap--;c.hacked=true;c.el.classList.add('hacked-v10');c.el.classList.remove('ready-v10');const out=V10_HACK_OUTCOMES[Math.floor(seededRandom()*V10_HACK_OUTCOMES.length)];spawnParticles(x,y,'#b060ff',18,3);floatText(x,y-.55,out.label,'#d8b8ff');out.run(u);updateCombat();checkWinLose();return}return V10PrevCellClick(x,y)};

