const V10PrevSerialize=serializeGame;
serializeGame=function(){ensureV10State();const d=JSON.parse(V10PrevSerialize());d.version=V10_VERSION;d.salvage=Game.salvage;return JSON.stringify(d)};
let v10AutosavePending=false,v10AutosaveHandle=0;
function flushAutosaveV10(){if(!v10AutosavePending)return false;v10AutosavePending=false;v10AutosaveHandle=0;try{localStorage.setItem(V10_SAVE_KEY+'0',serializeGame());return true}catch(e){toast('Save failed: '+e.message);return false}}
function saveV10Immediate(slot,quiet=false){try{localStorage.setItem(V10_SAVE_KEY+slot,serializeGame());if(!quiet)toast(slot===0?'Autosaved':'Game saved.');return true}catch(e){toast('Save failed: '+e.message);return false}}
saveGame=function(slot,quiet=false){if(slot===0&&quiet){v10AutosavePending=true;if(!v10AutosaveHandle){const cb=()=>flushAutosaveV10();v10AutosaveHandle=typeof requestIdleCallback==='function'?requestIdleCallback(cb,{timeout:700}):setTimeout(cb,0)}return true}return saveV10Immediate(slot,quiet)};
window.addEventListener('pagehide',flushAutosaveV10);
