/* ===================== OBJECTIVES ===================== */
const V12PrevObjectiveCellsFor=objectiveCellsFor;
objectiveCellsFor=function(type){
 if(type==='raid')return[{x:2,y:3,kind:'cache'},{x:7,y:6,kind:'cache'}];
 if(type==='breach')return[{x:3,y:5,kind:'security'},{x:7,y:3,kind:'security'}];
 if(type==='rescue')return[{x:7,y:3,kind:'captive'},{x:1,y:8,kind:'extract'}];
 if(type==='steal')return[{x:7,y:3,kind:'vault'},{x:1,y:8,kind:'extract'}];
 if(type==='secure')return[{x:4,y:4,kind:'security'},{x:6,y:6,kind:'security'}];
 return V12PrevObjectiveCellsFor(type);
};
const V12_NEW_OBJECTIVES=new Set(['raid','breach','rescue','steal','secure']);
const V12PrevSetupObjective=setupObjective;
setupObjective=function(m){
 const type=m.objective||m.type||'eliminate';if(!V12_NEW_OBJECTIVES.has(type))return V12PrevSetupObjective(m);
 const cells=objectiveCellsFor(type);Game.objective={type,cells,progress:0,required:type==='rescue'||type==='steal'?2:cells.length,completed:false,quiet:true,preAlarmClean:true,targetId:null,stage:0};
 cells.forEach((o,i)=>{const c=clearCellV12(o.x,o.y);if(c){c.objectiveIndex=i;c.el.classList.add('objective-cell','v12-objective');c.el.dataset.kind=o.kind}});
 ensureObjectiveHud();updateObjectiveHud();
};
const V12PrevObjectiveText=objectiveText;
objectiveText=function(){
 const o=Game.objective;if(!o)return V12PrevObjectiveText();
 const p=Game.currentTacticalProfileV12;
 if(o.type==='raid')return`RAID · Loot caches ${o.progress}/${o.required}`;
 if(o.type==='breach')return`SECURITY BREACH · Nodes ${o.progress}/${o.required}`;
 if(o.type==='rescue')return o.progress<1?'RESCUE · Free the captive':'RESCUE · Reach extraction with the VIP';
 if(o.type==='steal')return o.progress<1?'BLACK BAG · Crack the vault':'BLACK BAG · Exfiltrate the package';
 if(o.type==='secure')return`SEIZE CONTROL · Points ${o.progress}/${o.required}`;
 return V12PrevObjectiveText();
};
const V12PrevObjectiveAction=objectiveActionAvailable;
objectiveActionAvailable=function(u){
 const o=Game.objective;if(!o)return null;if(o.completed)return V12PrevObjectiveAction(u);
 if(o.type==='raid'){const idx=o.cells.findIndex((c,i)=>!c.done&&nearObjective(u,c,1));if(idx>=0)return{label:'LOOT CACHE',run:()=>progressObjective(u,idx)}}
 if(o.type==='breach'){const idx=o.cells.findIndex((c,i)=>!c.done&&nearObjective(u,c,Math.max(1,u.className==='Hacker'?2:1)));if(idx>=0)return{label:'BREACH SECURITY',run:()=>progressObjective(u,idx)}}
 if(o.type==='secure'){const idx=o.cells.findIndex((c,i)=>!c.done&&nearObjective(u,c));if(idx>=0)return{label:'SEIZE POINT',run:()=>progressObjective(u,idx)}}
 if((o.type==='rescue'||o.type==='steal')&&o.progress===0&&nearObjective(u,o.cells[0],1))return{label:o.type==='rescue'?'FREE VIP':'CRACK VAULT',run:()=>progressObjective(u,0)}
 if((o.type==='rescue'||o.type==='steal')&&o.progress===1&&nearObjective(u,o.cells[1]))return{label:o.type==='rescue'?'EXTRACT VIP':'EXFIL PACKAGE',run:()=>progressObjective(u,1)}
 return V12PrevObjectiveAction(u);
};
const V12PrevProgressObjective=progressObjective;
progressObjective=function(u,idx=0){
 const o=Game.objective;if(!o||!V12_NEW_OBJECTIVES.has(o.type))return V12PrevProgressObjective(u,idx);if(u.ap<1){logMsg('Need 1 AP.','sys');return}u.ap--;sfx('emp');
 const c=o.cells[idx];if(!c)return;
 if(o.type==='raid'){if(!c.done){c.done=true;o.progress++;Game.salvage=(Game.salvage||0)+1;markObjectiveCellDone(idx);floatText(c.x,c.y,'CACHE LOOTED','#ffaa00')}}
 else if(o.type==='breach'){if(!c.done){c.done=true;o.progress++;markObjectiveCellDone(idx);floatText(c.x,c.y,'SECURITY DOWN','#b060ff');if(o.progress===1&&!Game.alerted&&u.className!=='Hacker')setAlerted('security breach detected')}}
 else if(o.type==='secure'){if(!c.done){c.done=true;o.progress++;markObjectiveCellDone(idx);floatText(c.x,c.y,'CONTROLLED','#00f0ff')}}
 else if(o.type==='rescue'||o.type==='steal'){if(idx!==o.progress)return;c.done=true;o.progress++;markObjectiveCellDone(idx);floatText(c.x,c.y,o.type==='rescue'?(idx===0?'VIP FREED':'VIP EXTRACTED'):(idx===0?'PACKAGE ACQUIRED':'PACKAGE EXFILTRATED'),'#00ff88')}
 if(o.progress>=o.required)o.completed=true;updateObjectiveHud();updateCombat();checkWinLose();
};

