 const enemies=Game.units.filter(u=>u.team==='enemy');
 enemies.forEach((e,i)=>{e.v12Faction=fac;e.v12OriginalName=e.name;const label=ft.names[e.className]||e.className;e.name=`${label} ${i+1}`;const wk=ft.weapons[e.className];if(wk&&ITEMS[wk]){e.weapon=wk;e.range=Math.max(e.range,Math.min(ITEMS[wk].range||e.range,e.range+2));e.v12Manufacturer=ITEMS[wk].manufacturer}});
 if((m.objective||m.type)==='bounty'&&enemies.length&&!enemies.some(e=>e.isObjectiveTarget)){const target=enemies[enemies.length-1];target.isObjectiveTarget=true;target.name='TARGET // '+target.name;if(Game.objective)Game.objective.targetId=target.name}
