const V12PrevHasLOS=hasLOS;
hasLOS=function(from,to){
 const rev=Game.v12TopologyRevision||0,key=`v12:${rev}:${from.x},${from.y}>${to.x},${to.y}`;if(Game.losCache?.has(key))return Game.losCache.get(key);
 const line=bresenhamLine(from.x,from.y,to.x,to.y);let ok=true;for(let i=1;i<line.length-1;i++){const c=cellAt(line[i].x,line[i].y);if(c?.obstacle&&!c.transparentObstacle){ok=false;break}}
 Game.losCache?.set(key,ok);return ok;
};
function invalidateTopologyV12(){Game.v12TopologyRevision=(Game.v12TopologyRevision||0)+1;Game.losCache=new Map();{const perf=PerformanceV14.perf;if(perf){perf.movementCache=null;perf.visionCache=new WeakMap()}}updateCombat()}
function interactDoorV12(c,u=Game.selectedUnit){
 if(!c?.door||c.doorOpen||!u||u.team!=='player'||Game.turn!=='player')return false;const d=Math.abs(u.x-c.x)+Math.abs(u.y-c.y);if(d!==1){logMsg('Move adjacent to the door.','sys');return true}
 let cost=1;if(c.doorLocked&&!['Hacker','AgentEX'].includes(u.className))cost=2;if(u.ap<cost){logMsg(`Need ${cost} AP to ${c.doorLocked?'breach':'open'} door.`,'sys');return true}
 u.ap-=cost;c.doorOpen=true;c.obstacle=false;c.doorLocked=false;c.el.classList.add('open');c.el.classList.remove('locked','obstacle');Game.v12Stats.doorsOpened++;if(cost===1&&['Hacker','AgentEX'].includes(u.className))Game.v12Stats.lockedDoorsHacked++;floatText(c.x,c.y,cost===1?'ACCESS':'FORCED','#ffe060');spawnParticles(c.x,c.y,'#ffe060',10,2);invalidateTopologyV12();return true;
}
