 if(pool?.length&&seededRandom()<.36){const ev=pick(pool),panel=document.getElementById('travel-event');document.getElementById('te-title').textContent=`${s.name} // ${ev.title}`;document.getElementById('te-text').textContent=ev.text;const ch=document.getElementById('te-choices');ch.innerHTML='';ev.choices.forEach(([label,fn])=>{const b=document.createElement('button');b.className='btn';b.textContent=label;b.onclick=()=>{fn();panel.classList.remove('open');updateOverworldHUD();saveGame(0,true)};ch.appendChild(b)});panel.classList.add('open');return}
