/* ===================== SAVE / LOAD ===================== */
const V12PrevSerialize=serializeGame;
const V12PrevLoadGame=loadGame;
const V12PrevRenderLoadMenu=renderLoadMenu;
const V12_FALLBACK_PREFIXES=[
 'chrome_requiem_v12_','chrome_requiem_v11_','chrome_requiem_v10_',
 'chrome_requiem_v9_','chrome_requiem_v8_','chrome_requiem_v7_',
 'chrome_requiem_v5_','chrome_requiem_save_'
];
serializeGame=function(){
 ensureV12State();
 const d=JSON.parse(V12PrevSerialize());
 d.version=V12_VERSION;
 d.notoriety=Game.notoriety;
 d.peakNotoriety=Game.peakNotoriety;
 d.rivalEconomy=Game.rivalEconomy;
 d.v12Stats=Game.v12Stats;
 return JSON.stringify(d)
};
let v12AutosavePending=false,v12AutosaveHandle=0;
function flushAutosaveV12(){
 if(!v12AutosavePending)return false;
 v12AutosavePending=false;v12AutosaveHandle=0;
 try{localStorage.setItem(V12_SAVE_KEY+'0',serializeGame());return true}
 catch(e){toast('Save failed: '+e.message);return false}
}
function saveV12Immediate(slot,quiet=false){
 try{
  localStorage.setItem(V12_SAVE_KEY+slot,serializeGame());
  if(!quiet)toast(slot===0?'Autosaved':'Game saved.');
  return true
 }catch(e){toast('Save failed: '+e.message);return false}
}
saveGame=function(slot,quiet=false){
 if(slot===0&&quiet){
  v12AutosavePending=true;
  if(!v12AutosaveHandle){
   const cb=()=>flushAutosaveV12();
   v12AutosaveHandle=typeof requestIdleCallback==='function'?requestIdleCallback(cb,{timeout:700}):setTimeout(cb,0)
  }
  return true
 }
 return saveV12Immediate(slot,quiet)
};
window.addEventListener('pagehide',flushAutosaveV12);

function restoreV12Extras(data){
 Game.notoriety=Number.isFinite(data?.notoriety)?data.notoriety:0;
 Game.peakNotoriety=Number.isFinite(data?.peakNotoriety)?data.peakNotoriety:Game.notoriety;
 Game.rivalEconomy=data?.rivalEconomy||null;
 Game.v12Stats=data?.v12Stats||null;
 ensureV12State();
 ensureV12UI();
 updateV12NotorietyUI();
 return true
}
window.restoreV12Extras=restoreV12Extras;

/* The v11 loader lives inside its own closure.  Bridge v12 saves through the
   already-tested public v11 loadGame rather than reaching into private scope. */
function loadV12Slot(slot){
 try{
  const raw12=localStorage.getItem(V12_SAVE_KEY+slot);
  if(!raw12){
   const ok=V12PrevLoadGame(slot);
   if(ok){
    restoreV12Extras(null);
    toast('Previous save migrated to v12.');
   }
   return !!ok
  }

  const data=JSON.parse(raw12);
  const bridgeKey='chrome_requiem_v11_'+slot;
  const previousBridge=localStorage.getItem(bridgeKey);
  localStorage.setItem(bridgeKey,raw12);
  let ok=false;
  try{ok=!!V12PrevLoadGame(slot)}
  finally{
   if(previousBridge===null)localStorage.removeItem(bridgeKey);
   else localStorage.setItem(bridgeKey,previousBridge)
  }
  if(ok){
   restoreV12Extras(data);
   toast(`Loaded v${data.version||12} save.`);
  }
  return ok
 }catch(e){
  toast('Load failed: '+e.message);
  return false
 }
}
window.loadV12Slot=loadV12Slot;
loadGame=function(slot){return loadV12Slot(slot)};

renderLoadMenu=function(){
 const el=document.getElementById('load-slots');if(!el)return;
 el.innerHTML='';
 [0,1,2].forEach(slot=>{
  let raw=null,prefix=null;
  for(const p of V12_FALLBACK_PREFIXES){
   raw=localStorage.getItem(p+slot);
   if(raw){prefix=p;break}
  }
  const card=document.createElement('button');
  card.className='btn';
  card.style.cssText='width:100%;margin-bottom:6px;text-align:left;padding:10px 14px;';
  const label=slot===0?'AUTOSAVE':`SLOT ${slot}`;
  if(raw){
   try{
    const d=JSON.parse(raw),date=new Date(d.savedAt||Date.now());
    const version=d.version||4;
    card.innerHTML=`<b>${label}</b> — ${d.playerName||'Unknown'} (${d.playerClass||'?'}) · Day ${d.day||1} · ¢${d.credits||0} · ⚙${d.salvage||0}<br><span style="opacity:.6;font-size:9px;">v${version}${prefix===V12_SAVE_KEY?' · GROUND WAR':''} · ${date.toLocaleString()}</span>`;
    card.onclick=()=>loadGame(slot)
   }catch(e){
    card.innerHTML=`<b>${label}</b> — corrupt`;
    card.disabled=true
   }
  }else{
   card.innerHTML=`<b>${label}</b> — empty`;
   card.disabled=true
  }
  el.appendChild(card)
 })
};

const V12PrevStartNew=startNewGame;
startNewGame=function(name,className,background){
 Game.notoriety=0;Game.peakNotoriety=0;Game.rivalEconomy=null;Game.v12Stats=null;
 const r=V12PrevStartNew(name,className,background);
 ensureV12State();generateMissions();saveGame(0,true);
 return r
};

