function ensureContactsV13(){
 if(!Array.isArray(Game.contacts))Game.contacts=[];
 for(const d of V13_CONTACTS){
   let c=Game.contacts.find(x=>x.id===d.id);
   if(!c){c={id:d.id,name:d.name,role:d.role,x:-99,y:-99,color:factionColorV13(d.faction),faction:d.faction,missions:[]};Game.contacts.push(c)}
   Object.assign(c,{name:d.name,role:d.role,color:factionColorV13(d.faction),faction:d.faction,sectorId:d.sectorId,v13:true});
   if(!Array.isArray(c.missions))c.missions=[];
 }
}
function ensureShopsV13(){Game.cityLife=Game.cityLife||{};Game.cityLife.shops=V13_SHOPS.map(s=>s.id)}
function ensureUnitCyberV13(u){
 u.cyber=u.cyber||[];u.cyberSlots=u.cyberSlots||{};
 for(const id of u.cyber){const slot=V13_CYBERWARE[id]?.slot||V13_LEGACY_SLOTS[id];if(slot&&!u.cyberSlots[slot])u.cyberSlots[slot]=id}
 for(const [slot,id] of Object.entries(u.cyberSlots)){if(id&&!u.cyber.includes(id))u.cyber.push(id)}
 u.maxNeuralLoad=100+(u.level||1)*2;
 u.neuralLoad=Object.values(u.cyberSlots).reduce((n,id)=>n+(V13_CYBERWARE[id]?.load||([ 'cyber_neural','cyber_optics','cyber_reflex','cyber_weave'].includes(id)?8:0)),0);
}
function ensureContactRelationsV13(){
 Game.contactRelations=Game.contactRelations||{};
 for(const d of V13_CONTACTS){
   const r=Game.contactRelations[d.id]||(Game.contactRelations[d.id]={trust:d.trust,influence:d.influence,fear:d.fear,reliability:d.reliability,known:!['c22','c24','c28'].includes(d.id),introducedBy:null});
   r.trust=Number.isFinite(r.trust)?r.trust:d.trust;r.influence=Number.isFinite(r.influence)?r.influence:d.influence;r.fear=Number.isFinite(r.fear)?r.fear:d.fear;r.reliability=Number.isFinite(r.reliability)?r.reliability:d.reliability;
 }
}
function ensureCityDiscoveryV13(){
 Game.cityLife=Game.cityLife||{};Game.cityLife.discovered=Game.cityLife.discovered||{};
 Game.cityLife.currentDistrict=Game.cityLife.currentDistrict||getSectorV11(Game.ovPlayer?.x||0,Game.ovPlayer?.y||0).id;
 for(const arr of Object.values(V13_DISTRICT_LOCATIONS))for(const l of arr){
   if(!l.hidden)Game.cityLife.discovered[l.id]=true;
   if(l.contact&&Game.contactRelations?.[l.contact]?.known)Game.cityLife.discovered[l.id]=true;
 }
 Game.cityLife.chains=Game.cityLife.chains||{};
 for(const id of Object.keys(V13_CONTRACT_CHAINS))if(!Game.cityLife.chains[id])Game.cityLife.chains[id]={stage:0,complete:false};
}
function ensureV13State(){
 ensureV12State();ensureContactsV13();ensureShopsV13();ensureContactRelationsV13();Game.roster?.forEach(ensureUnitCyberV13);
 Game.rumors=Array.isArray(Game.rumors)?Game.rumors:[];Game.rareStock=Game.rareStock||{};Game.rareStockDay=Game.rareStockDay||0;
 ensureCityDiscoveryV13();if(!Game.cityLife.lastRumorDay)Game.cityLife.lastRumorDay=0;
}
