function changeContactTrustV13(id,n,reason=''){
 ensureV13State();const r=Game.contactRelations[id];if(!r)return 0;const before=r.trust;r.trust=clampV13(r.trust+n,-100,100);unlockIntroductionsV13(id);if(Math.floor(before/20)!==Math.floor(r.trust/20))toast(`${contactDefV13(id)?.name||id}: TRUST ${r.trust>=0?'+':''}${r.trust}`);if(reason)addJournal('main',`Contact: ${contactDefV13(id)?.name||id}`,reason);return r.trust-before;
}
// Export the canonical trust updater for later operation/contact plugins.
window.changeContactTrustV13=changeContactTrustV13;
function unlockIntroductionsV13(id){
 const d=contactDefV13(id),r=Game.contactRelations?.[id];if(!d||!r)return[];
 const threshold=25,unlocked=[];if(r.trust<threshold)return unlocked;
 for(const target of d.intro||[]){const tr=Game.contactRelations[target];if(tr&&!tr.known){tr.known=true;tr.introducedBy=id;const loc=locationByIdV13('loc_contact_'+target);if(loc)Game.cityLife.discovered[loc.id]=true;unlocked.push(target);addJournal('main','New Contact',`${d.name} introduced you to ${contactDefV13(target)?.name||target}.`)}}
 return unlocked;
}
window.unlockIntroductionsV13=unlockIntroductionsV13;

