 const shops=V13_SHOPS.filter(s=>s.type==='market'&&s.tier>=2),pool=[...V13_RARE_POOL];
 for(let i=0;i<Math.min(6,shops.length,pool.length);i++){const s=shops[Math.floor(seededRandom()*shops.length)],item=pool.splice(Math.floor(seededRandom()*pool.length),1)[0];Game.rareStock[s.id]={item,expires:Game.day+1}}
