 const targetPool={meridian:['Guard','Enforcer','Drone'],wraiths:['Drone','Enforcer','Guard'],iron:['Guard','Heavy','Brute'],chrome:['Enforcer','Brute','Heavy'],spine:['Guard','Drone','Enforcer']};
