function locationAccessV13(l){
 if(Game.cityLife.discovered[l.id])return true;if(l.contact&&Game.contactRelations?.[l.contact]?.known)return true;return false
}
function districtCenterV13(sid){
 const s=sectorDefV13(sid);if(!s)return null;const cx=Math.round((s.x0+s.x1)/2),cy=Math.round((s.y0+s.y1)/2);
 let best=null;for(let y=s.y0;y<=s.y1;y++)for(let x=s.x0;x<=s.x1;x++){if(typeof isWalkable==='function'&&!isWalkable(x,y))continue;const d=Math.abs(x-cx)+Math.abs(y-cy);if(!best||d<best.d)best={x,y,d}}return best||{x:cx,y:cy}
}
function travelToDistrictV13(sid){
 ensureV13State();const prev=getSectorV11(Game.ovPlayer.x,Game.ovPlayer.y).id;if(prev!==sid){const p=districtCenterV13(sid);if(p){const a=sectorDefV13(prev),b=sectorDefV13(sid),dist=Math.abs((a?.x0||0)-(b?.x0||0))+Math.abs((a?.y0||0)-(b?.y0||0));advanceTime(10+dist*2);Game.ovPlayer={x:p.x,y:p.y};Game.pendingPath=null;Game.cityLife.currentDistrict=sid;buildOverworldMap();renderOverworldStatic();v9MaybeDrawMinimap?.(true);if(seededRandom()<.18)setTimeout(()=>triggerTravelEvent(),120)}}return true
}
