 side.querySelectorAll('[data-c]').forEach(e=>e.onclick=()=>{renderContactDossierV13(e.dataset.c);showScreen('v13-contact-screen')});side.querySelectorAll('[data-r]').forEach(e=>e.onclick=()=>followRumorV13(e.dataset.r));
