 const sec=sectorDefV13(d.sectorId),f=FACTIONS[d.faction],trust=contactTrustV13(id),band=trust>=60?'TRUSTED':trust>=25?'RELIABLE':trust>=0?'PROFESSIONAL':'DAMAGED';
