 return{color:c?factionColorV132(c.faction):(l.type==='shop'?'#e4ad4c':l.type==='clinic'?'#66d690':l.type==='safehouse'?'#f2d76b':sec?.color||'#43d7e8'),
        shape:l.type==='contact'?'circle':l.type==='shop'?'square':l.type==='clinic'?'cross':l.type==='safehouse'?'hq':'diamond'}
