 ctx.shadowBlur=0;
 if(l.type==='contact'){ctx.fillStyle=s.color;ctx.font=`800 ${Math.max(6,tile*.20)}px Orbitron`;ctx.textAlign='center';ctx.fillText((l.name||'?')[0],x,y+2)}
