 const wrap=document.querySelector('#overworld-screen .wrap').getBoundingClientRect(),vw=(wrap.width/Game.ovTile)*sx,vh=(wrap.height/Game.ovTile)*sy;ctx.strokeStyle='#43d7e8';ctx.lineWidth=1.5;ctx.setLineDash([4,3]);ctx.strokeRect(x+Game.ovCamera.x*sx,y+Game.ovCamera.y*sy,vw,vh);ctx.setLineDash([]);
