 if(Game.hoverTile){const p=worldToScreenV132(Game.hoverTile.x,Game.hoverTile.y);ctx.save();ctx.strokeStyle=isWalkableV132(Game.hoverTile.x,Game.hoverTile.y)?'#d8f7ff':'#e35c5c';ctx.lineWidth=1.4;ctx.strokeRect(p.x+1,p.y+1,tile-2,tile-2);ctx.restore()}
