   if(r>.88){ctx.fillStyle='rgba(3,8,11,.42)';ctx.fillRect(cx-t*.12,cy+t*.08,t*.24,Math.max(1,t*.06));ctx.fillStyle=world.cfg.accent+'20';ctx.fillRect(cx-t*.08,cy+t*.10,t*.16,Math.max(1,t*.02));}
