function updateCameraModeV133(){const e=document.getElementById('v133-camera-mode');if(e)e.innerHTML=`CAMERA <b>${Game.ovCamera?.follow!==false?'FOLLOW':'FREE'}</b> · ${Math.round(Game.ovTile||0)}PX`}
