 if(m.targetFaction&&Game.rep){Game.rep[m.targetFaction]=(Game.rep[m.targetFaction]||0)+(success?-1:0);if(Game.heat)Game.heat[m.targetFaction]=clampV134((Game.heat[m.targetFaction]||0)+(success?5:2),0,100)}
