const companyCallV14=(name,...args)=>{
 const fn=globalThis[name];
 if(typeof fn!=='function')throw new Error(`CompanyV14 missing legacy implementation: ${name}`);
 return fn(...args);
};
const CompanyV14=Object.freeze({
 version:'13.5',
 ensureState:(...args)=>companyCallV14('ensureCompanyStateV135',...args),
 migrateRoster:(...args)=>companyCallV14('migrateCompanyRosterV135',...args),
 dailyCost:(...args)=>companyCallV14('companyDailyCostV135',...args),
 processDay:(...args)=>companyCallV14('processCompanyDayV135',...args),
 wage:(...args)=>companyCallV14('mercWageV135',...args),
 renderPanel:(...args)=>companyCallV14('renderCompanyPanelV135',...args),
 diagnostics:(...args)=>companyCallV14('runDiagnosticsV135',...args)
});
globalThis.ChromeRequiemV14Domains ||= {};
globalThis.ChromeRequiemV14Domains.company=CompanyV14;

/* SOURCE: src/world/action-time-v14.js */
(function(root){
'use strict';
if(typeof window==='undefined'||!window.document)return;

const STEP_MINUTES=.25;
const ACTOR_STEP_INTERVAL=6;
const ACTION_COSTS=Object.freeze({
 streetStep:STEP_MINUTES,
 waitShort:15,
 waitStandard:30,
 waitLong:60,
 enterLocation:5,
 missionDeployment:30,
 emergencyExtraction:90
});

function game(){return window.ChromeRequiemCoreV5?.state||(typeof Game!=='undefined'?Game:null)}
function world(){try{return window.currentDistrictV133?.()||null}catch{return null}}
function clampMinutes(v){const n=Number(v);if(!Number.isFinite(n))return 15;return Math.max(1,Math.min(240,Math.round(n)))}
function actionCost(action,context={}){
 if(action==='route')return Math.max(0,Number(context.steps)||0)*ACTION_COSTS.streetStep;
 const value=ACTION_COSTS[action];return Number.isFinite(value)?value:null
}
function formatMinutes(minutes){
 const total=Math.max(0,Number(minutes)||0);if(total<1)return `${Math.round(total*60)} sec`;
 if(total<60)return Number.isInteger(total)?`${total} min`:`${total.toFixed(2).replace(/0+$/,'').replace(/\.$/,'')} min`;
 const h=Math.floor(total/60),m=Math.round(total%60);return m?`${h}h ${m}m`:`${h}h`
}
function routeEstimate(path){
 const p=path||game()?.pendingPath||[],steps=Math.max(0,p.length-1),minutes=actionCost('route',{steps});
 return{steps,minutes,label:formatMinutes(minutes)}
}

function wait(minutes=15){
 const g=game(),mins=clampMinutes(minutes);if(!g||g.screen!=='overworld-screen'||g._v134EventOpen)return false;
 if(g.pendingPath?.length>1){window.toast?.('Finish moving before waiting.');return false}
 const w=world(),s=window.ensureLivingStreetsStateV134?.();
 const beforeSteps=s?.stepCount||0,equivalentSteps=Math.max(1,Math.round(mins/STEP_MINUTES));
 window.advanceTime?.(mins);
 if(s){
   s.stepCount=beforeSteps+equivalentSteps;
   const actorTicks=Math.max(0,Math.floor(s.stepCount/ACTOR_STEP_INTERVAL)-Math.floor(beforeSteps/ACTOR_STEP_INTERVAL));
   if(actorTicks&&w)window.advanceStreetActorsV134?.(w,actorTicks);
 }
 if(w&&!g._v134EventOpen)window.runEncounterDirectorV134?.(false,w);
 window.updateNeighborhoodHUDV134?.();window.updateOverworldHUD?.();window.requestOverworldRenderV133?.();
 window.saveGame?.(0,true);window.toast?.(`WAITED // ${mins} MIN`);
 return true
}

function ensureWaitControl(){
 const top=document.querySelector('#overworld-screen>.topbar');if(!top)return null;
 let btn=document.getElementById('ov-wait-btn');if(btn)return btn;
 btn=document.createElement('button');btn.id='ov-wait-btn';btn.className='btn small v14-wait-btn';btn.type='button';btn.textContent='WAIT 15M';btn.title='Hold position and let 15 minutes of world time pass';
 const menu=document.getElementById('ov-menu-btn');if(menu)top.insertBefore(btn,menu);else top.appendChild(btn);
 btn.addEventListener('click',()=>wait(ACTION_COSTS.waitShort));return btn
}

function decorateRouteCard(){
 const g=game(),card=document.getElementById('v133-route-card');if(!card||!g?.pendingPath?.length)return false;
 const estimate=routeEstimate(g.pendingPath);if(!estimate.steps)return false;
 let eta=card.querySelector('.v14-route-time');
 if(!eta){eta=document.createElement('span');eta.className='v14-route-time';card.appendChild(eta)}
 const text=` · ETA ${estimate.label}`,title=`Route time cost: ${estimate.steps} street steps × ${ACTION_COSTS.streetStep} min`;
 if(eta.textContent!==text)eta.textContent=text;if(eta.title!==title)eta.title=title;
 return true
}

const prevInit=window.initOverworld;
if(typeof prevInit==='function')window.initOverworld=function(){const r=prevInit.apply(this,arguments);ensureWaitControl();requestAnimationFrame(decorateRouteCard);return r};

const routeObserver=new MutationObserver(()=>decorateRouteCard());
function observeRouteCard(){const card=document.getElementById('v133-route-card');if(card)routeObserver.observe(card,{childList:true,subtree:true,characterData:true})}

window.CR14ActionTime=Object.freeze({wait,ensureWaitControl,actionCost,formatMinutes,routeEstimate,decorateRouteCard,ACTION_COSTS,STEP_MINUTES,ACTOR_STEP_INTERVAL});
window.ChromeRequiem=window.ChromeRequiem||{};window.ChromeRequiem.modules=window.ChromeRequiem.modules||{};window.ChromeRequiem.modules.ActionTimeV14=window.CR14ActionTime;
requestAnimationFrame(()=>{ensureWaitControl();observeRouteCard();decorateRouteCard()});
})(globalThis);

