function createRuntime(deps, {version='14.0.0-alpha.1'}={}) {
  const required=['save','load','newGame','advanceTime','startMission','buildGrid','createCombatUnits','showScreen','diagnostics'];
  for (const name of required) if (typeof deps?.[name] !== 'function') throw new TypeError(`CRRuntime dependency ${name} must be a function`);
  const runtime={
    version,
    save:(slot=0,quiet=true)=>deps.save(slot,quiet),
    load:(slot=0)=>deps.load(slot),
    newGame:(name,className,background)=>deps.newGame(name,className,background),
    advanceTime:(minutes)=>deps.advanceTime(minutes),
    startMission:(mission)=>deps.startMission(mission),
    buildGrid:(mission)=>deps.buildGrid(mission),
    createCombatUnits:(mission)=>deps.createCombatUnits(mission),
    showScreen:(screenId)=>deps.showScreen(screenId),
    diagnostics:()=>deps.diagnostics()
  };
  return Object.freeze(runtime);
}

