function decorateInventoryAssets(body){
 if(!body||!window.CRAssets?.state?.manifest)return false;
 const items=window.ChromeRequiemCoreV5?.items||{};
 const byName=new Map(Object.entries(items).map(([id,v])=>[String(v?.name||'').trim(),id]));
 let replaced=0;
 for(const section of body.querySelectorAll('.inv-section')){
  const title=(section.querySelector('h3')?.textContent||'').toUpperCase();
  const group=title.includes('WEAPON')?'weapons':title.includes('ARMOR')?'armor':title.includes('CYBER')?'cyberware':null;
  if(!group)continue;
  const className=group==='weapons'?'v14-weapon-asset':group==='armor'?'v14-armor-asset':'v14-cyber-asset';
  section.querySelectorAll('.inv-slot').forEach(slot=>{
   const name=slot.querySelector('.name')?.textContent?.trim()||'',id=byName.get(name);if(!id)return;
   const src=window.CRAssets?.url?.(group,id);if(!src)return;
   slot.dataset.v14Item=id;slot.dataset.v14Group=group;
   slot.querySelectorAll(':scope > svg,:scope > img').forEach(x=>x.remove());
   const img=document.createElement('img');img.src=src;img.alt=name;img.className=className;img.decoding='async';slot.prepend(img);replaced++;
  });
 }
 return replaced;
}

function decorateInventoryLayout(body){
 if(!body)return false;
 let wrap=body.querySelector(':scope > .v14-inventory-workbench');if(wrap)return true;
 const bench=body.querySelector(':scope > .v11-bench');const sections=[...body.querySelectorAll(':scope > .inv-section')];
 if(!bench||!sections.length)return false;
 const stock=document.createElement('section');stock.className='v14-inventory-stock';
 const detail=document.createElement('aside');detail.className='v14-inventory-detail';
 const hero=body.querySelector(':scope > .v14-crew-tab-hero');
 const side=body.querySelector(':scope > .v13-side-card');
 const header=[...body.children].find(x=>x!==hero&&x!==side&&x!==bench&&!x.classList.contains('inv-section')&&!x.classList.contains('v14-inventory-workbench'));
 if(side)stock.appendChild(side);if(header)stock.appendChild(header);sections.forEach(x=>stock.appendChild(x));detail.appendChild(bench);
 wrap=document.createElement('section');wrap.className='v14-inventory-workbench';wrap.append(stock,detail);hero?.after(wrap);
 body.classList.add('v14-inventory-mode');
 return true;
}

