function decorateCombatActions(){
 const actions=document.getElementById('actions'),g=game(),u=g?.selectedUnit;if(!actions||!u)return false;
 let head=actions.querySelector(':scope > .v14-action-deck-head');if(!head){head=document.createElement('div');head.className='v14-action-deck-head';actions.prepend(head)}
 head.innerHTML=`<span>ACTION DECK</span><b>${esc(u.name||'OPERATIVE')}</b><small>${esc(u.className||'')} · AP ${esc(u.ap||0)}/${esc(u.maxAp||0)}</small>`;
 [...actions.querySelectorAll(':scope > button')].forEach((btn,i)=>{
  const label=(btn.textContent||'').trim().toLowerCase();let kind='ability';
  if(btn.classList.contains('end-turn')||label.includes('end turn'))kind='end';
  else if(btn.classList.contains('item-btn'))kind='item';
  else if(label.includes('overwatch'))kind='overwatch';
  else if(label.includes('pause'))kind='utility';
  else if(label.includes('intel'))kind='intel';
  btn.dataset.v14Kind=kind;btn.dataset.v14ActionIndex=String(i+1);
 });
 return true;
}

