function decorateCurrent(name=game()?.screen){
 if(name==='intro')return decorateIntro();
 if(name==='v13-market-screen')return decorateMarket();
 if(name==='v13-contact-screen')return decorateContact(screenContactId());
 if(name==='v13-clinic-screen')return decorateClinic();
 if(name==='combat')return decorateCombat();
 if(name==='crew')return decorateCrew();
 if(name==='charcreate')return decorateCharCreate();
 if(name==='faction-screen')return decorateFactions();
 if(name==='journal')return decorateJournal();
 if(name==='menu')return decorateMenu();
 if(name==='load-menu')return decorateLoad();
 if(name==='story')return decorateStory();
 if(name==='v10-briefing')return decorateMissionSurface(game()?.pendingMission||game()?.activeMission,'brief');
 if(name==='v10-debrief')return false;
 if(name==='v11-world-screen')return decorateWorldNetwork();
 return false;
}

