if(typeof prevTravel==='function')window.triggerTravelEvent=function(){const r=prevTravel.apply(this,arguments);requestAnimationFrame(decorateTravel);return r};
const prevBriefingPwa10=window.showMissionBriefingV10;
if(typeof prevBriefingPwa10==='function')window.showMissionBriefingV10=function(m){const r=prevBriefingPwa10.apply(this,arguments);requestAnimationFrame(()=>decorateMissionSurface(m,'brief',true));return r};
const prevDebriefPwa10=window.showDebriefV10;
if(typeof prevDebriefPwa10==='function')window.showDebriefV10=function(success,m,salvage){const r=prevDebriefPwa10.apply(this,arguments);requestAnimationFrame(()=>decorateMissionSurface(m,'debrief',success));return r};
const prevWorldNetworkPwa10=window.renderWorldNetworkV11;
if(typeof prevWorldNetworkPwa10==='function')window.renderWorldNetworkV11=function(){const r=prevWorldNetworkPwa10.apply(this,arguments);decorateWorldNetwork();return r};
