if(typeof prevShow==='function')window.showScreen=function(name){const r=prevShow.apply(this,arguments);requestAnimationFrame(()=>decorateCurrent(name));return r};

window.CR14ScenePresentation=Object.freeze({decorateIntro,decorateCharCreate,decorateLegacyVendor,decorateMarket,decorateContact,decorateClinic,decorateInventoryAssets,decorateInventoryLayout,decorateCrewTab,decorateCrew,decorateFactionCommand,decorateFactions,decorateJournalCommand,decorateJournal,decorateCompany,decorateMenu,decorateLoad,decorateStory,decorateTravel,decorateMissionSurface,decorateWorldNetwork,decorateCombatActions,decorateCombat,decorateCurrent,shopLocation,shopArt});
